-- tours — card duration + the schedule the list/checkout surfaces read
-- ---------------------------------------------------------------------------
UPDATE public.tours SET
  duration = '≈ 9 hours',
  schedule = '[{"time":"≈ 09:00–10:00","title":"Pickup (your downtown Busan hotel)","description":"Transit / Hotel Pickup"},{"time":"≈ 10:20","title":"Haedong Yonggungsa Temple","description":"Buddhist Temple / Coastal"},{"time":"≈ 11:40","title":"Cheongsapo Daritdol Observatory (glass skywalk)","description":"Coastal Observatory / Free"},{"time":"≈ 12:30","title":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","description":"Coastal Ride / Ticket optional"},{"time":"≈ 13:25","title":"Lunch (local restaurant near Haeundae/Mipo)","description":"Local Meal"},{"time":"≈ 14:10","title":"Haeundae Beach","description":"Beach / Free"},{"time":"≈ 15:10","title":"Gamcheon Culture Village","description":"Cultural Village / Mural Art"},{"time":"≈ 16:30","title":"Dakbatgol Mural Village & Wish-Stairs Monorail","description":"Mural Village / Free monorail"},{"time":"≈ 17:10","title":"Drop-off (4 points across central Busan)","description":"Drop-off — Sequential Central Stations"}]'::jsonb,
  pickup_points_count = 1,
  dropoff_points_count = 4,
  updated_at = NOW()
WHERE slug = 'busan-small-group-yonggungsa-skycapsule-gamcheon-tour';

-- ---------------------------------------------------------------------------
-- locale = en
-- ---------------------------------------------------------------------------
UPDATE public.tour_product_pages SET
  duration_label = '≈ 9 hours',
  stops_count = 9,
  detail_payload = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(detail_payload, '{"seo"}', '{"pageTitle":"Busan Small-Group Tour: Yonggungsa, Sky Capsule, Gamcheon | AtoC Korea","metaDescription":"9-hour Busan small-group day tour, hotel pickup: Haedong Yonggungsa Temple, Cheongsapo Daritdol glass skywalk, Blueline Sky Capsule (ticket optional), Gamcheon Culture Village, Dakbatgol mural village & monorail.","title":"Busan Sea Temple, Sky Capsule & Culture Villages Small-Group Tour | AtoC","description":"Busan small-group day tour: Haedong Yonggungsa → Cheongsapo Daritdol Observatory → Blueline Park Sky Capsule (ticket included/excluded — your choice) → lunch → Gamcheon Culture Village → Dakbatgol Mural Village & wish-stairs monorail.","primaryKeywords":["Busan small group tour","Haedong Yonggungsa tour","Blueline Park Sky Capsule","Gamcheon Culture Village tour","Cheongsapo Daritdol Observatory"],"ogImage":"https://www.atockorea.com/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp"}'::jsonb, true), '{"catalog_card"}', '{"slug":"busan-small-group-yonggungsa-skycapsule-gamcheon-tour","title":"Busan Small-Group: Sea Temple, Sky Capsule & Culture Villages","subtitle":"Small-group day tour of Busan''s coastal icons and hillside villages — Haedong Yonggungsa seaside temple, the Cheongsapo Daritdol glass skywalk, the Blueline Park Sky Capsule ride (ticket optional at booking), Gamcheon Culture Village, and the quiet Dakbatgol mural village with its wish-stairs monorail.","region":"Busan","duration":"≈ 9 hours","stopsCount":9,"rating":0,"reviewCount":0,"badges":["Small group","Busan","Sky Capsule","Coastal","Culture villages"],"tags":["Small group","Busan","Sky Capsule","Coastal","Culture villages","First-time friendly"],"heroImage":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","thumbnail":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","priceLabel":"","shortCardDescription":"A small-group Busan day built around the coast and the hillside villages: Haedong Yonggungsa seaside temple in its quiet morning window, the free glass-floor Daritdol Observatory at Cheongsapo, the Blueline Park Sky Capsule ride from Cheongsapo to Mipo (ticket included or excluded — choose at booking), lunch, Gamcheon Culture Village, and the little-known Dakbatgol mural village where a free monorail glides up the ''wish stairs''. Every anchor except the optional capsule is free admission."}'::jsonb, true), '{"hero"}', '{"imageUrl":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","imagePosition":"center 40%","images":["/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp"],"tagline":"Busan''s seaside temple at its quiet hour, a glass skywalk over the sea, a pastel capsule ride down the coast, and two hillside villages — one famous, one still local","pills":["Small group","Busan","First-time friendly"],"meta":{"duration":"≈ 9 hours (09:00 hotel pickup, ≈ 17:50 last central drop)","region":"Busan","stops":"9 stops","rating":0,"ratingStars":0}}'::jsonb, true), '{"itineraryStops"}', '[{"number":1,"time":"≈ 09:00–10:00","duration":"60 min","name":"Pickup (your downtown Busan hotel)","category":"Transit / Hotel Pickup","description":"Door-to-door pickup at your hotel in central Busan, between **09:00 and 10:00**. Your exact time is confirmed by WhatsApp the evening before, once the driver has the day''s hotel list and can order the run efficiently — guests on the Haeundae side are usually collected last, because the coach leaves the city heading northeast toward Gijang-gun for the first stop.\n\nThe supported area covers the central hotel clusters: **Seomyeon**, **Nampo-dong / Busan Station**, and **Haeundae / Marine City**. If your hotel sits outside that area, the guide names the nearest meeting point when the booking is confirmed.\n\nPlease wait in the lobby 5 minutes before your confirmed time. Transit from the last pickup to Haedong Yonggungsa is about 30–40 minutes depending on traffic.","image":null,"highlights":["Door-to-door pickup at central Busan hotels, 09:00–10:00","Exact time confirmed by WhatsApp the evening before","Coach is small-group (max ~14 pax)","Printed Korean-English itinerary card distributed at pickup"],"timeUsed":["Hotel pickups across central Busan (~40 min)","Drive northeast to Gijang-gun (~20 min)"],"whyOnRoute":"Hotel pickup removes the morning transfer entirely — no early subway ride, no hunting for the right station exit. The run is ordered west→east so the coach finishes near Haeundae and leaves the city already pointed at Gijang and the day''s first stop.","_poi_meta":{"match":"transit_only","poi_key":"OPS_busan_hotel_pickup_central","sources":["AtoC Korea operations"],"verified":true,"verified_date":"2026-08-05"},"images":[],"imageCredits":[],"galleryItems":[],"_role":"pickup"},{"name":"Haedong Yonggungsa Temple","time":"≈ 10:20","number":2,"category":"Buddhist Temple / Coastal","duration":"60 min","timeUsed":["Coach drop-off + walk through vendor lane to entry plaza (~10 min)","Twelve Zodiac Generals + No-Accident Pagoda (~10 min)","108 stairs descent + Daeungjeon main hall + seaside terraces (~30 min)","Haesu Gwaneum statue viewpoint + photo time (~15 min)","Walk back up + reassemble at coach (~10 min)"],"_poi_meta":{"match":"exact","poi_key":"haedong_yonggungsa","sources":["Visit Busan","VisitKorea","Wikipedia","Culture Trip","Korean Temple Guide","Korea Tourism Organization Official"],"verified":true,"kb_version":"1.24","verified_date":"2026-04-29"},"highlights":["**Founded 1376** by Buddhist master Naong Hyegeun (originally ''Bomunsa'')","One of very few major Korean temples set on the seaside (most are in mountains)","Renamed **Haedong Yonggungsa in 1974** after Monk Jeong-am''s dragon-Goddess vision","**108 stone stairs** = Buddhism''s 108 delusions of the mind","**12 Sibiji-shin (Zodiac Generals)** at entry; ''**No-Accident Pagoda**'' coin shrine","**Haesu Gwaneum Daebul** (Sea Goddess of Mercy) — most photographed cliff view","Daeungjeon main hall restored in 1970 with attention to original colors","Hours daily 04:30-19:20, FREE admission; Buddha''s Birthday (May) lantern festival","**Stone-pillar Buddhist 12 Sibiji-shin Zodiac Generals lineup at the temple gate** — unique among Korean coastal temples"],"smartNotes":{"tip":"Side doors for entering halls (front door reserved for monks); Buddha''s Birthday (Apr–May) brings the lantern display; arrive before 10:30 to avoid the worst tour-bus crowds","photo":"Sunrise rock at the seaward edge; stairs next to Daeungjeon Hall give the classic ocean-and-temple frame; Haesu Gwaneum statue from the upper cliff gives the wide-angle temple-and-East-Sea view","facilities":"Souvenir/snack stalls and small cafe at upper plaza; coastal trail leads further along the rocks"},"whyOnRoute":"**The route''s iconic opener — Busan''s most-photographed temple in its quiet window.** The 10:20 arrival lands before the major tour-bus surge (typically from 11:00), so the 108-stair descent and the Haesu Gwaneum viewpoint are still walkable without queuing. Its Gijang cliff-top location also starts the day at the route''s far northeast point, so everything after flows one-way down the coast — Cheongsapo next, then the capsule ride toward the city — with no backtracking.","convenience":{"parking":"Haedong Yonggungsa Parking Lot (paid, per Visit Busan official)","restroom":"Available near main entrance and inside complex"},"description":"**Haedong Yonggungsa (해동 용궁사) — Korea''s most famous seaside Buddhist temple** — perches on the rocky cliffs of Gijang-gun on Busan''s northeastern coast, one of the very few major Korean temples NOT set in the mountains. Originally founded in **1376 during the Goryeo Dynasty by the great Buddhist teacher Naong Hyegeun (나옹 혜근, 1320-1376)** — a royal consultant and master who would help shape Korean Buddhism into the early Joseon era. \n\nPer legend, Naong was practicing asceticism at Bunhwangsa Temple in Gyeongju during a national drought; the East Sea god appeared to him in a dream and told him that building a temple on Bongrae Mountain (the original name of this seaside cliff) would restore the kingdom''s prosperity. \n\nNaong founded the temple and named it **Bomunsa**, dedicated to Gwanseum-bosal (관세음보살, the Bodhisattva of Compassion). The temple was destroyed in the **Japanese Imjin Invasion of 1592** and lay in ruins for over 300 years until **Monk Ungang of Tongdosa Temple began reconstruction in the early 1930s**. \n\nThe current name, **Haedong Yonggungsa (Korean Dragon Palace Temple)**, dates only to **1974** — when Head Monk Jeong-am, during a 100-day prayer (jeong-geon kido), had a vision of the Goddess of Mercy descending on the back of a dragon, emanating multicolor light. \n\nThe temple was renamed to honor this vision. The visit follows the temple''s signature processional path: through the row of **12 Sibiji-shin (Twelve Zodiac Generals)** at the entry plaza, past the **7-story ''No-Accident Pagoda''** (where drivers leave coin offerings under a stone wheel-shrine), down the famous **108 stone stairs** (representing the 108 delusions of the Buddhist mind) through a small bamboo grove, and out onto the seaside terraces and Daeungjeon main hall. \n\nThe **Haesu Gwaneum Daebul** (Sea-Goddess of Mercy statue) on the upper cliff is the most photographed view, framing both the temple rooftops and the East Sea. \n\nHours **04:30-19:20 daily, last entry 18:50, FREE admission**. **Buddha''s Birthday (May)** brings Yeondunhoe lantern festival displays.","visitBasics":{"hours":"Daily 04:30–19:20 (last admission 18:50)","closed":"Open year-round","walking":"Moderate — 108 steps through pine grove, multiple seaside terraces and stairs","admission":"Free; private-car parking is paid"},"image":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","images":["/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp"],"imageCredits":[{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 1","alt":"Haedong Yonggungsa Temple — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 2","alt":"Haedong Yonggungsa Temple — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 3","alt":"Haedong Yonggungsa Temple — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 4","alt":"Haedong Yonggungsa Temple — gallery image 4"},{"id":5,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 5","alt":"Haedong Yonggungsa Temple — gallery image 5"},{"id":6,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 6","alt":"Haedong Yonggungsa Temple — gallery image 6"}]},{"number":3,"time":"≈ 11:40","duration":"40 min","name":"Cheongsapo Daritdol Observatory (glass skywalk)","category":"Coastal Observatory / Free","description":"The **Cheongsapo Daritdol Observatory (청사포 다릿돌전망대)** is a **72.5-meter skywalk curving out over the sea about 20 meters above the water**, opened in August 2017 on the coastal cliff between Cheongsapo and Songjeong. Its name comes from the **daritdol — the five ''stepping-stone'' reef rocks** that dot the sea below the deck, said to step toward the horizon like a bridge. The far section of the deck floor is **glass**, with shoe covers provided to protect (and trust!) the panes as the swell rolls beneath your feet. Admission is **free**. Back at the village, the **Cheongsapo Twin Lighthouses** (one red, one white) and the little station crosswalk made famous by its Slam-Dunk-style anime frame are a short stroll away.","image":null,"highlights":["**72.5-m skywalk, ~20 m above the sea** — opened August 2017, FREE","Named for the five **daritdol ''stepping-stone'' reefs** visible below the deck","**Glass-floor section** at the seaward end (shoe covers provided)","**Cheongsapo Twin Lighthouses** (red + white) a short stroll away","Cheongsapo is one of Busan''s **eight scenic views** — a working fishing village","Anime-famous station crosswalk photo spot"],"timeUsed":["Coach drop-off + walk to the skywalk entrance (~5 min)","Skywalk walk-out + glass-floor section (~20 min)","Twin lighthouses / crosswalk photo stroll (~10 min)","Reassemble for the capsule station (~5 min)"],"whyOnRoute":"**The free thrill between the temple and the capsule.** Daritdol gives the day its over-the-sea moment — a glass floor with swell rolling underneath — without a ticket, and it sits directly on the Cheongsapo cliff so it chains into the Sky Capsule boarding just minutes away. Seeing the coastline from the fixed skywalk first makes the moving capsule view read differently ten minutes later.","_poi_meta":{"match":"authored","poi_key":"cheongsapo_daritdol_observatory","sources":["Visit Busan","Busan Metropolitan City Tourism","Blue Line Park official"],"verified":false,"verified_date":"2026-08-04"},"smartNotes":{"tip":"Windy days close the deck occasionally — the guide checks conditions and reorders the Cheongsapo cluster if needed","photo":"Shoot down through the glass at the daritdol reefs; the deck''s curve from the shore path gives the best wide shot","facilities":"Cafes and seafood stalls in Cheongsapo village below"},"convenience":{"parking":"Coach stop at Cheongsapo village; short walk to the deck","restroom":"Public restrooms near Cheongsapo station"},"visitBasics":{"hours":"Open access; observatory staffed roughly 09:00–18:00 (season/weather dependent)","closed":"May close temporarily in high wind or storm conditions","walking":"Flat walk-out on the deck; a short slope from the village","admission":"FREE (shoe covers provided for the glass section)"},"images":[],"imageCredits":[],"galleryItems":[]},{"number":4,"time":"≈ 12:30","duration":"50 min","name":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","category":"Coastal Ride / Ticket optional","description":"The **Sky Capsule** is the signature ride of **Haeundae Blueline Park**, the 2020 eco-redevelopment of the disused Donghae Nambu coastal railway: **pastel 4-seat cabins gliding 2.3 km along an elevated rail 7–10 meters above the coastline** between Cheongsapo and Mipo, with the sea on one side the whole way (~30 minutes). We board at **Cheongsapo and ride toward Mipo**, where the coach is already waiting — so the ride doubles as the day''s transfer down the coast. **The capsule ticket is optional and chosen at booking**: with the ticket-included option we pre-reserve capsules for your group (pricing is per capsule: about ₩30,000 for 2 / ₩39,000 for 3 / ₩44,000 for 4, one-way); with the base option you can walk the **free Green Railway boardwalk** — the award-winning 2.3 km wooden coastal path under the same rail — or simply ride the coach to Mipo.","image":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","highlights":["**Pastel 4-seat capsules on an elevated coastal rail** — Blueline Park''s signature ride (opened 2020)","**Cheongsapo → Mipo, 2.3 km / ~30 min**, sea views the whole way","**Ticket included or excluded — your choice at booking** (per-capsule pricing ≈ ₩30,000 for 2 / ₩39,000 for 3 / ₩44,000 for 4, one-way)","Non-riders: **free Green Railway boardwalk** along the same coast, or the coach to Mipo","The ride ends where lunch begins — Mipo is a short walk from Haeundae''s food streets","Runs in normal rain; pauses only in high wind"],"timeUsed":["Boarding at Cheongsapo station (~15 min)","Sky Capsule ride Cheongsapo → Mipo (~35 min)"],"whyOnRoute":"**The ride that is also the transfer.** Boarding at Cheongsapo right after the skywalk means the capsule carries you down the exact coastline you just looked out over — and it deposits you at Mipo, where the coach and the lunch streets are already waiting. Nothing about the day detours for it: skip the ticket and the coach or the free boardwalk cover the same leg.","_poi_meta":{"match":"partial","poi_key":"cheongsapo_blue_line_park","sources":["Blue Line Park official","Visit Busan","Busan Metropolitan City Tourism"],"verified":true,"kb_version":"1.24","verified_date":"2026-08-04"},"smartNotes":{"tip":"Sunset and weekend slots sell out 1–2 weeks ahead — choose the ticket-included option at booking and we reserve them for you","photo":"Sit on the sea side (right side heading to Mipo); the curve past Dalmaji Tunnel is the signature frame","facilities":"Cafes and convenience store at Mipo plaza; ticket kiosks at both stations"},"convenience":{"parking":"Coach meets the group at Mipo station plaza","restroom":"At both Cheongsapo and Mipo stations"},"visitBasics":{"hours":"≈ 09:30–18:30 (extended into the evening in peak season)","closed":"Weather-dependent; high wind pauses operations","walking":"Flat station platforms; boardwalk alternative is 2.3 km (~30 min) on wood decking","admission":"Per capsule, one-way: ≈ ₩30,000 (2 pax) / ₩39,000 (3) / ₩44,000 (4) — included-ticket option available at booking"},"images":["/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","/images/tours/cheongsapo-blue-line/blueline-tram-cherry-sea.webp","/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-12-53-19.webp"],"imageCredits":[{"url":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","source":"atoc-korea"},{"url":"/images/tours/cheongsapo-blue-line/blueline-tram-cherry-sea.webp","source":"atoc-korea"},{"url":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","source":"atoc-korea"},{"url":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-12-53-19.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","location":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","caption":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — photo 1","alt":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/cheongsapo-blue-line/blueline-tram-cherry-sea.webp","location":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","caption":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — photo 2","alt":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","location":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","caption":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — photo 3","alt":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-12-53-19.webp","location":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","caption":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — photo 4","alt":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — gallery image 4"}]},{"name":"Lunch (local restaurant near Haeundae/Mipo)","time":"≈ 13:25","number":5,"category":"Local Meal","duration":"45 min","timeUsed":["Walk from Mipo station to restaurant (~5 min)","Lunch (~35 min)","Reassemble at coach (~5 min)"],"_poi_meta":{"match":"lunch_placeholder","poi_key":"OPS_busan_lunch","sources":["Visit Busan","Busan Metropolitan Government cuisine guide"],"verified":true,"kb_version":"1.15","verified_date":"2026-04-29"},"highlights":[],"whyOnRoute":"**The natural break between the coast and the villages.** The capsule ride ends at Mipo at lunchtime, and Haeundae''s food streets are a short walk from the station — no extra driving to reach a good meal. Fueling up here sets up the afternoon''s two hillside villages, where the walking is at its most vertical.","description":"About a 45-minute lunch near Mipo/Haeundae right after the Sky Capsule arrives. Typical guide-recommended options: **dwaeji-gukbap (돼지국밥)** — Busan''s signature pork-broth rice soup born in the Korean-War refugee era (~₩10,000), **milmyeon** cold wheat noodles, or a harborside seafood table. Lunch is not included (≈ ₩10,000–15,000), so you can pick what suits your appetite and budget."},{"number":6,"time":"≈ 14:10","duration":"20 min","name":"Haeundae Beach","category":"Beach / Free","description":"**Haeundae Beach (해운대해수욕장)** is Korea''s best-known stretch of sand — about **1.5 km** of shoreline curving between Dongbaekseom island at the west end and Mipo at the east, backed by the Marine City skyline. The Sky Capsule sets you down at Mipo, which is simply the eastern end of this beach, so the stop costs the day no extra driving.\n\nTwenty minutes is a photo-and-toes stop, not a swim: walk out onto the sand, shoot the skyline, and rejoin the coach. In July and August the beach is at its busiest and the parasol rows are up; the rest of the year it is wide, quiet and walkable. Free, open at all hours.","image":null,"highlights":["**Korea''s most famous beach** — ~1.5 km of sand, FREE and open 24h","Marine City skyline backdrop from the water''s edge","Dongbaekseom island and Nurimaru APEC House at the far west end","Directly at Mipo, where the Sky Capsule ride ends — no extra transfer"],"timeUsed":["Walk onto the sand from Mipo (~5 min)","Beach and skyline photos (~10 min)","Reassemble at the coach (~5 min)"],"whyOnRoute":"The capsule lands at Mipo, which is the beach''s eastern end — so Busan''s most famous view is a five-minute walk away and costs the day nothing. It is deliberately short: enough to stand on the sand and photograph the skyline before the afternoon turns to the hillside villages.","_poi_meta":{"match":"authored","poi_key":"haeundae_beach","sources":["Visit Busan","Busan Metropolitan City Tourism"],"verified":false,"verified_date":"2026-08-05"},"visitBasics":{"hours":"Open 24 hours","closed":"Never","walking":"Flat sand and a paved promenade","admission":"FREE"},"images":[],"imageCredits":[],"galleryItems":[]},{"name":"Gamcheon Culture Village","time":"≈ 15:10","number":7,"category":"Cultural Village / Mural Art","duration":"60 min","timeUsed":["Coach drop-off at Public Parking Lot 2 + walk to entrance (~5 min)","Tourist Information Center + Stamp Map purchase (~10 min)","Sky Garden viewpoint + Little Prince bench (~25 min)","Alley walk past murals + small cafe pause (~25 min)","Reassemble at coach (~10 min)"],"_poi_meta":{"match":"exact","poi_key":"gamcheon_culture_village","sources":["Wikipedia","CNN","Visit Busan","Hapskorea","Columban Society","Lifeguin","Busan Cultural Foundation"],"verified":true,"kb_version":"1.24","verified_date":"2026-04-29"},"highlights":["**''Korea''s Machu Picchu'' / ''Korea''s Santorini''** — UN-HABITAT Asian Townscape Award 2012","Origins: **1920s-1930s** Busan administration relocation + **1955 Taegeukdo refugees** (~800 families)","**Taegeukdo philosophy of ''allowing others to prosper''** = no house blocks the view behind it","**2009 ''Dreaming of Machu Picchu'' + 2010 ''Miro Miro''** Ministry of Culture public-art projects","**''Little Prince and Fox'' bench** at Sky Garden — the village''s most-photographed spot","**~1.4 million visitors annually** since the public-art revitalization","**Living residential community** — quiet voices, no drones, no flash into homes","Free village entry; optional Stamp Map ~₩2,000","**UN-HABITAT Asian Townscape Award 2012** — recognition of the 2009 ''Dreaming of Machu Picchu'' art project that transformed the 1955 Taegeukdo refugee settlement into Busan''s signature mural village"],"smartNotes":{"tip":"Residents live here — keep voices down, no drones, take rubbish with you; wear grippy shoes for the steep lanes; afternoon golden hour ~16:00-17:00 is the village''s best light","photo":"Little Prince and Fox bench (long queue) and Haneul Maru / Sky Garden Observatory for the sweeping rainbow-roof and bay view","facilities":"Hanbok rental, craft workshops, Korean candy stalls, cafes; small village museum at the entrance; the stamp map is the easiest way to navigate"},"whyOnRoute":"**The afternoon''s headline village — Busan''s pastel amphitheater.** After the coastal morning, the day crosses to the west hillsides where Gamcheon''s Korean-War-era refugee terraces, reborn as an art village in 2009, stack in candy colors above the sea. The 90-minute loop covers the viewpoints, the Little Prince ledge, and time to wander the alleys — and it pairs deliberately with quiet Dakbatgol just after, so you see both the famous village and the local one the buses skip.","convenience":{"parking":"Gamcheon Public Parking Lot 2 (paid)","restroom":"Public restrooms at the Tourist Information Center and around the main viewpoints"},"description":"**Gamcheon Culture Village (감천문화마을)** — nicknamed both **''Korea''s Machu Picchu''** and **''Korea''s Santorini''** — is a hillside neighborhood in Saha-gu, west Busan, whose pastel-painted houses cascade down in stepped rows over the slope. \n\nThe settlement began in the **1920s-1930s** when the Busan administration relocated working-class residents away from the port. The village''s character was set in **1955** when **~800 families (about 4,000 people) of the Taegeukdo religious community** — a uniquely Korean syncretic religion blending Buddhist, Confucian, and yin-yang elements, founded by **Jo Cheol-je** during the Japanese colonial period — settled here as Korean War refugees fleeing the North. \n\nThe Taegeukdo philosophy of ''**allowing others to prosper**'' directly shaped the village''s most distinctive feature: houses are intentionally tiered so that **no roof blocks the view of the house behind it**, with the entire community visible to the sky and the sea. Gamcheon remained one of Busan''s poorest neighborhoods until **2009**, when the Korean Ministry of Culture launched the **''Dreaming of Machu Picchu in Busan''** public-art revitalization project, followed by the **''Miro Miro'' (maze) project in 2010** — adding 22+ commissioned murals, sculptures, and art installations including the iconic **''Little Prince and Fox'' bench** at the Sky Garden viewpoint. \n\nGamcheon won the **2012 UN-HABITAT Asian Townscape Award** and now welcomes **~1.4 million visitors annually**. The visit follows the village''s signature stamp-map walking route: from the entrance at the **Tourist Information Center**, up to **Sky Garden viewpoint** for the panoramic rainbow-roof shot, then down through the labyrinthine alleys past murals, hanbok rental shops, craft workshops, and small cafes. \n\n**The village is a living residential community** — quiet voices required, no drones, no flash photography into homes, and rubbish carried out. \n\nHours **09:00-18:00 Mar-Oct / 09:00-17:00 Nov-Feb (info center)**; **village itself open 24h, FREE entry**.","visitBasics":{"hours":"Daily 09:00–18:00 (Mar–Oct) / 09:00–17:00 (Nov–Feb); some shops/cafes keep their own hours","closed":"Open year-round (a living residential community)","walking":"Strenuous — very steep alleys and stairs; not stroller- or wheelchair-friendly in many sections","admission":"Free village entry; optional Stamp Map ≈ 2,000 KRW"},"image":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","images":["/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp"],"imageCredits":[{"url":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 1","alt":"Gamcheon Culture Village — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 2","alt":"Gamcheon Culture Village — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 3","alt":"Gamcheon Culture Village — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 8","alt":"Gamcheon Culture Village — gallery image 8"}]},{"number":8,"time":"≈ 16:30","duration":"30 min","name":"Dakbatgol Mural Village & Wish-Stairs Monorail","category":"Mural Village / Free monorail","description":"**Dakbatgol (닥밭골)** is a hillside village in Busan''s Seo-gu whose name remembers the **paper-mulberry (dak) fields** that once supplied Korea''s traditional hanji paper-makers. Like Gamcheon it climbs a steep slope in tight lanes — but it never became a tour-bus stop, so its **mural alleys, hanji-motif artwork, and lookout points stay quiet and local**, laundry lines and all. The village''s landmark is the **''wish stairs'' (소망계단)** — a long, steep stair street painted with murals — and the **free incline monorail** that glides beside it, installed so the village''s elderly residents could reach their homes; visitors ride it too, turning the steepest climb of the afternoon into a slow-motion viewpoint. It is the deliberately human-scale counterpoint to Gamcheon''s fame, ten minutes before drop-off territory.","image":null,"highlights":["**Quiet mural village** — Gamcheon''s local counterpart with almost no crowds","Named for the **paper-mulberry (dak) fields** of Busan''s hanji paper heritage","**''Wish stairs'' (소망계단)** — a steep mural stair street","**Free incline monorail** beside the stairs — built for village elders, open to visitors","Hillside lookouts over the old harbor quarter","FREE admission; a genuinely lived-in neighborhood — keep voices low"],"timeUsed":["Coach drop-off + mural lane walk (~10 min)","Wish-stairs monorail ride up + lookout (~10 min)","Descent + photo time (~5 min)","Reassemble at coach (~5 min)"],"whyOnRoute":"**The quiet closer the buses skip.** After Gamcheon''s crowds, Dakbatgol shows the same hillside Busan at living volume — murals, wish stairs, and a monorail that does the climbing. It closes the villages chapter ten minutes from the Nampo drop-off zone, so the day ends deep in local texture rather than in traffic.","_poi_meta":{"match":"authored","poi_key":"dakbatgol_mural_village","sources":["Visit Busan","Busan Seo-gu Office"],"verified":false,"verified_date":"2026-08-04"},"smartNotes":{"tip":"This is a lived-in village, not a theme park — keep voices low in the alleys and don''t photograph into open doorways","photo":"Shoot the wish stairs from the bottom with the monorail track running beside; the top lookout frames the harbor quarter","facilities":"Small cafes near the entrance; more options at Nampo-dong after drop-off"},"convenience":{"parking":"Coach stop at the village entrance","restroom":"Public restroom near the village entrance"},"visitBasics":{"hours":"Open village; monorail runs daytime hours (≈ 09:00–18:00, weather-dependent)","closed":"Monorail may pause for maintenance or storm weather — the stairs remain open","walking":"Steep lanes and stairs; the monorail covers the steepest section","admission":"FREE (village and monorail)"},"images":[],"imageCredits":[],"galleryItems":[]},{"number":9,"time":"≈ 17:10","duration":"≈ 70 min total","name":"Drop-off (4 points across central Busan)","category":"Drop-off — Sequential Central Stations","description":"**Drop-offs run in sequence from the west side back east**: **Nampo-dong / Jagalchi area (~17:10)** — step off here for Busan''s best evening food streets and the BIFF Square night scene; **Busan Station (~17:30)** for KTX connections; **Seomyeon (~17:50)** for the central hotel cluster; and **Haeundae (~18:20)** last. Choose your drop point with the guide during the afternoon — staying on to Haeundae is the longest ride but lands you by the beach for the evening.","image":null,"highlights":[],"timeUsed":["Nampo-dong / Jagalchi area (~17:10)","Busan Station (~17:30)","Seomyeon (~17:50)","Haeundae (~18:20)"],"whyOnRoute":"Dakbatgol sits ten minutes from Nampo-dong, so the drop sequence starts almost immediately after the last stop — no dead transfer time. The west-to-east order covers KTX travelers (Busan Station), central hotels (Seomyeon), and beach hotels (Haeundae) without backtracking.","_poi_meta":null,"images":[],"imageCredits":[],"galleryItems":[]}]'::jsonb, true), '{"routeFlowStops"}', '[{"name":"Pickup (your downtown Busan hotel)","type":"origin","theme":"Departure"},{"name":"Haedong Yonggungsa Temple","type":"primary","theme":"Seaside temple"},{"name":"Cheongsapo Daritdol Observatory (glass skywalk)","type":"secondary","theme":"Glass Skywalk"},{"name":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","type":"primary","theme":"Sky Capsule"},{"name":"Lunch (local Busan restaurant)","type":"meal","theme":"Meal"},{"name":"Haeundae Beach","type":"secondary","theme":"Beach"},{"name":"Gamcheon Culture Village","type":"primary","theme":"Art village"},{"name":"Dakbatgol Mural Village & Wish-Stairs Monorail","type":"secondary","theme":"Mural Village"},{"name":"Drop-off (4 points across central Busan)","type":"return","theme":"Return"}]'::jsonb, true), '{"routePhases"}', '[{"phase":"Coastal morning","duration":"≈ 3.5 hours","description":"Door-to-door hotel pickup across central Busan (09:00–10:00), then Haedong Yonggungsa Temple before the tour-bus surge, and on to Cheongsapo''s Daritdol glass skywalk."},{"phase":"Sky Capsule, lunch & beach","duration":"≈ 2 hours","description":"The pastel Sky Capsule ride from Cheongsapo to Mipo (ticket optional — non-riders take the coach or walk the Green Railway boardwalk), lunch near Haeundae, then twenty minutes on Haeundae Beach itself."},{"phase":"Two hillside villages","duration":"≈ 2 hours","description":"Gamcheon Culture Village''s photo loop (60 min), then the quiet Dakbatgol mural village and its free wish-stairs monorail (30 min)."},{"phase":"Central close","duration":"≈ 1 hour","description":"Sequential drop-offs: Nampo-dong, Busan Station, Seomyeon, then Haeundae."}]'::jsonb, true), '{"routeShapeIntro"}', '{"title":"How this Busan day moves","subtitle":"East coast first: the seaside temple in its quiet morning window, then the Cheongsapo cluster — glass skywalk, twin lighthouses — where the Sky Capsule ride itself becomes the transfer down the coast to Mipo. After lunch and a short stop on Haeundae Beach the day crosses to Busan''s west hillsides for two villages in two moods: Gamcheon''s world-famous color, then Dakbatgol''s quiet murals, where a free monorail glides up the ''wish stairs''. Central drop-offs close the loop, 09:00 to about 18:20."}'::jsonb, true), '{"whyTourWorks"}', '{"bestFor":["First-time Busan visitors","Couples and photo-focused travelers","Adult families and friends groups","Travelers who want the coast AND the villages in one day"],"lessIdealFor":["Travelers who want minimal walking or no slopes","Stroller-heavy groups (village lanes and stairs)","Night-view seekers — this is a daytime route"],"routeLogicSections":[{"title":"Pacing & geography","icon":"route","iconBg":"bg-sky-50/80","iconColor":"text-sky-600","items":[{"label":"The temple at its quiet window","detail":"Haedong Yonggungsa is Busan''s most-photographed temple and its tour-bus surge starts around 11:00. Arriving at about 10:20 keeps the 108-stair descent and the Haesu Gwaneum viewpoint walkable without queuing."},{"label":"The capsule ride IS the transfer","detail":"From Cheongsapo the pastel Sky Capsule glides 2.3 km down the coast to Mipo — so the ride replaces a coach hop instead of adding a detour. Guests who skip the ticket ride the coach to Mipo or walk the free Green Railway boardwalk along the same coastline."},{"label":"Two hillside villages, two moods","detail":"Gamcheon is Busan''s world-famous pastel amphitheater; Dakbatgol, ten minutes away, is its quiet local counterpart — mural lanes with almost no crowds, where a free incline monorail built for village elders carries you up the ''wish stairs''."},{"label":"Free-admission anchors, one optional ticket","detail":"Yonggungsa, the Daritdol skywalk, Gamcheon, and Dakbatgol (monorail included) are all free. The only paid attraction of the day is the Sky Capsule — and it is your choice at booking: ticket included, or excluded if you''d rather walk the boardwalk."}]}]}'::jsonb, true), '{"practicalAccordionItems"}', '[{"id":"pickup","title":"Pickup & drop-off","preview":"Pickup is door-to-door at your hotel in central Busan — Seomyeon, Nampo-dong / Busan Station, Haeundae / Marine City — between 09:00 and 10:00. Your exact time is confirmed by WhatsApp the evening before.","content":["Pickup is door-to-door at your hotel in central Busan — Seomyeon, Nampo-dong / Busan Station, Haeundae / Marine City — between 09:00 and 10:00. Your exact time is confirmed by WhatsApp the evening before.","Drop-offs in sequence: Nampo-dong/Jagalchi ≈17:10, Busan Station ≈17:30, Seomyeon ≈17:50, Haeundae ≈18:20.","Your effective tour length depends on your pickup time and where you get off — about 7¼ hours at the shortest (10:00 pickup, Nampo-dong drop) and about 9¼ at the longest (09:00 pickup, Haeundae drop)."]},{"id":"what-to-bring","title":"What to wear & bring","preview":"Comfortable walking shoes with grip — Gamcheon''s hillside alleys and Yonggungsa''s 108…","content":["Comfortable walking shoes with grip — Gamcheon''s hillside alleys and Yonggungsa''s 108 stairs both need traction.","Light layer for AC vehicle and the sea breeze at Yonggungsa.","Camera or smartphone (Gamcheon and Cheongsapo are the photo highlights).","Cash or card for lunch (₩10,000–₩20,000), the optional Sky Capsule / Beach Train tickets at Cheongsapo, and the optional Busan Tower observatory."]},{"id":"weather-policy","title":"Weather policy","preview":"Year-round operation.","content":["Year-round operation.","Light rain: tour runs as scheduled — Yonggungsa under rain has its own atmosphere, and Gamcheon''s alleys remain navigable.","Heavy rain or storms: the guide may adjust the route because Yonggungsa''s lower temple area can become slippery and Gamcheon''s stairs can be unsafe.","Typhoon-level weather: full refund or rebooking is offered."]},{"id":"inclusions","title":"What''s included","preview":"Small-group mini-coach (≈12 guests max), certified English-speaking guide, fuel/tolls/parking.","content":["Small-group mini-coach (≈12 guests max), certified English-speaking guide, fuel/tolls/parking.","All anchor attractions are FREE admission: Haedong Yonggungsa, Cheongsapo Daritdol Observatory, Gamcheon Culture Village, Dakbatgol Mural Village (wish-stairs monorail free).","Sky Capsule ticket: choose at booking — included (we pre-reserve capsules for your group; 2-per-capsule basis) or excluded (walk the free Green Railway boardwalk or ride the coach to Mipo).","Not included: lunch (≈ ₩10,000–15,000), drinks, personal spending, tips."]},{"id":"language","title":"Language","preview":"Primary tour language: English.","content":["Primary tour language: English.","Chinese-speaking guide available on request — book 3+ days ahead.","Korean is spoken throughout the day for menus, signage, and stall interactions; the guide handles translation."]},{"id":"walking","title":"Walking & terrain","preview":"Moderate difficulty with short demanding bursts.","content":["Moderate difficulty with short demanding bursts.","Yonggungsa has 108 stone stairs down and back up.","The Daritdol skywalk is flat (glass floor, shoe covers provided).","Sky Capsule stations are flat with a few platform steps.","Gamcheon is hillside lanes and stairs — wear comfortable shoes.","Dakbatgol''s wish stairs are steep, but the free monorail does the climb.","Total walking about 4–5 km."]},{"id":"capsule","title":"Sky Capsule (ticket option)","preview":"Included or excluded — your choice at booking.","content":["The Sky Capsule runs 2.3 km on an elevated rail between Cheongsapo and Mipo (~30 min), in pastel 4-seat cabins above the coastline.","Ticket-included option: we pre-reserve capsules for your group (per-capsule pricing ≈ ₩30,000 for 2 / ₩39,000 for 3 / ₩44,000 for 4 one-way; the included option is priced on a 2-per-capsule basis).","Ticket-excluded option: walk the free Green Railway boardwalk (2.3 km, ~30 min, same coastline) or ride the coach to Mipo.","Operations are weather-dependent (high wind pauses the line); if the capsule cannot run, the boardwalk walk and coach transfer keep the route on time."]},{"id":"cancellation","title":"Cancellation","preview":"Free cancellation up to 24 hours before pickup.","content":["Free cancellation up to 24 hours before pickup.","Same-day cancellations and no-shows are non-refundable."]}]'::jsonb, true), '{"bookingSupportSteps"}', '[{"timing":"Immediately","title":"Instant Confirmation","detail":"Booking confirmation with itinerary summary","description":"Instant booking confirmation, with your hotel pickup window (09:00–10:00) and what to expect."},{"timing":"Day before","title":"Pickup Details","detail":"Exact pickup location and vehicle info via WhatsApp","description":"Weather check and any route note (Danubi Train tip for Taejongdae, tide timing at Yonggungsa) sent the day before."},{"timing":"Morning of","title":"Pickup Confirmation","detail":"Driver checks in 10 minutes before arrival","description":"Van plate and guide contact confirmed the evening before."},{"timing":"During tour","title":"On-tour Support","detail":"Direct line to operations","description":"A message the evening before confirms your exact hotel pickup time; a morning message covers real-time traffic."},{"timing":"End of day","title":"Flexible Drop-off","detail":"Choose drop-off at Nampo-dong, Busan Station, Seomyeon, or Haeundae","description":"Guide provides on-site narration at each stop — Yonggungsa''s 1376 founding, UNMCK''s 22-nation story, Gamcheon''s 1955 refugee-settlement origin."},{"timing":"After tour","title":"Review & Followup","detail":"Optional review and follow-up","description":"Post-tour feedback request sent; questions about Busan restaurant recommendations answered same day."}]'::jsonb, true), '{"staticQuestions"}', '[{"question":"Is the Sky Capsule ticket included?","answer":"Your choice at booking. Book the ticket-included option and we reserve capsules for your group in advance (per-capsule pricing: about ₩30,000 for 2 / ₩39,000 for 3 / ₩44,000 for 4, one-way — the included option is priced on a 2-per-capsule basis). Book the base option and you can instead walk the free Green Railway boardwalk or ride the coach to Mipo while others take the capsule."},{"question":"Do I need to reserve the Sky Capsule in advance?","answer":"Sunset and weekend slots sell out 1–2 weeks ahead. If you choose the ticket-included option we handle the reservation for your group when the booking is confirmed. Same-day kiosk tickets are possible on quiet weekdays but not guaranteed."},{"question":"Is lunch included?","answer":"No — lunch is separate (about ₩10,000–15,000). The guide recommends local options near Haeundae/Mipo such as dwaeji-gukbap (Busan''s signature pork-rice soup), milmyeon cold noodles, or a seafood place."},{"question":"How much walking and how steep is it?","answer":"Moderate-to-challenging in short bursts: 108 stairs down and up at Yonggungsa, flat glass skywalk at Daritdol, mostly flat at the capsule stations, hillside lanes at Gamcheon, and stairs at Dakbatgol — where the free monorail does the climbing for you. Total on-foot distance is about 4–5 km."},{"question":"Is this suitable for children or seniors?","answer":"Yes for most active travelers. Kids love the glass floor and the capsule; the Dakbatgol monorail spares the steepest climb. The Yonggungsa stairs and Gamcheon slopes are the two demanding sections — take them slowly and skip side alleys as needed."},{"question":"How is this different from the Busan Top Attractions day tour?","answer":"Same operator, different focus. Top Attractions covers the classic city sweep (UN Memorial Cemetery, Jagalchi Market). This small-group route doubles down on the coast and the villages: a dedicated Daritdol skywalk stop, the Sky Capsule ride with an included-ticket option, and the quiet Dakbatgol mural village that big buses skip."},{"question":"Where do you pick up and drop off?","answer":"Pickup is door-to-door at your hotel in central Busan between 09:00 and 10:00 — the exact time is confirmed by WhatsApp the evening before. Drop-offs run in sequence: Nampo-dong ≈17:10, Busan Station ≈17:30, Seomyeon ≈17:50, Haeundae ≈18:20."},{"question":"What happens if it rains?","answer":"The day runs rain or shine. The capsule and monorail operate in normal rain (they pause only in high wind), the skywalk provides shoe covers, and village lanes stay walkable with an umbrella. Heavy weather may shorten outdoor time at the temple terraces."}]'::jsonb, true), '{"pickup_dropoff"}', '{"departure":[{"order":1,"time":"09:00–10:00","name":"Your downtown Busan hotel (door-to-door)","type":"hotel","note":"Door-to-door pickup at hotels in central Busan — Seomyeon, Nampo-dong / Busan Station, Haeundae / Marine City. Your exact time is confirmed the evening before.","lat":35.15782,"lng":129.06003}],"return":[{"order":1,"name":"Nampo-dong / Jagalchi area","type":"station","lat":35.09663,"lng":129.0308},{"order":2,"name":"Busan Station (Exit 4)","type":"station","lat":35.11449,"lng":129.03933},{"order":3,"name":"Seomyeon Station (Exit 4)","type":"station","lat":35.15782,"lng":129.06003},{"order":4,"name":"Haeundae Station (Exit 5)","type":"station","lat":35.16396,"lng":129.15853}],"notes":["Pickup is door-to-door at your central Busan hotel between 09:00 and 10:00; the exact time is confirmed the evening before. Drop-offs are at four central points in sequence (Nampo-dong → Busan Station → Seomyeon → Haeundae, ≈ 17:10–18:20) — tell the guide during the afternoon which one you want."]}'::jsonb, true), '{"matching_profile"}', '{"profile_version":1,"is_active":true,"product_id":"busan-small-group-yonggungsa-skycapsule-gamcheon-tour","product_type":"small_group","route_type":"fixed_route","destination_region":"busan_city","region_type":"busan_city","vehicle_type":"coach","duration_hours":9,"region_tags":["busan_haeundae","busan_gijang","busan_namgu","busan_saha","busan_jung"],"theme_tags":["temple","coastal","war_memorial","mural_village","fish_market","korean_war_history"],"poi_tags":["haedong_yonggungsa","cheongsapo_daritdol_observatory","cheongsapo_blue_line_park","gamcheon_culture_village","dakbatgol_mural_village"],"pace_level":0.7,"walking_level":0.85,"scenic_level":0.9,"photo_level":1,"culture_level":0.95,"relax_level":0.5,"first_time_fit":1,"family_fit":0.85,"senior_fit":0.7,"couple_fit":0.95,"solo_traveler_fit":0.9,"active_traveler_fit":0.8,"adult_family_fit":1,"family_with_teens_fit":0.95,"young_kids_fit":0.55,"senior_active_fit":0.7,"senior_general_fit":0.55,"mobility_friendly_fit":0.4,"stroller_fit":0.4,"one_day_fit":1,"same_day_flight_fit":0.3,"rain_fit":0.5,"value_for_money_fit":0.95,"iconic_landmark_fit":1,"cafe_fit":0.7,"food_fit":0.8,"nature_fit":0.8,"beach_fit":0.6,"nightlife_fit":0.2,"shopping_fit":0.2,"no_shopping_fit":0.5,"local_culture_fit":1,"storytelling_fit":0.8,"unesco_fit":0,"intangible_heritage_fit":0.2,"indoor_ratio":0.2,"weather_sensitivity":0.5,"comfort_level":0.6,"budget_fit":0.85,"premium_fit":0.3,"small_group_fit":1,"private_fit":0.05,"bus_fit":1,"price_band":"mid","pickup_base":"busan_central","return_time_band":"17:00-18:30","duration_band":"9h","min_recommended_age":8,"hard_constraints":{"avoidIf":["mobility_limited"],"notIdealFor":["very_low_mobility","stroller_heavy_groups"]},"walking_notes":["Active walking day with several flights of stairs (Yonggungsa 108 steps, Gamcheon hillside).","Average fitness expected.","Sturdy closed-toe shoes recommended (Jagalchi 1F floor is wet)."],"keywords":["busan top attractions day tour","busan small group tour","haedong yonggungsa","gamcheon culture village","jagalchi market","un memorial cemetery busan"],"synonym_hints":["busan one day classic tour","busan must-see day trip","busan top 5 highlights"],"seasonality":"year_round","pickup_base_normalized":"busan","vehicle_type_legacy":"bus_coach","anchor_poi_keys":["haedong_yonggungsa","cheongsapo_daritdol_observatory","cheongsapo_blue_line_park","gamcheon_culture_village","dakbatgol_mural_village"],"private_tour_fit":0.05,"customizable_route_fit":0.1,"flexibility_fit":0.3,"fixed_itinerary_fit":1,"buddhist_temple_fit":1,"scenic_temple_fit":1,"coastal_temple_fit":1,"seaside_temple_fit":1,"war_memorial_fit":1,"korean_war_history_fit":1,"mural_village_fit":1,"fish_market_fit":1,"market_fit":1,"street_food_fit":0.9,"skywalk_fit":1,"sky_capsule_fit":0.7,"coastal_railway_fit":1,"history_culture_fit":1,"k_drama_filming_fit":0.5,"religious_history_fit":0.85,"premium_dining_fit":0.3,"seasonal_fit":0.85,"china_mainland_market_fit":0,"korea_domestic_market_fit":0,"taiwan_market_fit":1,"singapore_market_fit":1,"hong_kong_market_fit":1,"china_diaspora_overseas_market_fit":0.95,"se_asia_market_fit":0.95,"us_market_fit":0.85,"europe_market_fit":0.85,"australia_market_fit":0.85,"japan_market_fit":0.85,"busan_signature_route_fit":1,"skywalk_coastal_railway_fit":1,"first_time_busan_fit":1,"no_inter_city_travel_fit":1,"differentiates_from_busan_gyeongju_routes":true,"deep_history_traveler_fit_minimum":0.7,"english_speaking_guide_provided":true,"chinese_speaking_guide_available_on_advance_notice":true,"japanese_speaking_guide_available_on_advance_notice":true}'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'busan-small-group-yonggungsa-skycapsule-gamcheon-tour' AND locale = 'en';

