UPDATE public.tour_product_pages SET
  duration_label = '≈ 9 Stunden',
  stops_count = 9,
  detail_payload = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(detail_payload, '{"seo"}', '{"pageTitle":"Busan Kleingruppen-Tour: Yonggungsa, Sky Capsule, Gamcheon | AtoC Korea","metaDescription":"9-stündige Kleingruppen-Tagestour durch Busan: Haedong-Yonggungsa-Tempel, Glas-Skywalk am Cheongsapo-Daritdol-Observatorium, Blueline Sky Capsule (Ticket optional), Kulturdorf Gamcheon, Dakbatgol-Wandmalereidorf & Monorail.","title":"Busan Meerestempel, Sky Capsule & Kulturdörfer — Kleingruppen-Tour | AtoC","description":"Kleingruppen-Tagestour durch Busan: Haedong Yonggungsa → Cheongsapo-Daritdol-Observatorium → Sky Capsule im Blueline Park (Ticket inbegriffen/nicht inbegriffen — Ihre Wahl) → Mittagessen → Kulturdorf Gamcheon → Dakbatgol-Wandmalereidorf & Monorail an der „Wunschtreppe“.","primaryKeywords":["Busan Kleingruppen-Tour","Haedong Yonggungsa Tour","Blueline Park Sky Capsule","Kulturdorf Gamcheon Tour","Cheongsapo-Daritdol-Observatorium"],"ogImage":"https://www.atockorea.com/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp"}'::jsonb, true), '{"catalog_card"}', '{"slug":"busan-small-group-yonggungsa-skycapsule-gamcheon-tour","title":"Busan Kleingruppe: Meerestempel, Sky Capsule & Kulturdörfer","subtitle":"Kleingruppen-Tagestour zu Busans Küstenikonen und Hangdörfern — der Haedong-Yonggungsa-Tempel am Meer, der Glas-Skywalk des Cheongsapo-Daritdol-Observatoriums, die Fahrt mit der Sky Capsule im Blueline Park (Ticket bei der Buchung wählbar), das Kulturdorf Gamcheon und das stille Dakbatgol-Wandmalereidorf mit seiner Monorail an der „Wunschtreppe“ (소망계단).","region":"Busan","duration":"≈ 9 Stunden","stopsCount":9,"rating":0,"reviewCount":0,"badges":["Kleingruppe","Busan","Sky Capsule","Küste","Kulturdörfer"],"tags":["Kleingruppe","Busan","Sky Capsule","Küste","Kulturdörfer","Ideal für Erstbesucher"],"heroImage":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","thumbnail":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","priceLabel":"","shortCardDescription":"Ein Busan-Tag in der Kleingruppe, aufgebaut um die Küste und die Hangdörfer: der Haedong-Yonggungsa-Tempel am Meer in seinem ruhigen Morgenfenster, das kostenlose Daritdol-Observatorium mit Glasboden in Cheongsapo, die Fahrt mit der Sky Capsule im Blueline Park von Cheongsapo nach Mipo (Ticket inbegriffen oder nicht — Sie wählen bei der Buchung), Mittagessen, das Kulturdorf Gamcheon und das kaum bekannte Dakbatgol-Wandmalereidorf, wo eine kostenlose Monorail die „Wunschtreppe“ hinaufgleitet. Jeder Ankerpunkt außer der optionalen Kapsel ist eintrittsfrei."}'::jsonb, true), '{"hero"}', '{"imageUrl":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","imagePosition":"center 40%","images":["/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp"],"tagline":"Busans Tempel am Meer zur stillen Stunde, ein Glas-Skywalk über dem Wasser, eine Pastellkapsel-Fahrt die Küste hinab und zwei Hangdörfer — eines berühmt, eines noch ganz lokal","pills":["Kleingruppe","Busan","Ideal für Erstbesucher"],"meta":{"duration":"≈ 9 Stunden (09:00 Abholung am Hotel, ≈ 17:50 letzte Rückgabe im Zentrum)","region":"Busan","stops":"9 Stopps","rating":0,"ratingStars":0}}'::jsonb, true), '{"itineraryStops"}', '[{"number":1,"time":"≈ 09:00–10:00","duration":"60 Min.","name":"Abholung (Ihr Hotel im Zentrum von Busan)","category":"Transfer / Hotelabholung","description":"Abholung von Tür zu Tür an Ihrem Hotel im Zentrum Busans, zwischen **09:00 und 10:00**. Die genaue Zeit wird am Vorabend per WhatsApp bestätigt, sobald der Fahrer die Hotelliste des Tages hat und die Runde effizient ordnen kann — Gäste auf der Haeundae-Seite werden meist zuletzt abgeholt, weil der Bus die Stadt nordostwärts Richtung Gijang-gun zum ersten Stopp verlässt.\n\nDas Einzugsgebiet umfasst die zentralen Hotelviertel: **Seomyeon**, **Nampo-dong / Bahnhof Busan** und **Haeundae / Marine City**. Liegt Ihr Hotel außerhalb, nennt Ihnen die Reiseleitung bei der Buchungsbestätigung den nächstgelegenen Treffpunkt.\n\nBitte warten Sie 5 Minuten vor Ihrer bestätigten Zeit in der Lobby. Die Fahrt von der letzten Abholung bis Haedong Yonggungsa dauert je nach Verkehr etwa 30–40 Minuten.","image":null,"highlights":["Abholung von Tür zu Tür an Hotels im Zentrum Busans, 09:00–10:00","Genaue Zeit am Vorabend per WhatsApp bestätigt","Kleingruppenbus (max. ~14 Personen)","Gedruckte Programmkarte auf Koreanisch und Englisch beim Einsteigen"],"timeUsed":["Abholungen an Hotels im Zentrum Busans (~40 Min.)","Fahrt nordostwärts nach Gijang-gun (~20 Min.)"],"whyOnRoute":"Die Hotelabholung erspart den morgendlichen Transfer vollständig — keine frühe U-Bahn-Fahrt, keine Suche nach dem richtigen Ausgang. Die Runde verläuft von West nach Ost, sodass der Bus in Haeundae endet und die Stadt bereits Richtung Gijang und ersten Stopp verlässt.","_poi_meta":{"match":"transit_only","poi_key":"OPS_busan_hotel_pickup_central","sources":["AtoC Korea operations"],"verified":true,"verified_date":"2026-08-05"},"images":[],"imageCredits":[],"galleryItems":[],"_role":"pickup"},{"name":"Haedong-Yonggungsa-Tempel","time":"≈ 10:20","number":2,"category":"Buddhistischer Tempel / Küste","duration":"60 Min.","timeUsed":["Ausstieg aus dem Bus + Gang durch die Händlergasse zum Eingangsplatz (~10 Min.)","Zwölf Tierkreis-Generäle + „Unfallfrei-Pagode“ (~10 Min.)","Abstieg über die 108 Stufen + Haupthalle Daeungjeon + Meeresterrassen (~25 Min.)","Aussichtspunkt der Haesu-Gwaneum-Statue + Fotozeit (~10 Min.)","Rückweg hinauf + Sammeln am Bus (~5 Min.)"],"_poi_meta":{"match":"exact","poi_key":"haedong_yonggungsa","sources":["Visit Busan","VisitKorea","Wikipedia","Culture Trip","Korean Temple Guide","Korea Tourism Organization Official"],"verified":true,"kb_version":"1.24","verified_date":"2026-04-29"},"highlights":["**Gegründet 1376** vom buddhistischen Meister Naong Hyegeun (ursprünglich „Bomunsa“)","Einer der ganz wenigen bedeutenden koreanischen Tempel direkt am Meer (die meisten liegen in den Bergen)","**1974 in Haedong Yonggungsa umbenannt** nach der Drachen-Göttinnen-Vision von Mönch Jeong-am","**108 Steinstufen** = die 108 Verblendungen des Geistes im Buddhismus","**12 Sibiji-shin (Tierkreis-Generäle)** am Eingang; Münzschrein der „**Unfallfrei-Pagode**“","**Haesu Gwaneum Daebul** (Meeresgöttin der Barmherzigkeit) — der meistfotografierte Klippenblick","Haupthalle Daeungjeon 1970 mit Blick auf die Originalfarben restauriert","Täglich 04:30-19:20 geöffnet, EINTRITT FREI; Laternenfest zu Buddhas Geburtstag (Mai)","**Steinsäulen-Aufstellung der 12 buddhistischen Sibiji-shin-Tierkreis-Generäle am Tempeltor** — einzigartig unter Koreas Küstentempeln"],"smartNotes":{"tip":"Hallen durch die Seitentüren betreten (die Vordertür ist den Mönchen vorbehalten); zu Buddhas Geburtstag (Apr.–Mai) leuchtet die Laterneninstallation; kommen Sie vor 10:30, um den größten Reisebus-Andrang zu vermeiden","photo":"Der Sonnenaufgangsfelsen am seewärtigen Rand; die Treppe neben der Daeungjeon-Halle liefert das klassische Motiv aus Meer und Tempel; die Haesu-Gwaneum-Statue von der oberen Klippe gibt den Weitwinkelblick auf Tempel und Ostmeer","facilities":"Souvenir- und Snackstände sowie ein kleines Café am oberen Platz; ein Küstenpfad führt weiter über die Felsen"},"whyOnRoute":"**Der ikonische Auftakt der Route — Busans meistfotografierter Tempel in seinem ruhigen Fenster.** Die Ankunft um 10:20 liegt vor dem großen Ansturm der Reisebusse (typischerweise ab 11:00), sodass der Abstieg über die 108 Stufen und der Aussichtspunkt der Haesu-Gwaneum-Statue noch ohne Anstehen begehbar sind. Die Klippenlage in Gijang setzt den Tagesbeginn zudem an den äußersten Nordostpunkt der Route, sodass alles Weitere in eine Richtung die Küste hinabfließt — als Nächstes Cheongsapo, dann die Kapselfahrt Richtung Stadt — ganz ohne Zurückfahren.","convenience":{"parking":"Parkplatz Haedong Yonggungsa (kostenpflichtig, laut Visit Busan)","restroom":"Nahe dem Haupteingang und innerhalb der Anlage vorhanden"},"description":"**Haedong Yonggungsa (해동 용궁사) — Koreas berühmtester buddhistischer Tempel am Meer** — thront auf den Felsklippen von Gijang-gun an Busans Nordostküste, einer der ganz wenigen bedeutenden koreanischen Tempel, die NICHT in den Bergen liegen. Ursprünglich gegründet **1376 während der Goryeo-Dynastie durch den großen buddhistischen Lehrer Naong Hyegeun (나옹 혜근, 1320-1376)** — königlicher Berater und Meister, der den koreanischen Buddhismus bis in die frühe Joseon-Ära prägen sollte. \n\nDer Legende nach übte Naong während einer landesweiten Dürre Askese im Bunhwangsa-Tempel in Gyeongju; der Gott des Ostmeers erschien ihm im Traum und verkündete, dass der Bau eines Tempels auf dem Bongrae-Berg (dem ursprünglichen Namen dieser Küstenklippe) den Wohlstand des Königreichs wiederherstellen würde. \n\nNaong gründete den Tempel und nannte ihn **Bomunsa**, geweiht Gwanseum-bosal (관세음보살, dem Bodhisattva des Mitgefühls). Der Tempel wurde in der **japanischen Imjin-Invasion von 1592** zerstört und lag über 300 Jahre in Ruinen, bis **Mönch Ungang vom Tongdosa-Tempel in den frühen 1930er-Jahren mit dem Wiederaufbau begann**. \n\nDer heutige Name, **Haedong Yonggungsa (Koreanischer Drachenpalast-Tempel)**, stammt erst von **1974** — als Vorsteher Jeong-am während eines 100-tägigen Gebets (jeong-geon kido) eine Vision der Göttin der Barmherzigkeit hatte, die auf dem Rücken eines Drachen herabstieg und vielfarbiges Licht ausstrahlte. \n\nZu Ehren dieser Vision wurde der Tempel umbenannt. Der Besuch folgt dem charakteristischen Prozessionsweg des Tempels: durch die Reihe der **12 Sibiji-shin (Zwölf Tierkreis-Generäle)** am Eingangsplatz, vorbei an der **7-stöckigen „Unfallfrei-Pagode“** (wo Autofahrer Münzopfer unter einem steinernen Radschrein hinterlassen), die berühmten **108 Steinstufen** hinab (sie stehen für die 108 Verblendungen des buddhistischen Geistes) durch einen kleinen Bambushain und hinaus auf die Meeresterrassen und zur Haupthalle Daeungjeon. \n\nDie **Haesu Gwaneum Daebul** (Statue der Meeresgöttin der Barmherzigkeit) auf der oberen Klippe ist der meistfotografierte Blick und rahmt sowohl die Tempeldächer als auch das Ostmeer. \n\nÖffnungszeiten **täglich 04:30-19:20, letzter Einlass 18:50, EINTRITT FREI**. Zu **Buddhas Geburtstag (Mai)** erstrahlt das Laternenfest Yeondunhoe.","visitBasics":{"hours":"Täglich 04:30–19:20 (letzter Einlass 18:50)","closed":"Ganzjährig geöffnet","walking":"Moderat — 108 Stufen durch einen Kiefernhain, mehrere Meeresterrassen und Treppen","admission":"Frei; Parken für Privatwagen kostenpflichtig"},"image":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","images":["/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp"],"imageCredits":[{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 1","alt":"Haedong Yonggungsa Temple — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 2","alt":"Haedong Yonggungsa Temple — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 3","alt":"Haedong Yonggungsa Temple — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 4","alt":"Haedong Yonggungsa Temple — gallery image 4"},{"id":5,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 5","alt":"Haedong Yonggungsa Temple — gallery image 5"},{"id":6,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 6","alt":"Haedong Yonggungsa Temple — gallery image 6"}]},{"number":3,"time":"≈ 11:40","duration":"40 Min.","name":"Cheongsapo-Daritdol-Observatorium (Glas-Skywalk)","category":"Küsten-Observatorium / Kostenlos","description":"Das **Cheongsapo-Daritdol-Observatorium (청사포 다릿돌전망대)** ist ein **72,5 Meter langer Skywalk, der sich etwa 20 Meter über dem Wasser aufs Meer hinausschwingt**, eröffnet im August 2017 auf der Küstenklippe zwischen Cheongsapo und Songjeong. Sein Name kommt von den **daritdol — den fünf „Trittstein“-Rifffelsen**, die unter dem Steg im Meer liegen und der Sage nach wie eine Brücke zum Horizont schreiten. Der äußere Abschnitt des Stegbodens ist aus **Glas**, mit gestellten Schuhüberziehern zum Schutz der Scheiben (und als Vertrauensbeweis!), während die Dünung unter Ihren Füßen rollt. Der Eintritt ist **frei**. Zurück im Dorf sind die **Zwillingsleuchttürme von Cheongsapo** (einer rot, einer weiß) und der kleine Bahnübergang, den sein Anime-Bildausschnitt im Slam-Dunk-Stil berühmt gemacht hat, nur einen kurzen Spaziergang entfernt.","image":null,"highlights":["**72,5-m-Skywalk, ~20 m über dem Meer** — eröffnet August 2017, KOSTENLOS","Benannt nach den fünf **daritdol-„Trittstein“-Riffen**, die unter dem Steg sichtbar sind","**Glasboden-Abschnitt** am seewärtigen Ende (Schuhüberzieher werden gestellt)","**Zwillingsleuchttürme von Cheongsapo** (rot + weiß), einen kurzen Spaziergang entfernt","Cheongsapo zählt zu Busans **acht schönsten Aussichten** — ein aktives Fischerdorf","Anime-berühmter Bahnübergang als Fotospot"],"timeUsed":["Ausstieg aus dem Bus + Fußweg zum Skywalk-Eingang (~5 Min.)","Gang auf den Skywalk + Glasboden-Abschnitt (~20 Min.)","Spaziergang zu Zwillingsleuchttürmen / Bahnübergang für Fotos (~10 Min.)","Sammeln für die Kapselstation (~5 Min.)"],"whyOnRoute":"**Der kostenlose Nervenkitzel zwischen Tempel und Kapsel.** Daritdol gibt dem Tag seinen Moment über dem Meer — ein Glasboden mit rollender Dünung darunter — ganz ohne Ticket, und es liegt direkt auf der Cheongsapo-Klippe, sodass es nahtlos in das nur Minuten entfernte Einsteigen in die Sky Capsule übergeht. Wer die Küste zuerst vom feststehenden Skywalk aus gesehen hat, erlebt den Blick aus der fahrenden Kapsel zehn Minuten später ganz anders.","_poi_meta":{"match":"authored","poi_key":"cheongsapo_daritdol_observatory","sources":["Visit Busan","Busan Metropolitan City Tourism","Blue Line Park official"],"verified":false,"verified_date":"2026-08-04"},"smartNotes":{"tip":"An windigen Tagen schließt der Steg gelegentlich — der Guide prüft die Bedingungen und ordnet das Cheongsapo-Ensemble bei Bedarf um","photo":"Fotografieren Sie durch das Glas hinab auf die daritdol-Riffe; die Kurve des Stegs vom Uferweg aus ergibt die beste Weitaufnahme","facilities":"Cafés und Fischstände im Dorf Cheongsapo unterhalb"},"convenience":{"parking":"Bushalt im Dorf Cheongsapo; kurzer Fußweg zum Steg","restroom":"Öffentliche Toiletten nahe der Station Cheongsapo"},"visitBasics":{"hours":"Frei zugänglich; Observatorium besetzt etwa 09:00–18:00 (saison-/wetterabhängig)","closed":"Kann bei starkem Wind oder Sturm vorübergehend schließen","walking":"Ebener Gang auf dem Steg; eine kurze Steigung vom Dorf","admission":"KOSTENLOS (Schuhüberzieher für den Glasabschnitt werden gestellt)"},"images":[],"imageCredits":[],"galleryItems":[]},{"number":4,"time":"≈ 12:30","duration":"50 Min.","name":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","category":"Küstenfahrt / Ticket optional","description":"Die **Sky Capsule** ist die Signature-Fahrt des **Haeundae Blueline Park**, der 2020 eröffneten Öko-Umnutzung der stillgelegten Donghae-Nambu-Küstenbahn: **pastellfarbene 4-Sitzer-Kabinen, die 2,3 km auf einer aufgeständerten Trasse 7–10 Meter über der Küstenlinie** zwischen Cheongsapo und Mipo gleiten, mit dem Meer die ganze Zeit auf einer Seite (~30 Minuten). Wir steigen in **Cheongsapo ein und fahren Richtung Mipo**, wo der Bus bereits wartet — die Fahrt dient also zugleich als Tagestransfer die Küste hinab. **Das Kapselticket ist optional und wird bei der Buchung gewählt**: Mit der Option „Ticket inbegriffen“ reservieren wir die Kapseln für Ihre Gruppe vorab (Preis pro Kapsel: etwa ₩30,000 für 2 / ₩39,000 für 3 / ₩44,000 für 4, einfache Fahrt); mit der Basisoption können Sie über den **kostenlosen Green-Railway-Holzsteg** gehen — die preisgekrönte 2,3 km lange hölzerne Uferpromenade unter derselben Trasse — oder einfach mit dem Bus nach Mipo fahren.","image":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","highlights":["**Pastellfarbene 4-Sitzer-Kapseln auf einer aufgeständerten Küstentrasse** — die Signature-Fahrt des Blueline Park (eröffnet 2020)","**Cheongsapo → Mipo, 2,3 km / ~30 Min.**, Meerblick auf der ganzen Strecke","**Ticket inbegriffen oder nicht — Ihre Wahl bei der Buchung** (Preis pro Kapsel ≈ ₩30,000 für 2 / ₩39,000 für 3 / ₩44,000 für 4, einfache Fahrt)","Nicht-Mitfahrende: **kostenloser Green-Railway-Holzsteg** (Uferpromenade) entlang derselben Küste oder der Bus nach Mipo","Die Fahrt endet, wo das Mittagessen beginnt — Mipo liegt nur einen kurzen Fußweg von Haeundaes Essensstraßen entfernt","Fährt bei normalem Regen; pausiert nur bei starkem Wind"],"timeUsed":["Einstieg an der Station Cheongsapo (~15 Min.)","Fahrt mit der Sky Capsule Cheongsapo → Mipo (~35 Min.)"],"whyOnRoute":"**Die Fahrt, die zugleich der Transfer ist.** Der Einstieg in Cheongsapo direkt nach dem Skywalk bedeutet, dass die Kapsel Sie genau die Küste hinabträgt, über die Sie gerade geblickt haben — und sie setzt Sie in Mipo ab, wo Bus und Essensstraßen bereits warten. Nichts am Tag macht dafür einen Umweg: Lassen Sie das Ticket aus, decken der Bus oder die kostenlose Uferpromenade dieselbe Etappe ab.","_poi_meta":{"match":"partial","poi_key":"cheongsapo_blue_line_park","sources":["Blue Line Park official","Visit Busan","Busan Metropolitan City Tourism"],"verified":true,"kb_version":"1.24","verified_date":"2026-08-04"},"smartNotes":{"tip":"Sonnenuntergangs- und Wochenendtermine sind 1–2 Wochen im Voraus ausverkauft — wählen Sie bei der Buchung die Option mit inbegriffenem Ticket, und wir reservieren für Sie","photo":"Setzen Sie sich auf die Meerseite (in Fahrtrichtung Mipo rechts); die Kurve am Dalmaji-Tunnel ist das Signature-Motiv","facilities":"Cafés und Convenience-Store am Vorplatz von Mipo; Ticketautomaten an beiden Stationen"},"convenience":{"parking":"Der Bus trifft die Gruppe am Stationsvorplatz von Mipo","restroom":"An beiden Stationen, Cheongsapo und Mipo"},"visitBasics":{"hours":"≈ 09:30–18:30 (in der Hochsaison bis in den Abend verlängert)","closed":"Wetterabhängig; starker Wind pausiert den Betrieb","walking":"Ebene Bahnsteige; die Alternative über den Holzsteg beträgt 2,3 km (~30 Min.) auf Holzplanken","admission":"Pro Kapsel, einfache Fahrt: ≈ ₩30,000 (2 Pers.) / ₩39,000 (3) / ₩44,000 (4) — Option mit inbegriffenem Ticket bei der Buchung verfügbar"},"images":["/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","/images/tours/cheongsapo-blue-line/blueline-tram-cherry-sea.webp","/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-12-53-19.webp"],"imageCredits":[{"url":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","source":"atoc-korea"},{"url":"/images/tours/cheongsapo-blue-line/blueline-tram-cherry-sea.webp","source":"atoc-korea"},{"url":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","source":"atoc-korea"},{"url":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-12-53-19.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","location":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","caption":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — photo 1","alt":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/cheongsapo-blue-line/blueline-tram-cherry-sea.webp","location":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","caption":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — photo 2","alt":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","location":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","caption":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — photo 3","alt":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-12-53-19.webp","location":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","caption":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — photo 4","alt":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo) — gallery image 4"}]},{"name":"Mittagessen (lokales Restaurant nahe Haeundae/Mipo)","time":"≈ 13:25","number":5,"category":"Lokale Mahlzeit","duration":"45 Min.","timeUsed":["Fußweg von der Station Mipo zum Restaurant (~5 Min.)","Mittagessen (~35 Min.)","Sammeln am Bus (~5 Min.)"],"_poi_meta":{"match":"lunch_placeholder","poi_key":"OPS_busan_lunch","sources":["Visit Busan","Busan Metropolitan Government cuisine guide"],"verified":true,"kb_version":"1.15","verified_date":"2026-04-29"},"highlights":[],"whyOnRoute":"**Die natürliche Pause zwischen Küste und Dörfern.** Die Kapselfahrt endet zur Mittagszeit in Mipo, und Haeundaes Essensstraßen sind nur einen kurzen Fußweg von der Station entfernt — keine zusätzliche Fahrt für eine gute Mahlzeit. Wer sich hier stärkt, ist bereit für die beiden Hangdörfer des Nachmittags, wo das Gehen am steilsten wird.","description":"Etwa 45 Minuten Mittagspause nahe Mipo/Haeundae, direkt nachdem die Sky Capsule angekommen ist. Typische Empfehlungen des Guides: **dwaeji-gukbap (돼지국밥)** — Busans typische Reissuppe mit Schweinefleischbrühe, entstanden in der Flüchtlingszeit des Koreakriegs (~₩10,000), **milmyeon**, kalte Weizennudeln, oder ein Fischrestaurant am Hafen. Das Mittagessen ist nicht inbegriffen (≈ ₩10,000–15,000), sodass Sie nach Appetit und Budget wählen können."},{"number":6,"time":"≈ 14:10","duration":"20 Min.","name":"Haeundae-Strand","category":"Strand / Kostenlos","description":"Der **Haeundae-Strand (해운대해수욕장)** ist Koreas bekanntester Sandstrand — rund **1,5 km** Küste, die sich zwischen der Insel Dongbaekseom im Westen und Mipo im Osten spannt, im Rücken die Skyline von Marine City. Die Sky Capsule setzt Sie in Mipo ab, also schlicht am Ostende dieses Strands — der Stopp kostet dem Tag keine zusätzliche Fahrzeit.\n\nZwanzig Minuten sind ein Foto- und Fußbadstopp, kein Badeaufenthalt: hinaus auf den Sand, die Skyline fotografieren, zurück zum Bus. Im Juli und August ist der Strand am vollsten und die Schirmreihen stehen; den Rest des Jahres ist er weit, ruhig und gut begehbar. Kostenlos und rund um die Uhr geöffnet.","image":null,"highlights":["**Koreas berühmtester Strand** — ~1,5 km Sand, KOSTENLOS und 24 Std. geöffnet","Skyline von Marine City direkt von der Wasserlinie","Insel Dongbaekseom und Nurimaru APEC House am Westende","Direkt in Mipo, wo die Sky Capsule endet — kein zusätzlicher Transfer"],"timeUsed":["Von Mipo hinaus auf den Sand (~5 Min.)","Fotos von Strand und Skyline (~10 Min.)","Sammeln am Bus (~5 Min.)"],"whyOnRoute":"Die Capsule endet in Mipo, dem Ostende des Strands — Busans berühmtester Blick liegt also fünf Gehminuten entfernt und kostet den Tag nichts. Der Stopp ist bewusst kurz: gerade genug, um im Sand zu stehen und die Skyline zu fotografieren, bevor der Nachmittag zu den Hangdörfern wechselt.","_poi_meta":{"match":"authored","poi_key":"haeundae_beach","sources":["Visit Busan","Busan Metropolitan City Tourism"],"verified":false,"verified_date":"2026-08-05"},"visitBasics":{"hours":"Rund um die Uhr geöffnet","closed":"Nie","walking":"Ebener Sand und befestigte Promenade","admission":"KOSTENLOS"},"images":[],"imageCredits":[],"galleryItems":[]},{"name":"Kulturdorf Gamcheon","time":"≈ 15:10","number":7,"category":"Kulturdorf / Wandmalerei-Kunst","duration":"60 Min.","timeUsed":["Ausstieg aus dem Bus am öffentlichen Parkplatz 2 + Fußweg zum Eingang (~5 Min.)","Touristeninformation + Kauf der Stempelkarte (~10 Min.)","Aussichtspunkt Sky Garden + Bank des Kleinen Prinzen (~20 Min.)","Gassenspaziergang vorbei an Wandbildern + kleine Café-Pause (~20 Min.)","Sammeln am Bus (~5 Min.)"],"_poi_meta":{"match":"exact","poi_key":"gamcheon_culture_village","sources":["Wikipedia","CNN","Visit Busan","Hapskorea","Columban Society","Lifeguin","Busan Cultural Foundation"],"verified":true,"kb_version":"1.24","verified_date":"2026-04-29"},"highlights":["**„Koreas Machu Picchu“ / „Koreas Santorin“** — UN-HABITAT Asian Townscape Award 2012","Ursprünge: Umsiedlung durch die Busaner Verwaltung **1920er-1930er** + **Taegeukdo-Flüchtlinge 1955** (~800 Familien)","**Taegeukdo-Philosophie des „andere gedeihen Lassens“** = kein Haus verstellt die Sicht des dahinterliegenden","**2009 „Dreaming of Machu Picchu“ + 2010 „Miro Miro“** — Public-Art-Projekte des Kulturministeriums","**Bank mit dem „Kleinen Prinzen und dem Fuchs“** am Sky Garden — der meistfotografierte Ort des Dorfes","**~1,4 Millionen Besucher jährlich** seit der Public-Art-Erneuerung","**Bewohnte Wohngemeinschaft** — leise Stimmen, keine Drohnen, kein Blitzlicht in die Häuser","Freier Dorfeintritt; optionale Stempelkarte ~₩2,000","**UN-HABITAT Asian Townscape Award 2012** — Auszeichnung für das Kunstprojekt „Dreaming of Machu Picchu“ von 2009, das die Taegeukdo-Flüchtlingssiedlung von 1955 in Busans bekanntestes Wandmalereidorf verwandelte"],"smartNotes":{"tip":"Hier leben Menschen — sprechen Sie leise, keine Drohnen, nehmen Sie Abfall mit; tragen Sie rutschfeste Schuhe für die steilen Gassen; die goldene Stunde am Nachmittag ~16:00-17:00 ist das schönste Licht des Dorfes","photo":"Bank mit dem Kleinen Prinzen und dem Fuchs (lange Schlange) und Haneul Maru / Sky-Garden-Observatorium für den weiten Blick auf Regenbogendächer und Bucht","facilities":"Hanbok-Verleih, Handwerksateliers, koreanische Süßigkeitenstände, Cafés; kleines Dorfmuseum am Eingang; die Stempelkarte ist der einfachste Wegweiser"},"whyOnRoute":"**Das Hauptdorf des Nachmittags — Busans Pastell-Amphitheater.** Nach dem Küstenmorgen wechselt der Tag zu den westlichen Hanglagen, wo sich Gamcheons Flüchtlingsterrassen aus der Koreakriegszeit, 2009 als Kunstdorf wiedergeboren, in Bonbonfarben über dem Meer stapeln. Die 90-minütige Runde umfasst die Aussichtspunkte, den Sims mit dem Kleinen Prinzen und Zeit zum Streifen durch die Gassen — und sie ist bewusst mit dem stillen Dakbatgol direkt danach kombiniert, damit Sie sowohl das berühmte Dorf als auch das lokale sehen, das die Busse auslassen.","convenience":{"parking":"Öffentlicher Parkplatz Gamcheon 2 (kostenpflichtig)","restroom":"Öffentliche Toiletten an der Touristeninformation und an den Hauptaussichtspunkten"},"description":"Das **Kulturdorf Gamcheon (감천문화마을)** — genannt sowohl **„Koreas Machu Picchu“** als auch **„Koreas Santorin“** — ist ein Hangviertel in Saha-gu im Westen Busans, dessen pastellfarben gestrichene Häuser in gestaffelten Reihen den Hang hinabfallen. \n\nDie Siedlung entstand in den **1920er-1930er-Jahren**, als die Busaner Verwaltung Arbeiterfamilien vom Hafen weg umsiedelte. Ihren Charakter erhielt das Dorf **1955**, als sich **~800 Familien (etwa 4.000 Menschen) der Taegeukdo-Glaubensgemeinschaft** — einer einzigartig koreanischen synkretistischen Religion, die buddhistische, konfuzianische und Yin-Yang-Elemente verbindet, gegründet von **Jo Cheol-je** während der japanischen Kolonialzeit — hier als Koreakriegsflüchtlinge aus dem Norden niederließen. \n\nDie Taegeukdo-Philosophie, „**andere gedeihen zu lassen**“, prägte unmittelbar das markanteste Merkmal des Dorfes: Die Häuser sind bewusst so gestaffelt, dass **kein Dach dem Haus dahinter die Sicht nimmt** — die ganze Gemeinschaft bleibt zu Himmel und Meer hin offen. Gamcheon blieb eines der ärmsten Viertel Busans, bis das koreanische Kulturministerium **2009** das Public-Art-Projekt **„Dreaming of Machu Picchu in Busan“** startete, gefolgt vom **„Miro Miro“-Projekt (Labyrinth) 2010** — mit über 22 beauftragten Wandbildern, Skulpturen und Kunstinstallationen, darunter die ikonische **Bank mit dem „Kleinen Prinzen und dem Fuchs“** am Aussichtspunkt Sky Garden. \n\nGamcheon gewann den **UN-HABITAT Asian Townscape Award 2012** und empfängt heute **~1,4 Millionen Besucher jährlich**. Der Besuch folgt der charakteristischen Stempelkarten-Route des Dorfes: vom Eingang an der **Touristeninformation** hinauf zum **Aussichtspunkt Sky Garden** für das Panorama der Regenbogendächer, dann hinab durch die labyrinthischen Gassen vorbei an Wandbildern, Hanbok-Verleihen, Handwerksateliers und kleinen Cafés. \n\n**Das Dorf ist eine bewohnte Wohngemeinschaft** — leise Stimmen sind Pflicht, keine Drohnen, kein Blitzlicht in die Häuser, und Abfall wird mitgenommen. \n\nÖffnungszeiten **09:00-18:00 März-Okt. / 09:00-17:00 Nov.-Feb. (Infozentrum)**; **das Dorf selbst ist rund um die Uhr geöffnet, EINTRITT FREI**.","visitBasics":{"hours":"Täglich 09:00–18:00 (März–Okt.) / 09:00–17:00 (Nov.–Feb.); manche Läden/Cafés haben eigene Öffnungszeiten","closed":"Ganzjährig geöffnet (eine bewohnte Wohngemeinschaft)","walking":"Anstrengend — sehr steile Gassen und Treppen; in vielen Abschnitten nicht kinderwagen- oder rollstuhlgerecht","admission":"Freier Dorfeintritt; optionale Stempelkarte ≈ 2,000 KRW"},"image":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","images":["/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp"],"imageCredits":[{"url":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 1","alt":"Gamcheon Culture Village — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 2","alt":"Gamcheon Culture Village — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 3","alt":"Gamcheon Culture Village — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 8","alt":"Gamcheon Culture Village — gallery image 8"}]},{"number":8,"time":"≈ 16:30","duration":"30 Min.","name":"Dakbatgol-Wandmalereidorf & Monorail an der „Wunschtreppe“","category":"Wandmalereidorf / Kostenlose Monorail","description":"**Dakbatgol (닥밭골)** ist ein Hangdorf in Busans Bezirk Seo-gu, dessen Name an die **Papiermaulbeer-Felder (dak)** erinnert, die einst Koreas traditionelle Hanji-Papiermacher belieferten. Wie Gamcheon klettert es in engen Gassen einen steilen Hang hinauf — doch es wurde nie zum Reisebus-Stopp, sodass seine **Wandmalerei-Gassen, Hanji-Motive und Aussichtspunkte still und lokal bleiben**, Wäscheleinen inklusive. Das Wahrzeichen des Dorfes ist die **„Wunschtreppe“ (소망계단)** — eine lange, steile, mit Wandmalereien bemalte Treppenstraße — und die **kostenlose Standseil-Monorail**, die daneben hinaufgleitet, installiert, damit die älteren Bewohner ihre Häuser erreichen können; auch Besucher fahren mit und verwandeln so den steilsten Anstieg des Nachmittags in einen Aussichtspunkt in Zeitlupe. Es ist der bewusst menschliche Kontrapunkt zu Gamcheons Ruhm, zehn Minuten vor der Ausstiegszone.","image":null,"highlights":["**Stilles Wandmalereidorf** — Gamcheons lokales Gegenstück, fast ohne Menschenmengen","Benannt nach den **Papiermaulbeer-Feldern (dak)** von Busans Hanji-Papiererbe","**„Wunschtreppe“ (소망계단)** — eine steile Treppenstraße voller Wandmalereien","**Kostenlose Standseil-Monorail** neben der Treppe — für die Dorfältesten gebaut, offen für Besucher","Hang-Aussichtspunkte über das alte Hafenviertel","EINTRITT FREI; ein wirklich bewohntes Viertel — bitte leise sprechen"],"timeUsed":["Ausstieg aus dem Bus + Spaziergang durch die Wandmalerei-Gassen (~10 Min.)","Monorail-Fahrt die „Wunschtreppe“ hinauf + Aussichtspunkt (~10 Min.)","Abstieg + Fotozeit (~5 Min.)","Sammeln am Bus (~5 Min.)"],"whyOnRoute":"**Der stille Abschluss, den die Busse auslassen.** Nach Gamcheons Menschenmengen zeigt Dakbatgol dasselbe Hang-Busan in Alltagslautstärke — Wandmalereien, die „Wunschtreppe“ und eine Monorail, die den Aufstieg übernimmt. Es schließt das Dörfer-Kapitel zehn Minuten von der Nampo-Ausstiegszone entfernt, sodass der Tag tief in lokaler Atmosphäre endet statt im Verkehr.","_poi_meta":{"match":"authored","poi_key":"dakbatgol_mural_village","sources":["Visit Busan","Busan Seo-gu Office"],"verified":false,"verified_date":"2026-08-04"},"smartNotes":{"tip":"Dies ist ein bewohntes Dorf, kein Themenpark — sprechen Sie in den Gassen leise und fotografieren Sie nicht in offene Türen","photo":"Fotografieren Sie die „Wunschtreppe“ von unten mit der daneben verlaufenden Monorail-Trasse; der obere Aussichtspunkt rahmt das Hafenviertel","facilities":"Kleine Cafés nahe dem Eingang; mehr Auswahl in Nampo-dong nach dem Ausstieg"},"convenience":{"parking":"Bushalt am Dorfeingang","restroom":"Öffentliche Toilette nahe dem Dorfeingang"},"visitBasics":{"hours":"Offenes Dorf; die Monorail fährt tagsüber (≈ 09:00–18:00, wetterabhängig)","closed":"Die Monorail kann für Wartung oder bei Sturm pausieren — die Treppe bleibt offen","walking":"Steile Gassen und Treppen; die Monorail deckt den steilsten Abschnitt ab","admission":"KOSTENLOS (Dorf und Monorail)"},"images":[],"imageCredits":[],"galleryItems":[]},{"number":9,"time":"≈ 17:10","duration":"≈ 70 Min. gesamt","name":"Ausstieg (4 Punkte im zentralen Busan)","category":"Ausstieg — Zentrale Stationen der Reihe nach","description":"**Die Rückgaben verlaufen der Reihe nach von West nach Ost**: **Nampo-dong / Jagalchi (~17:10)** — hier steigen Sie für Busans beste Abend-Esstraßen und das nächtliche BIFF Square aus; **Bahnhof Busan (~17:30)** für KTX-Anschlüsse; **Seomyeon (~17:50)** für die zentralen Hotels; und zuletzt **Haeundae (~18:20)**. Stimmen Sie Ihren Ausstiegspunkt im Laufe des Nachmittags mit der Reiseleitung ab — bis Haeundae mitzufahren ist die längste Strecke, setzt Sie aber für den Abend direkt am Strand ab.","image":null,"highlights":[],"timeUsed":["Nampo-dong / Jagalchi (~17:10)","Bahnhof Busan (~17:30)","Seomyeon (~17:50)","Haeundae (~18:20)"],"whyOnRoute":"Dakbatgol liegt zehn Minuten von Nampo-dong, sodass die Rückgabefolge fast unmittelbar nach dem letzten Stopp beginnt — keine Leerfahrt. Die West-Ost-Reihenfolge deckt KTX-Reisende (Bahnhof Busan), zentrale Hotels (Seomyeon) und Strandhotels (Haeundae) ohne Umwege ab.","_poi_meta":null,"images":[],"imageCredits":[],"galleryItems":[]}]'::jsonb, true), '{"routeFlowStops"}', '[{"name":"Abholung (Ihr Hotel im Zentrum von Busan)","type":"origin","theme":"Departure"},{"name":"Haedong-Yonggungsa-Tempel","type":"primary","theme":"Seaside temple"},{"name":"Cheongsapo-Daritdol-Observatorium (Glas-Skywalk)","type":"secondary","theme":"Glass Skywalk"},{"name":"Haeundae Blueline Park Sky Capsule (Cheongsapo → Mipo)","type":"primary","theme":"Sky Capsule"},{"name":"Mittagessen (lokales Restaurant in Busan)","type":"meal","theme":"Meal"},{"name":"Haeundae-Strand","type":"secondary","theme":"Beach"},{"name":"Kulturdorf Gamcheon","type":"primary","theme":"Art village"},{"name":"Dakbatgol-Wandmalereidorf & Monorail an der „Wunschtreppe“","type":"secondary","theme":"Mural Village"},{"name":"Ausstieg (4 Punkte im zentralen Busan)","type":"return","theme":"Return"}]'::jsonb, true), '{"routePhases"}', '[{"phase":"Küstenmorgen","duration":"≈ 3,5 Stunden","description":"Abholung von Tür zu Tür an Hotels im Zentrum Busans (09:00–10:00), dann der Haedong-Yonggungsa-Tempel vor dem Reisebus-Ansturm und weiter zum gläsernen Daritdol-Skywalk in Cheongsapo."},{"phase":"Sky Capsule, Mittagessen & Strand","duration":"≈ 2 Stunden","description":"Die pastellfarbene Sky Capsule von Cheongsapo nach Mipo (Ticket optional — wer nicht mitfährt, nimmt den Bus oder läuft den Green-Railway-Boardwalk), Mittagessen nahe Haeundae und anschließend zwanzig Minuten am Haeundae-Strand selbst."},{"phase":"Zwei Hangdörfer","duration":"≈ 2 Stunden","description":"Die Fotorunde durch das Kulturdorf Gamcheon (60 Min.) und danach das stille Wandbilddorf Dakbatgol mit seiner kostenlosen Monorail an der „Wunschtreppe\" (30 Min.)."},{"phase":"Abschluss im Zentrum","duration":"≈ 1 Stunde","description":"Rückgaben der Reihe nach: Nampo-dong, Bahnhof Busan, Seomyeon, dann Haeundae."}]'::jsonb, true), '{"routeShapeIntro"}', '{"title":"So bewegt sich dieser Busan-Tag","subtitle":"Zuerst die Ostküste: der Tempel am Meer in seinem ruhigen Morgenfenster, dann das Cheongsapo-Ensemble — Glas-Skywalk, Zwillingsleuchttürme — wo die Fahrt mit der Sky Capsule selbst zum Transfer die Küste hinab nach Mipo wird. Nach dem Mittagessen und einem kurzen Stopp am Haeundae-Strand wechselt der Tag zu Busans westlichen Hanglagen für zwei Dörfer in zwei Stimmungen: Gamcheons weltberühmte Farben, dann Dakbatgols stille Wandmalereien, wo eine kostenlose Monorail die „Wunschtreppe“ hinaufgleitet. Zentrale Ausstiegspunkte schließen die Runde, von 09:00 bis etwa 18:20."}'::jsonb, true), '{"whyTourWorks"}', '{"bestFor":["Erstbesucher in Busan","Paare und fotobegeisterte Reisende","Erwachsene Familien und Freundesgruppen","Reisende, die Küste UND Dörfer an einem Tag erleben möchten"],"lessIdealFor":["Reisende, die möglichst wenig gehen oder keine Steigungen möchten","Gruppen mit Kinderwagen (Dorfgassen und Treppen)","Nachtpanorama-Fans — dies ist eine Tagesroute"],"routeLogicSections":[{"title":"Pacing & geography","icon":"route","iconBg":"bg-sky-50/80","iconColor":"text-sky-600","items":[{"label":"Der Tempel in seinem ruhigen Fenster","detail":"Haedong Yonggungsa ist Busans meistfotografierter Tempel, und der Ansturm der Reisebusse setzt gegen 11:00 ein. Eine Ankunft gegen 10:20 hält den Abstieg über die 108 Stufen und den Aussichtspunkt der Haesu-Gwaneum-Statue begehbar, ganz ohne Schlange."},{"label":"Die Kapselfahrt IST der Transfer","detail":"Von Cheongsapo gleitet die pastellfarbene Sky Capsule 2,3 km die Küste hinab nach Mipo — die Fahrt ersetzt also eine Busetappe, statt einen Umweg hinzuzufügen. Gäste ohne Ticket fahren mit dem Bus nach Mipo oder gehen über den kostenlosen Green-Railway-Holzsteg (Uferpromenade) entlang derselben Küste."},{"label":"Zwei Hangdörfer, zwei Stimmungen","detail":"Gamcheon ist Busans weltberühmtes Pastell-Amphitheater; Dakbatgol, zehn Minuten entfernt, ist sein stilles lokales Gegenstück — Wandmalerei-Gassen fast ohne Menschenmengen, wo eine kostenlose Standseil-Monorail, gebaut für die älteren Dorfbewohner, Sie die „Wunschtreppe“ hinaufträgt."},{"label":"Eintrittsfreie Ankerpunkte, ein optionales Ticket","detail":"Yonggungsa, der Daritdol-Skywalk, Gamcheon und Dakbatgol (Monorail inbegriffen) sind alle kostenlos. Die einzige kostenpflichtige Attraktion des Tages ist die Sky Capsule — und Sie entscheiden bei der Buchung: Ticket inbegriffen, oder nicht inbegriffen, wenn Sie lieber die Uferpromenade entlanggehen."}]}]}'::jsonb, true), '{"practicalAccordionItems"}', '[{"id":"pickup","title":"Abholung & Rückgabe","preview":"Die Abholung erfolgt von Tür zu Tür an Ihrem Hotel im Zentrum Busans — Seomyeon, Nampo-dong / Bahnhof Busan, Haeundae / Marine City — zwischen 09:00 und 10:00. Die genaue Zeit wird am Vorabend per WhatsApp bestätigt.","content":["Die Abholung erfolgt von Tür zu Tür an Ihrem Hotel im Zentrum Busans — Seomyeon, Nampo-dong / Bahnhof Busan, Haeundae / Marine City — zwischen 09:00 und 10:00. Die genaue Zeit wird am Vorabend per WhatsApp bestätigt.","Rückgaben der Reihe nach: Nampo-dong/Jagalchi ≈17:10, Bahnhof Busan ≈17:30, Seomyeon ≈17:50, Haeundae ≈18:20.","Ihre effektive Tourdauer hängt von Abholzeit und Ausstiegspunkt ab — im kürzesten Fall etwa 7 Std. 15 Min. (Abholung 10:00, Ausstieg Nampo-dong), im längsten etwa 9 Std. 15 Min. (Abholung 09:00, Ausstieg Haeundae)."]},{"id":"what-to-bring","title":"Kleidung & Ausrüstung","preview":"Bequeme Wanderschuhe mit Profil — Gamcheons Hanggassen und Yonggungsas 108…","content":["Bequeme Wanderschuhe mit Profil — Gamcheons Hanggassen und Yonggungsas 108 Stufen verlangen beide Trittsicherheit.","Eine leichte Schicht für das klimatisierte Fahrzeug und die Meeresbrise am Yonggungsa.","Kamera oder Smartphone (Gamcheon und Cheongsapo sind die Foto-Höhepunkte).","Bargeld oder Karte für das Mittagessen (₩10,000–₩20,000), die optionalen Sky-Capsule-/Beach-Train-Tickets in Cheongsapo und das optionale Busan-Tower-Observatorium."]},{"id":"weather-policy","title":"Wetterregelung","preview":"Ganzjähriger Betrieb.","content":["Ganzjähriger Betrieb.","Leichter Regen: Die Tour läuft wie geplant — der Yonggungsa im Regen hat seine eigene Atmosphäre, und Gamcheons Gassen bleiben begehbar.","Starker Regen oder Sturm: Der Guide kann die Route anpassen, weil der untere Tempelbereich am Yonggungsa rutschig werden kann und Gamcheons Treppen unsicher sein können.","Wetter auf Taifun-Niveau: Volle Rückerstattung oder Umbuchung wird angeboten."]},{"id":"inclusions","title":"What''s included","preview":"Kleingruppen-Minibus (max. ≈12 Gäste), zertifizierter englischsprachiger Guide, Kraftstoff/Maut/Parken.","content":["Kleingruppen-Minibus (max. ≈12 Gäste), zertifizierter englischsprachiger Guide, Kraftstoff/Maut/Parken.","Alle Ankerattraktionen sind EINTRITTSFREI: Haedong Yonggungsa, Cheongsapo-Daritdol-Observatorium, Kulturdorf Gamcheon, Dakbatgol-Wandmalereidorf (Monorail an der „Wunschtreppe“ kostenlos).","Sky-Capsule-Ticket: bei der Buchung wählbar — inbegriffen (wir reservieren die Kapseln für Ihre Gruppe vorab; Basis: 2 Personen pro Kapsel) oder nicht inbegriffen (kostenloser Green-Railway-Holzsteg, die Uferpromenade, oder Busfahrt nach Mipo).","Nicht inbegriffen: Mittagessen (≈ ₩10,000–15,000), Getränke, persönliche Ausgaben, Trinkgelder."]},{"id":"language","title":"Sprache","preview":"Haupt-Toursprache: Englisch.","content":["Haupt-Toursprache: Englisch.","Chinesischsprachiger Guide auf Anfrage verfügbar — bitte mindestens 3 Tage im Voraus buchen.","Koreanisch begegnet Ihnen den ganzen Tag auf Speisekarten, Schildern und an Ständen; der Guide übernimmt die Übersetzung."]},{"id":"walking","title":"Walking & terrain","preview":"Mittlerer Schwierigkeitsgrad mit kurzen fordernden Abschnitten.","content":["Mittlerer Schwierigkeitsgrad mit kurzen fordernden Abschnitten.","Am Yonggungsa führen 108 Steinstufen hinab und wieder hinauf.","Der Daritdol-Skywalk ist eben (Glasboden, Schuhüberzieher werden gestellt).","Die Sky-Capsule-Stationen sind eben mit wenigen Bahnsteigstufen.","Gamcheon besteht aus Hanggassen und Treppen — tragen Sie bequeme Schuhe.","Dakbatgols „Wunschtreppe“ ist steil, doch die kostenlose Monorail übernimmt den Aufstieg.","Gesamtstrecke zu Fuß etwa 4–5 km."]},{"id":"capsule","title":"Sky Capsule (Ticket-Option)","preview":"Inbegriffen oder nicht — Ihre Wahl bei der Buchung.","content":["Die Sky Capsule fährt 2,3 km auf einer aufgeständerten Trasse zwischen Cheongsapo und Mipo (~30 Min.), in pastellfarbenen 4-Sitzer-Kabinen über der Küstenlinie.","Option mit Ticket: Wir reservieren die Kapseln für Ihre Gruppe vorab (Preis pro Kapsel ≈ ₩30,000 für 2 / ₩39,000 für 3 / ₩44,000 für 4, einfache Fahrt; die inbegriffene Option ist auf Basis von 2 Personen pro Kapsel kalkuliert).","Option ohne Ticket: Gehen Sie über den kostenlosen Green-Railway-Holzsteg (Uferpromenade, 2,3 km, ~30 Min., dieselbe Küste) oder fahren Sie mit dem Bus nach Mipo.","Der Betrieb ist wetterabhängig (starker Wind pausiert die Strecke); kann die Kapsel nicht fahren, halten der Weg über die Uferpromenade und der Bustransfer die Route im Zeitplan."]},{"id":"cancellation","title":"Stornierung","preview":"Kostenlose Stornierung bis 24 Stunden vor der Abholung.","content":["Kostenlose Stornierung bis 24 Stunden vor der Abholung.","Stornierungen am selben Tag und Nichterscheinen sind nicht erstattungsfähig."]}]'::jsonb, true), '{"bookingSupportSteps"}', '[{"timing":"Sofort","title":"Sofortige Bestätigung","detail":"Buchungsbestätigung mit Programmübersicht","description":"Sofortige Buchungsbestätigung mit Ihrem Abholfenster am Hotel (09:00–10:00) und allem, was Sie erwartet."},{"timing":"Am Vortag","title":"Abholdetails","detail":"Genauer Abholort und Fahrzeuginfo per WhatsApp","description":"Wettercheck und etwaige Routenhinweise (Danubi-Train-Tipp für Taejongdae, Gezeiten am Yonggungsa) werden am Vortag gesendet."},{"timing":"Am Morgen","title":"Abholbestätigung","detail":"Der Fahrer meldet sich 10 Minuten vor Ankunft","description":"Kennzeichen des Vans und Kontakt des Guides werden am Vorabend bestätigt."},{"timing":"Während der Tour","title":"Betreuung unterwegs","detail":"Direkter Draht zum Einsatzteam","description":"Eine Nachricht am Vorabend bestätigt Ihre genaue Abholzeit am Hotel; eine Nachricht am Morgen deckt die aktuelle Verkehrslage ab."},{"timing":"Am Tagesende","title":"Flexibler Ausstieg","detail":"Ausstieg wahlweise in Nampo-dong, am Bahnhof Busan, in Seomyeon oder Haeundae","description":"Der Guide erzählt an jedem Stopp vor Ort — Yonggungsas Gründung 1376, die 22-Nationen-Geschichte des UNMCK, Gamcheons Ursprung als Flüchtlingssiedlung von 1955."},{"timing":"Nach der Tour","title":"Bewertung & Nachbetreuung","detail":"Optionale Bewertung und Nachfassen","description":"Nach der Tour senden wir eine Feedback-Anfrage; Fragen zu Restaurantempfehlungen in Busan beantworten wir noch am selben Tag."}]'::jsonb, true), '{"staticQuestions"}', '[{"question":"Ist das Sky-Capsule-Ticket inbegriffen?","answer":"Ihre Wahl bei der Buchung. Buchen Sie die Option mit Ticket, reservieren wir die Kapseln für Ihre Gruppe im Voraus (Preis pro Kapsel: etwa ₩30,000 für 2 / ₩39,000 für 3 / ₩44,000 für 4, einfache Fahrt — die inbegriffene Option ist auf Basis von 2 Personen pro Kapsel kalkuliert). Buchen Sie die Basisoption, können Sie stattdessen den kostenlosen Green-Railway-Holzsteg (Uferpromenade) entlanggehen oder mit dem Bus nach Mipo fahren, während andere die Kapsel nehmen."},{"question":"Muss ich die Sky Capsule im Voraus reservieren?","answer":"Sonnenuntergangs- und Wochenendtermine sind 1–2 Wochen im Voraus ausverkauft. Wählen Sie die Option mit inbegriffenem Ticket, übernehmen wir die Reservierung für Ihre Gruppe, sobald die Buchung bestätigt ist. Tickets am Automaten am selben Tag sind an ruhigen Wochentagen möglich, aber nicht garantiert."},{"question":"Ist das Mittagessen inbegriffen?","answer":"Nein — das Mittagessen ist separat (etwa ₩10,000–15,000). Der Guide empfiehlt lokale Optionen nahe Haeundae/Mipo wie dwaeji-gukbap (Busans typische Schweinefleisch-Reissuppe), milmyeon (kalte Weizennudeln) oder ein Fischrestaurant."},{"question":"Wie viel wird gelaufen und wie steil ist es?","answer":"Moderat bis anspruchsvoll in kurzen Abschnitten: 108 Stufen hinab und wieder hinauf am Yonggungsa, ebener Glas-Skywalk am Daritdol, überwiegend eben an den Kapselstationen, Hanggassen in Gamcheon und Treppen in Dakbatgol — wo die kostenlose Monorail den Aufstieg für Sie übernimmt. Die Gesamtstrecke zu Fuß beträgt etwa 4–5 km."},{"question":"Ist die Tour für Kinder oder Senioren geeignet?","answer":"Ja, für die meisten aktiven Reisenden. Kinder lieben den Glasboden und die Kapsel; die Dakbatgol-Monorail erspart den steilsten Anstieg. Die Yonggungsa-Treppen und Gamcheons Steigungen sind die beiden fordernden Abschnitte — gehen Sie sie langsam an und lassen Sie Seitengassen bei Bedarf aus."},{"question":"Worin unterscheidet sich diese Tour von der Busan-Top-Attraktionen-Tagestour?","answer":"Gleicher Veranstalter, anderer Schwerpunkt. Die Top-Attraktionen-Tour deckt die klassische Stadtrunde ab (UN-Gedenkfriedhof, Jagalchi-Markt). Diese Kleingruppen-Route setzt voll auf Küste und Dörfer: ein eigener Stopp am Daritdol-Skywalk, die Fahrt mit der Sky Capsule mit Option auf inbegriffenes Ticket und das stille Dakbatgol-Wandmalereidorf, das die großen Busse auslassen."},{"question":"Wo holen Sie ab und wo setzen Sie ab?","answer":"Die Abholung erfolgt von Tür zu Tür an Ihrem Hotel im Zentrum Busans, zwischen 09:00 und 10:00 — die genaue Zeit wird am Vorabend per WhatsApp bestätigt. Die Rückgaben erfolgen der Reihe nach: Nampo-dong ≈17:10, Bahnhof Busan ≈17:30, Seomyeon ≈17:50, Haeundae ≈18:20."},{"question":"Was passiert bei Regen?","answer":"Die Tour findet bei jedem Wetter statt. Kapsel und Monorail fahren bei normalem Regen (sie pausieren nur bei starkem Wind), am Skywalk werden Schuhüberzieher gestellt, und die Dorfgassen bleiben mit Regenschirm begehbar. Bei schwerem Wetter kann sich die Außenzeit auf den Tempelterrassen verkürzen."}]'::jsonb, true), '{"pickup_dropoff"}', '{"departure":[{"order":1,"time":"09:00–10:00","name":"Ihr Hotel im Zentrum von Busan (von Tür zu Tür)","type":"hotel","note":"Abholung von Tür zu Tür an Hotels im Zentrum Busans — Seomyeon, Nampo-dong / Bahnhof Busan, Haeundae / Marine City. Die genaue Zeit wird am Vorabend bestätigt.","lat":35.15782,"lng":129.06003}],"return":[{"order":1,"name":"Nampo-dong / Jagalchi area","type":"station","lat":35.09663,"lng":129.0308},{"order":2,"name":"Busan Station (Exit 4)","type":"station","lat":35.11449,"lng":129.03933},{"order":3,"name":"Seomyeon Station (Exit 4)","type":"station","lat":35.15782,"lng":129.06003},{"order":4,"name":"Haeundae Station (Exit 5)","type":"station","lat":35.16396,"lng":129.15853}],"notes":["Die Abholung erfolgt von Tür zu Tür an Ihrem Hotel im Zentrum Busans zwischen 09:00 und 10:00; die genaue Zeit wird am Vorabend bestätigt. Die Rückgaben erfolgen an vier zentralen Punkten der Reihe nach (Nampo-dong → Bahnhof Busan → Seomyeon → Haeundae, ≈ 17:10–18:20) — sagen Sie der Reiseleitung im Laufe des Nachmittags, welchen Sie wünschen."]}'::jsonb, true), '{"matching_profile"}', '{"profile_version":1,"is_active":true,"product_id":"busan-small-group-yonggungsa-skycapsule-gamcheon-tour","product_type":"small_group","route_type":"fixed_route","destination_region":"busan_city","region_type":"busan_city","vehicle_type":"coach","duration_hours":9,"region_tags":["busan_haeundae","busan_gijang","busan_namgu","busan_saha","busan_jung"],"theme_tags":["temple","coastal","war_memorial","mural_village","fish_market","korean_war_history"],"poi_tags":["haedong_yonggungsa","cheongsapo_daritdol_observatory","cheongsapo_blue_line_park","gamcheon_culture_village","dakbatgol_mural_village"],"pace_level":0.7,"walking_level":0.85,"scenic_level":0.9,"photo_level":1,"culture_level":0.95,"relax_level":0.5,"first_time_fit":1,"family_fit":0.85,"senior_fit":0.7,"couple_fit":0.95,"solo_traveler_fit":0.9,"active_traveler_fit":0.8,"adult_family_fit":1,"family_with_teens_fit":0.95,"young_kids_fit":0.55,"senior_active_fit":0.7,"senior_general_fit":0.55,"mobility_friendly_fit":0.4,"stroller_fit":0.4,"one_day_fit":1,"same_day_flight_fit":0.3,"rain_fit":0.5,"value_for_money_fit":0.95,"iconic_landmark_fit":1,"cafe_fit":0.7,"food_fit":0.8,"nature_fit":0.8,"beach_fit":0.6,"nightlife_fit":0.2,"shopping_fit":0.2,"no_shopping_fit":0.5,"local_culture_fit":1,"storytelling_fit":0.8,"unesco_fit":0,"intangible_heritage_fit":0.2,"indoor_ratio":0.2,"weather_sensitivity":0.5,"comfort_level":0.6,"budget_fit":0.85,"premium_fit":0.3,"small_group_fit":1,"private_fit":0.05,"bus_fit":1,"price_band":"mid","pickup_base":"busan_central","return_time_band":"17:00-18:30","duration_band":"9h","min_recommended_age":8,"hard_constraints":{"avoidIf":["mobility_limited"],"notIdealFor":["very_low_mobility","stroller_heavy_groups"]},"walking_notes":["Active walking day with several flights of stairs (Yonggungsa 108 steps, Gamcheon hillside).","Average fitness expected.","Sturdy closed-toe shoes recommended (Jagalchi 1F floor is wet)."],"keywords":["busan top attractions day tour","busan small group tour","haedong yonggungsa","gamcheon culture village","jagalchi market","un memorial cemetery busan"],"synonym_hints":["busan one day classic tour","busan must-see day trip","busan top 5 highlights"],"seasonality":"year_round","pickup_base_normalized":"busan","vehicle_type_legacy":"bus_coach","anchor_poi_keys":["haedong_yonggungsa","cheongsapo_daritdol_observatory","cheongsapo_blue_line_park","gamcheon_culture_village","dakbatgol_mural_village"],"private_tour_fit":0.05,"customizable_route_fit":0.1,"flexibility_fit":0.3,"fixed_itinerary_fit":1,"buddhist_temple_fit":1,"scenic_temple_fit":1,"coastal_temple_fit":1,"seaside_temple_fit":1,"war_memorial_fit":1,"korean_war_history_fit":1,"mural_village_fit":1,"fish_market_fit":1,"market_fit":1,"street_food_fit":0.9,"skywalk_fit":1,"sky_capsule_fit":0.7,"coastal_railway_fit":1,"history_culture_fit":1,"k_drama_filming_fit":0.5,"religious_history_fit":0.85,"premium_dining_fit":0.3,"seasonal_fit":0.85,"china_mainland_market_fit":0,"korea_domestic_market_fit":0,"taiwan_market_fit":1,"singapore_market_fit":1,"hong_kong_market_fit":1,"china_diaspora_overseas_market_fit":0.95,"se_asia_market_fit":0.95,"us_market_fit":0.85,"europe_market_fit":0.85,"australia_market_fit":0.85,"japan_market_fit":0.85,"busan_signature_route_fit":1,"skywalk_coastal_railway_fit":1,"first_time_busan_fit":1,"no_inter_city_travel_fit":1,"differentiates_from_busan_gyeongju_routes":true,"deep_history_traveler_fit_minimum":0.7,"english_speaking_guide_provided":true,"chinese_speaking_guide_available_on_advance_notice":true,"japanese_speaking_guide_available_on_advance_notice":true}'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'busan-small-group-yonggungsa-skycapsule-gamcheon-tour' AND locale = 'de';

