UPDATE public.tour_product_pages SET
  duration_label = '≈ 9 ore',
  stops_count = 9,
  detail_payload = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(detail_payload, '{"seo"}', '{"pageTitle":"Tour di Busan in piccolo gruppo: Yonggungsa, Sky Capsule, Gamcheon | AtoC Korea","metaDescription":"Tour giornaliero di 9 ore a Busan in piccolo gruppo: tempio Haedong Yonggungsa, passerella di vetro Daritdol di Cheongsapo, Sky Capsule del Blueline Park (biglietto opzionale), villaggio culturale di Gamcheon, villaggio dei murales Dakbatgol e monorotaia.","title":"Tour di Busan in piccolo gruppo: tempio sul mare, Sky Capsule e villaggi culturali | AtoC","description":"Tour giornaliero di Busan in piccolo gruppo: Haedong Yonggungsa → osservatorio Daritdol di Cheongsapo → Sky Capsule del Blueline Park (biglietto incluso/escluso — a vostra scelta) → pranzo → villaggio culturale di Gamcheon → villaggio dei murales Dakbatgol e monorotaia della scalinata dei desideri.","primaryKeywords":["tour Busan piccolo gruppo","tour Haedong Yonggungsa","Sky Capsule Blueline Park","tour villaggio culturale Gamcheon","osservatorio Daritdol Cheongsapo"],"ogImage":"https://www.atockorea.com/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp"}'::jsonb, true), '{"catalog_card"}', '{"slug":"busan-small-group-yonggungsa-skycapsule-gamcheon-tour","title":"Busan in piccolo gruppo: tempio sul mare, Sky Capsule e villaggi culturali","subtitle":"Tour giornaliero in piccolo gruppo tra le icone costiere e i villaggi collinari di Busan — il tempio sul mare Haedong Yonggungsa, la passerella di vetro dell''osservatorio Daritdol di Cheongsapo, la corsa in Sky Capsule del Blueline Park (biglietto opzionale al momento della prenotazione), il villaggio culturale di Gamcheon e il tranquillo villaggio dei murales Dakbatgol con la monorotaia della scalinata dei desideri.","region":"Busan","duration":"≈ 9 ore","stopsCount":9,"rating":0,"reviewCount":0,"badges":["Piccolo gruppo","Busan","Sky Capsule","Costa","Villaggi culturali"],"tags":["Piccolo gruppo","Busan","Sky Capsule","Costa","Villaggi culturali","Ideale per la prima visita"],"heroImage":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","thumbnail":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","priceLabel":"","shortCardDescription":"Una giornata a Busan in piccolo gruppo costruita intorno alla costa e ai villaggi collinari: il tempio sul mare Haedong Yonggungsa nella sua quieta finestra mattutina, l''osservatorio Daritdol di Cheongsapo con pavimento di vetro e ingresso gratuito, la corsa in Sky Capsule del Blueline Park da Cheongsapo a Mipo (biglietto incluso o escluso — a vostra scelta alla prenotazione), il pranzo, il villaggio culturale di Gamcheon e il poco conosciuto villaggio dei murales Dakbatgol, dove una monorotaia gratuita risale la ''scalinata dei desideri''. Ogni tappa principale, tranne la capsula opzionale, è a ingresso gratuito."}'::jsonb, true), '{"hero"}', '{"imageUrl":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","imagePosition":"center 40%","images":["/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp"],"tagline":"Il tempio sul mare di Busan nella sua ora più quieta, una passerella di vetro sospesa sull''acqua, una corsa in capsula pastello lungo la costa e due villaggi collinari — uno celebre, uno ancora autenticamente locale","pills":["Piccolo gruppo","Busan","Ideale per la prima visita"],"meta":{"duration":"≈ 9 ore (prelievo in hotel alle 09:00, ultimo rientro in centro ≈ 17:50)","region":"Busan","stops":"9 tappe","rating":0,"ratingStars":0}}'::jsonb, true), '{"itineraryStops"}', '[{"number":1,"time":"≈ 09:00–10:00","duration":"60 min","name":"Prelievo (il vostro hotel nel centro di Busan)","category":"Trasferimento / Prelievo in hotel","description":"Prelievo porta a porta presso il vostro hotel nel centro di Busan, tra le **09:00 e le 10:00**. L''orario esatto viene confermato via WhatsApp la sera prima, quando l''autista ha l''elenco degli hotel della giornata e può ordinare il giro in modo efficiente — chi alloggia sul lato Haeundae viene di norma prelevato per ultimo, perché il pullman lascia la città verso nord-est, in direzione di Gijang-gun e della prima tappa.\n\nL''area servita comprende i principali poli alberghieri del centro: **Seomyeon**, **Nampo-dong / stazione di Busan** e **Haeundae / Marine City**. Se il vostro hotel si trova fuori da quest''area, la guida indicherà il punto d''incontro più vicino alla conferma della prenotazione.\n\nVi preghiamo di attendere nella hall 5 minuti prima dell''orario confermato. Il trasferimento dall''ultimo prelievo a Haedong Yonggungsa richiede circa 30-40 minuti a seconda del traffico.","image":null,"highlights":["Prelievo porta a porta negli hotel del centro di Busan, 09:00–10:00","Orario esatto confermato via WhatsApp la sera prima","Pullman in piccolo gruppo (max ~14 pax)","Scheda itinerario stampata in coreano e inglese alla partenza"],"timeUsed":["Prelievi negli hotel del centro di Busan (~40 min)","Trasferimento verso nord-est a Gijang-gun (~20 min)"],"whyOnRoute":"Il prelievo in hotel elimina del tutto il trasferimento mattutino: niente metropolitana all''alba, niente uscite di stazione da cercare. Il giro procede da ovest a est, così il pullman termina vicino a Haeundae e lascia la città già orientato verso Gijang e la prima tappa della giornata.","_poi_meta":{"match":"transit_only","poi_key":"OPS_busan_hotel_pickup_central","sources":["AtoC Korea operations"],"verified":true,"verified_date":"2026-08-05"},"images":[],"imageCredits":[],"galleryItems":[],"_role":"pickup"},{"name":"Tempio Haedong Yonggungsa","time":"≈ 10:20","number":2,"category":"Tempio buddhista / Costiero","duration":"60 min","timeUsed":["Discesa dal minibus + passeggiata tra le bancarelle fino al piazzale d''ingresso (~10 min)","Dodici Generali dello Zodiaco + pagoda contro gli incidenti (~10 min)","Discesa dei 108 gradini + sala principale Daeungjeon + terrazze sul mare (~25 min)","Belvedere della statua Haesu Gwaneum + tempo per le foto (~10 min)","Risalita + ritrovo al minibus (~5 min)"],"_poi_meta":{"match":"exact","poi_key":"haedong_yonggungsa","sources":["Visit Busan","VisitKorea","Wikipedia","Culture Trip","Korean Temple Guide","Korea Tourism Organization Official"],"verified":true,"kb_version":"1.24","verified_date":"2026-04-29"},"highlights":["**Fondato nel 1376** dal maestro buddhista Naong Hyegeun (in origine ''Bomunsa'')","Uno dei pochissimi grandi templi coreani affacciati sul mare (la maggior parte è in montagna)","Ribattezzato **Haedong Yonggungsa nel 1974** dopo la visione del drago e della Dea avuta dal monaco Jeong-am","**108 gradini di pietra** = le 108 illusioni della mente nel buddhismo","**12 Sibiji-shin (Generali dello Zodiaco)** all''ingresso; santuario delle monete della ''**pagoda contro gli incidenti**''","**Haesu Gwaneum Daebul** (Dea della Misericordia del mare) — la veduta più fotografata della scogliera","Sala principale Daeungjeon restaurata nel 1970 con cura per i colori originali","Orari tutti i giorni 04:30-19:20, ingresso GRATUITO; festival delle lanterne per il compleanno di Buddha (maggio)","**La fila di colonne di pietra dei 12 Generali dello Zodiaco Sibiji-shin alla porta del tempio** — unica tra i templi costieri coreani"],"smartNotes":{"tip":"Per entrare nelle sale usate le porte laterali (la porta frontale è riservata ai monaci); il compleanno di Buddha (apr–mag) porta l''esposizione delle lanterne; arrivate prima delle 10:30 per evitare la folla peggiore dei pullman turistici","photo":"La roccia dell''alba sul bordo verso il mare; la scalinata accanto alla sala Daeungjeon regala la classica inquadratura di oceano e tempio; la statua Haesu Gwaneum dalla scogliera superiore offre la veduta grandangolare di tempio e Mare Orientale","facilities":"Bancarelle di souvenir/snack e piccolo caffè al piazzale superiore; il sentiero costiero prosegue lungo le rocce"},"whyOnRoute":"**L''apertura iconica dell''itinerario — il tempio più fotografato di Busan nella sua ora più quieta.** L''arrivo alle 10:20 precede la grande ondata dei pullman turistici (in genere dalle 11:00), così la discesa dei 108 gradini e il belvedere della Haesu Gwaneum restano percorribili senza code. La sua posizione sulla scogliera di Gijang, inoltre, fa iniziare la giornata dal punto più a nord-est dell''itinerario, così tutto ciò che segue scorre in un''unica direzione lungo la costa — prima Cheongsapo, poi la corsa in capsula verso la città — senza mai tornare indietro.","convenience":{"parking":"Parcheggio di Haedong Yonggungsa (a pagamento, secondo il sito ufficiale Visit Busan)","restroom":"Disponibili vicino all''ingresso principale e all''interno del complesso"},"description":"**Haedong Yonggungsa (해동 용궁사) — il tempio buddhista sul mare più famoso della Corea** — è arroccato sulle scogliere rocciose di Gijang-gun, sulla costa nord-orientale di Busan: uno dei pochissimi grandi templi coreani NON collocato in montagna. Fu fondato in origine nel **1376, durante la dinastia Goryeo, dal grande maestro buddhista Naong Hyegeun (나옹 혜근, 1320-1376)** — consigliere reale e maestro che avrebbe contribuito a plasmare il buddhismo coreano fino agli albori dell''era Joseon. \n\nSecondo la leggenda, Naong praticava l''ascesi al tempio Bunhwangsa di Gyeongju durante una siccità nazionale; il dio del Mare Orientale gli apparve in sogno e gli disse che costruire un tempio sul monte Bongrae (il nome originario di questa scogliera sul mare) avrebbe restituito prosperità al regno. \n\nNaong fondò il tempio e lo chiamò **Bomunsa**, dedicandolo a Gwanseum-bosal (관세음보살, il Bodhisattva della Compassione). Il tempio fu distrutto durante l''**invasione giapponese Imjin del 1592** e rimase in rovina per oltre 300 anni, finché **il monaco Ungang del tempio Tongdosa non ne avviò la ricostruzione nei primi anni Trenta del Novecento**. \n\nIl nome attuale, **Haedong Yonggungsa (tempio del Palazzo del Drago di Corea)**, risale soltanto al **1974** — quando il monaco superiore Jeong-am, durante una preghiera di 100 giorni (jeong-geon kido), ebbe la visione della Dea della Misericordia che discendeva sul dorso di un drago, irradiando una luce multicolore. \n\nIl tempio fu ribattezzato in onore di questa visione. La visita segue il caratteristico percorso processionale del tempio: attraverso la fila dei **12 Sibiji-shin (i Dodici Generali dello Zodiaco)** nel piazzale d''ingresso, oltre la **pagoda a 7 piani ''contro gli incidenti''** (dove gli automobilisti lasciano monete in offerta sotto un santuario di pietra a forma di ruota), giù per i celebri **108 gradini di pietra** (che rappresentano le 108 illusioni della mente buddhista) attraverso un piccolo boschetto di bambù, fino alle terrazze sul mare e alla sala principale Daeungjeon. \n\nLa **Haesu Gwaneum Daebul** (statua della Dea della Misericordia del mare) sulla scogliera superiore è la veduta più fotografata, e incornicia insieme i tetti del tempio e il Mare Orientale. \n\nOrari **04:30-19:20 tutti i giorni, ultimo ingresso 18:50, ingresso GRATUITO**. Il **compleanno di Buddha (maggio)** porta le installazioni di lanterne del festival Yeondunhoe.","visitBasics":{"hours":"Tutti i giorni 04:30–19:20 (ultimo ingresso 18:50)","closed":"Aperto tutto l''anno","walking":"Moderato — 108 gradini attraverso una pineta, diverse terrazze sul mare e scalinate","admission":"Gratuito; il parcheggio per auto private è a pagamento"},"image":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","images":["/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp"],"imageCredits":[{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 1","alt":"Haedong Yonggungsa Temple — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 2","alt":"Haedong Yonggungsa Temple — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 3","alt":"Haedong Yonggungsa Temple — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 4","alt":"Haedong Yonggungsa Temple — gallery image 4"},{"id":5,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 5","alt":"Haedong Yonggungsa Temple — gallery image 5"},{"id":6,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 6","alt":"Haedong Yonggungsa Temple — gallery image 6"}]},{"number":3,"time":"≈ 11:40","duration":"40 min","name":"Osservatorio Daritdol di Cheongsapo (passerella di vetro)","category":"Osservatorio costiero / Gratuito","description":"L''**osservatorio Daritdol di Cheongsapo (청사포 다릿돌전망대)** è una **passerella di 72,5 metri che si incurva sul mare a circa 20 metri sopra l''acqua**, inaugurata nell''agosto 2017 sulla scogliera costiera tra Cheongsapo e Songjeong. Il nome viene dai **daritdol — i cinque scogli ''pietre di guado''** che punteggiano il mare sotto la piattaforma e che, si dice, avanzano verso l''orizzonte come un ponte. Il tratto finale del pavimento è in **vetro**, con copriscarpe forniti per proteggere (e mettere alla prova la vostra fiducia!) le lastre mentre le onde rotolano sotto i vostri piedi. L''ingresso è **gratuito**. Tornando al villaggio, i **fari gemelli di Cheongsapo** (uno rosso, uno bianco) e il piccolo passaggio pedonale della stazione, reso celebre dalla sua inquadratura in stile anime alla Slam Dunk, sono a due passi.","image":null,"highlights":["**Passerella di 72,5 m, ~20 m sopra il mare** — inaugurata nell''agosto 2017, GRATUITA","Prende il nome dai cinque **scogli daritdol, le ''pietre di guado''** visibili sotto la piattaforma","**Tratto con pavimento di vetro** all''estremità verso il mare (copriscarpe forniti)","**Fari gemelli di Cheongsapo** (rosso + bianco) a due passi","Cheongsapo è una delle **otto vedute panoramiche** di Busan — un villaggio di pescatori ancora attivo","Il passaggio pedonale della stazione, celebre spot fotografico in stile anime"],"timeUsed":["Discesa dal minibus + passeggiata fino all''ingresso della passerella (~5 min)","Percorso sulla passerella + tratto con pavimento di vetro (~20 min)","Passeggiata fotografica ai fari gemelli / passaggio pedonale (~10 min)","Ritrovo per la stazione della capsula (~5 min)"],"whyOnRoute":"**Il brivido gratuito tra il tempio e la capsula.** Il Daritdol regala alla giornata il suo momento sospeso sul mare — un pavimento di vetro con le onde che rotolano sotto — senza biglietto, e sorge proprio sulla scogliera di Cheongsapo, così si concatena con l''imbarco sulla Sky Capsule a pochi minuti di distanza. Vedere prima la costa dalla passerella fissa fa leggere in modo diverso, dieci minuti dopo, il panorama in movimento dalla capsula.","_poi_meta":{"match":"authored","poi_key":"cheongsapo_daritdol_observatory","sources":["Visit Busan","Busan Metropolitan City Tourism","Blue Line Park official"],"verified":false,"verified_date":"2026-08-04"},"smartNotes":{"tip":"Nei giorni ventosi la piattaforma chiude occasionalmente — la guida verifica le condizioni e, se necessario, riordina le tappe di Cheongsapo","photo":"Fotografate verso il basso attraverso il vetro gli scogli daritdol; la curva della piattaforma vista dal sentiero costiero regala il miglior scatto panoramico","facilities":"Caffè e bancarelle di pesce nel villaggio di Cheongsapo, in basso"},"convenience":{"parking":"Fermata del minibus al villaggio di Cheongsapo; breve passeggiata fino alla piattaforma","restroom":"Servizi pubblici nei pressi della stazione di Cheongsapo"},"visitBasics":{"hours":"Accesso libero; osservatorio presidiato indicativamente 09:00–18:00 (in base a stagione/meteo)","closed":"Può chiudere temporaneamente in caso di forte vento o tempesta","walking":"Percorso pianeggiante sulla piattaforma; breve pendenza dal villaggio","admission":"GRATUITO (copriscarpe forniti per il tratto in vetro)"},"images":[],"imageCredits":[],"galleryItems":[]},{"number":4,"time":"≈ 12:30","duration":"50 min","name":"Sky Capsule dello Haeundae Blueline Park (Cheongsapo → Mipo)","category":"Attrazione costiera / Biglietto opzionale","description":"La **Sky Capsule** è l''attrazione simbolo dello **Haeundae Blueline Park**, la riqualificazione ecologica del 2020 della dismessa ferrovia costiera Donghae Nambu: **cabine pastello da 4 posti che scivolano per 2,3 km su una rotaia sopraelevata a 7–10 metri sopra la costa** tra Cheongsapo e Mipo, con il mare da un lato per tutto il tragitto (~30 minuti). Saliamo a **Cheongsapo e viaggiamo verso Mipo**, dove il minibus è già ad attenderci — così la corsa fa anche da trasferimento della giornata lungo la costa. **Il biglietto della capsula è opzionale e si sceglie alla prenotazione**: con l''opzione con biglietto incluso riserviamo in anticipo le capsule per il vostro gruppo (il prezzo è per capsula: circa ₩30,000 per 2 / ₩39,000 per 3 / ₩44,000 per 4, sola andata); con l''opzione base potete percorrere la **passeggiata gratuita della Green Railway** — la premiata passerella costiera in legno di 2,3 km sotto la stessa rotaia — oppure semplicemente raggiungere Mipo in minibus.","image":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","highlights":["**Capsule pastello da 4 posti su una rotaia costiera sopraelevata** — l''attrazione simbolo del Blueline Park (inaugurata nel 2020)","**Cheongsapo → Mipo, 2,3 km / ~30 min**, vista mare per tutto il tragitto","**Biglietto incluso o escluso — a vostra scelta alla prenotazione** (prezzo per capsula ≈ ₩30,000 per 2 / ₩39,000 per 3 / ₩44,000 per 4, sola andata)","Chi non sale: **passeggiata gratuita in legno della Green Railway** lungo la stessa costa, oppure minibus fino a Mipo","La corsa finisce dove inizia il pranzo — Mipo è a due passi dalle vie gastronomiche di Haeundae","Funziona con pioggia normale; si ferma solo in caso di forte vento"],"timeUsed":["Imbarco alla stazione di Cheongsapo (~15 min)","Corsa in Sky Capsule Cheongsapo → Mipo (~35 min)"],"whyOnRoute":"**La corsa che è anche il trasferimento.** Salire a Cheongsapo subito dopo la passerella significa che la capsula vi porta lungo la stessa identica costa che avete appena ammirato dall''alto — e vi lascia a Mipo, dove il minibus e le vie del pranzo sono già ad aspettarvi. Nulla della giornata devia per farle spazio: rinunciate al biglietto e il minibus o la passeggiata gratuita coprono lo stesso tratto.","_poi_meta":{"match":"partial","poi_key":"cheongsapo_blue_line_park","sources":["Blue Line Park official","Visit Busan","Busan Metropolitan City Tourism"],"verified":true,"kb_version":"1.24","verified_date":"2026-08-04"},"smartNotes":{"tip":"Le fasce del tramonto e del fine settimana si esauriscono con 1–2 settimane di anticipo — scegliete l''opzione con biglietto incluso alla prenotazione e le riserviamo noi per voi","photo":"Sedetevi sul lato mare (lato destro in direzione Mipo); la curva oltre il tunnel di Dalmaji è l''inquadratura simbolo","facilities":"Caffè e minimarket al piazzale di Mipo; biglietterie automatiche in entrambe le stazioni"},"convenience":{"parking":"Il minibus attende il gruppo al piazzale della stazione di Mipo","restroom":"In entrambe le stazioni di Cheongsapo e Mipo"},"visitBasics":{"hours":"≈ 09:30–18:30 (prolungati fino a sera in alta stagione)","closed":"Dipende dal meteo; il forte vento sospende il servizio","walking":"Banchine di stazione in piano; l''alternativa a piedi è di 2,3 km (~30 min) su passerella in legno","admission":"Per capsula, sola andata: ≈ ₩30,000 (2 pax) / ₩39,000 (3) / ₩44,000 (4) — opzione con biglietto incluso disponibile alla prenotazione"},"images":["/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","/images/tours/cheongsapo-blue-line/blueline-tram-cherry-sea.webp","/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-12-53-19.webp"],"imageCredits":[{"url":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","source":"atoc-korea"},{"url":"/images/tours/cheongsapo-blue-line/blueline-tram-cherry-sea.webp","source":"atoc-korea"},{"url":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","source":"atoc-korea"},{"url":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-12-53-19.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","location":"Sky Capsule dello Haeundae Blueline Park (Cheongsapo → Mipo)","caption":"Sky Capsule dello Haeundae Blueline Park (Cheongsapo → Mipo) — photo 1","alt":"Sky Capsule dello Haeundae Blueline Park (Cheongsapo → Mipo) — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/cheongsapo-blue-line/blueline-tram-cherry-sea.webp","location":"Sky Capsule dello Haeundae Blueline Park (Cheongsapo → Mipo)","caption":"Sky Capsule dello Haeundae Blueline Park (Cheongsapo → Mipo) — photo 2","alt":"Sky Capsule dello Haeundae Blueline Park (Cheongsapo → Mipo) — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","location":"Sky Capsule dello Haeundae Blueline Park (Cheongsapo → Mipo)","caption":"Sky Capsule dello Haeundae Blueline Park (Cheongsapo → Mipo) — photo 3","alt":"Sky Capsule dello Haeundae Blueline Park (Cheongsapo → Mipo) — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-12-53-19.webp","location":"Sky Capsule dello Haeundae Blueline Park (Cheongsapo → Mipo)","caption":"Sky Capsule dello Haeundae Blueline Park (Cheongsapo → Mipo) — photo 4","alt":"Sky Capsule dello Haeundae Blueline Park (Cheongsapo → Mipo) — gallery image 4"}]},{"name":"Pranzo (ristorante locale nei pressi di Haeundae/Mipo)","time":"≈ 13:25","number":5,"category":"Pasto locale","duration":"45 min","timeUsed":["Passeggiata dalla stazione di Mipo al ristorante (~5 min)","Pranzo (~35 min)","Ritrovo al minibus (~5 min)"],"_poi_meta":{"match":"lunch_placeholder","poi_key":"OPS_busan_lunch","sources":["Visit Busan","Busan Metropolitan Government cuisine guide"],"verified":true,"kb_version":"1.15","verified_date":"2026-04-29"},"highlights":[],"whyOnRoute":"**La pausa naturale tra la costa e i villaggi.** La corsa in capsula termina a Mipo all''ora di pranzo, e le vie gastronomiche di Haeundae sono a pochi passi dalla stazione — nessun tragitto extra per raggiungere un buon pasto. Fare rifornimento qui prepara ai due villaggi collinari del pomeriggio, dove la camminata è al suo tratto più verticale.","description":"Pranzo di circa 45 minuti nei pressi di Mipo/Haeundae, subito dopo l''arrivo della Sky Capsule. Opzioni tipiche consigliate dalla guida: il **dwaeji-gukbap (돼지국밥)** — la zuppa di riso in brodo di maiale simbolo di Busan, nata nell''epoca dei rifugiati della guerra di Corea (~₩10,000), i **milmyeon**, noodle freddi di grano, oppure una tavola di pesce vista porto. Il pranzo non è incluso (≈ ₩10,000–15,000), così potete scegliere secondo appetito e budget."},{"number":6,"time":"≈ 14:10","duration":"20 min","name":"Spiaggia di Haeundae","category":"Spiaggia / Gratis","description":"La **spiaggia di Haeundae (해운대해수욕장)** è il tratto di sabbia più noto della Corea: circa **1,5 km** di costa che si incurva tra l''isola di Dongbaekseom a ovest e Mipo a est, con lo skyline di Marine City alle spalle. Lo Sky Capsule vi lascia a Mipo, che non è altro che l''estremità orientale di questa spiaggia: la sosta non costa alla giornata un minuto di strada in più.\n\nVenti minuti sono una sosta da foto e piedi nell''acqua, non da bagno: si cammina sulla sabbia, si fotografa lo skyline e si torna al pullman. A luglio e agosto la spiaggia è al massimo dell''affollamento, con le file di ombrelloni montate; nel resto dell''anno è ampia, tranquilla e molto percorribile. Gratuita e aperta a ogni ora.","image":null,"highlights":["**La spiaggia più famosa della Corea** — ~1,5 km di sabbia, GRATUITA e aperta 24 ore","Lo skyline di Marine City dal bagnasciuga","L''isola di Dongbaekseom e la Nurimaru APEC House all''estremità ovest","Proprio a Mipo, dove finisce lo Sky Capsule — nessun trasferimento aggiuntivo"],"timeUsed":["Discesa sulla sabbia da Mipo (~5 min)","Foto della spiaggia e dello skyline (~10 min)","Ritrovo al pullman (~5 min)"],"whyOnRoute":"Il capsule arriva a Mipo, che è l''estremità est della spiaggia: la vista più famosa di Busan è quindi a cinque minuti a piedi e non costa nulla alla giornata. È una sosta volutamente breve: quanto basta per mettere piede sulla sabbia e fotografare lo skyline prima che il pomeriggio viri verso i villaggi in collina.","_poi_meta":{"match":"authored","poi_key":"haeundae_beach","sources":["Visit Busan","Busan Metropolitan City Tourism"],"verified":false,"verified_date":"2026-08-05"},"visitBasics":{"hours":"Aperta 24 ore","closed":"Mai","walking":"Sabbia pianeggiante e lungomare pavimentato","admission":"GRATIS"},"images":[],"imageCredits":[],"galleryItems":[]},{"name":"Villaggio culturale di Gamcheon","time":"≈ 15:10","number":7,"category":"Villaggio culturale / Arte murale","duration":"60 min","timeUsed":["Discesa dal minibus al parcheggio pubblico 2 + passeggiata fino all''ingresso (~5 min)","Centro informazioni turistiche + acquisto della mappa dei timbri (~10 min)","Belvedere Sky Garden + panchina del Piccolo Principe (~20 min)","Passeggiata nei vicoli tra i murales + pausa in un piccolo caffè (~20 min)","Ritrovo al minibus (~5 min)"],"_poi_meta":{"match":"exact","poi_key":"gamcheon_culture_village","sources":["Wikipedia","CNN","Visit Busan","Hapskorea","Columban Society","Lifeguin","Busan Cultural Foundation"],"verified":true,"kb_version":"1.24","verified_date":"2026-04-29"},"highlights":["**''La Machu Picchu della Corea'' / ''la Santorini della Corea''** — premio UN-HABITAT Asian Townscape Award 2012","Origini: trasferimenti dell''amministrazione di Busan negli **anni Venti-Trenta** + **rifugiati Taegeukdo del 1955** (~800 famiglie)","**La filosofia Taegeukdo del ''lasciar prosperare gli altri''** = nessuna casa blocca la vista di quella dietro","**2009 ''Dreaming of Machu Picchu'' + 2010 ''Miro Miro''**: i progetti di arte pubblica del Ministero della Cultura","**La panchina del ''Piccolo Principe e la Volpe''** allo Sky Garden — il punto più fotografato del villaggio","**~1,4 milioni di visitatori l''anno** dalla rigenerazione tramite arte pubblica","**Comunità residenziale viva** — voce bassa, niente droni, niente flash verso le case","Ingresso al villaggio gratuito; mappa dei timbri opzionale ~₩2,000","**Premio UN-HABITAT Asian Townscape Award 2012** — riconoscimento al progetto artistico ''Dreaming of Machu Picchu'' del 2009 che ha trasformato l''insediamento di rifugiati Taegeukdo del 1955 nel villaggio dei murales simbolo di Busan"],"smartNotes":{"tip":"Qui vivono i residenti — parlate a bassa voce, niente droni, portate via i rifiuti; indossate scarpe con buona presa per i vicoli ripidi; l''ora dorata del pomeriggio, ~16:00-17:00, è la luce migliore del villaggio","photo":"La panchina del Piccolo Principe e la Volpe (lunga coda) e l''osservatorio Haneul Maru / Sky Garden per la veduta panoramica sui tetti arcobaleno e sulla baia","facilities":"Noleggio hanbok, botteghe artigiane, bancarelle di dolciumi coreani, caffè; piccolo museo del villaggio all''ingresso; la mappa dei timbri è il modo più semplice per orientarsi"},"whyOnRoute":"**Il villaggio protagonista del pomeriggio — l''anfiteatro pastello di Busan.** Dopo la mattinata costiera, la giornata attraversa la città verso le colline occidentali, dove le terrazze di Gamcheon, nate come insediamento di rifugiati della guerra di Corea e rinate come villaggio d''arte nel 2009, si impilano in colori pastello sopra il mare. Il percorso di 90 minuti copre i belvedere, la balaustra del Piccolo Principe e il tempo per perdersi nei vicoli — e si abbina di proposito al quieto Dakbatgol subito dopo, così vedete sia il villaggio celebre sia quello locale che i pullman saltano.","convenience":{"parking":"Parcheggio pubblico 2 di Gamcheon (a pagamento)","restroom":"Servizi pubblici al centro informazioni turistiche e intorno ai belvedere principali"},"description":"Il **villaggio culturale di Gamcheon (감천문화마을)** — soprannominato sia **''la Machu Picchu della Corea''** sia **''la Santorini della Corea''** — è un quartiere collinare di Saha-gu, nella Busan occidentale, le cui case dipinte in colori pastello scendono a cascata in file terrazzate lungo il pendio. \n\nL''insediamento nacque negli **anni Venti-Trenta del Novecento**, quando l''amministrazione di Busan trasferì i residenti della classe operaia lontano dal porto. Il carattere del villaggio si definì nel **1955**, quando **~800 famiglie (circa 4.000 persone) della comunità religiosa Taegeukdo** — una religione sincretica unicamente coreana che fonde elementi buddhisti, confuciani e dello yin-yang, fondata da **Jo Cheol-je** durante il periodo coloniale giapponese — si stabilirono qui come rifugiati della guerra di Corea in fuga dal Nord. \n\nLa filosofia Taegeukdo del ''**lasciar prosperare gli altri**'' plasmò direttamente il tratto più distintivo del villaggio: le case sono volutamente disposte a gradoni, così che **nessun tetto blocchi la vista della casa retrostante**, con l''intera comunità aperta al cielo e al mare. Gamcheon rimase uno dei quartieri più poveri di Busan fino al **2009**, quando il Ministero della Cultura coreano lanciò il progetto di rigenerazione tramite arte pubblica **''Dreaming of Machu Picchu in Busan''**, seguito dal **progetto ''Miro Miro'' (labirinto) del 2010** — con l''aggiunta di oltre 22 murales commissionati, sculture e installazioni artistiche, tra cui l''iconica **panchina del ''Piccolo Principe e la Volpe''** al belvedere Sky Garden. \n\nGamcheon ha vinto il **premio UN-HABITAT Asian Townscape Award 2012** e accoglie oggi **~1,4 milioni di visitatori l''anno**. La visita segue il caratteristico percorso a piedi con la mappa dei timbri: dall''ingresso presso il **centro informazioni turistiche**, su fino al **belvedere Sky Garden** per lo scatto panoramico sui tetti arcobaleno, poi giù attraverso i vicoli labirintici tra murales, negozi di noleggio hanbok, botteghe artigiane e piccoli caffè. \n\n**Il villaggio è una comunità residenziale viva** — si richiede di parlare a bassa voce, niente droni, niente flash verso le abitazioni e i rifiuti si portano via con sé. \n\nOrari **09:00-18:00 mar-ott / 09:00-17:00 nov-feb (centro informazioni)**; **il villaggio in sé è aperto 24 ore su 24, ingresso GRATUITO**.","visitBasics":{"hours":"Tutti i giorni 09:00–18:00 (mar–ott) / 09:00–17:00 (nov–feb); alcuni negozi/caffè seguono orari propri","closed":"Aperto tutto l''anno (una comunità residenziale viva)","walking":"Impegnativo — vicoli e scalinate molto ripidi; in molti tratti non adatto a passeggini o sedie a rotelle","admission":"Ingresso al villaggio gratuito; mappa dei timbri opzionale ≈ 2,000 KRW"},"image":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","images":["/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp"],"imageCredits":[{"url":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 1","alt":"Gamcheon Culture Village — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 2","alt":"Gamcheon Culture Village — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 3","alt":"Gamcheon Culture Village — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 8","alt":"Gamcheon Culture Village — gallery image 8"}]},{"number":8,"time":"≈ 16:30","duration":"30 min","name":"Villaggio dei murales Dakbatgol e monorotaia della scalinata dei desideri","category":"Villaggio dei murales / Monorotaia gratuita","description":"**Dakbatgol (닥밭골)** è un villaggio collinare nel distretto di Seo-gu, a Busan, il cui nome ricorda i **campi di gelso da carta (dak)** che un tempo rifornivano i maestri della carta tradizionale coreana hanji. Come Gamcheon si arrampica su un ripido pendio in vicoli stretti — ma non è mai diventato una fermata dei pullman turistici, così i suoi **vicoli di murales, le opere ispirate alla hanji e i punti panoramici restano quieti e locali**, panni stesi compresi. Il simbolo del villaggio è la **''scalinata dei desideri'' (소망계단)** — una lunga e ripida via di gradini dipinta di murales — e la **monorotaia inclinata gratuita** che le scorre accanto, installata perché gli anziani del villaggio potessero raggiungere le proprie case; anche i visitatori possono salirvi, trasformando la salita più ripida del pomeriggio in un belvedere al rallentatore. È il contrappunto volutamente a misura d''uomo alla fama di Gamcheon, a dieci minuti dalla zona dei rientri.","image":null,"highlights":["**Villaggio dei murales silenzioso** — l''omologo locale di Gamcheon, quasi senza folla","Prende il nome dai **campi di gelso da carta (dak)** dell''eredità hanji di Busan","**''Scalinata dei desideri'' (소망계단)** — una ripida via di gradini coperta di murales","**Monorotaia inclinata gratuita** accanto alla scalinata — costruita per gli anziani del villaggio, aperta ai visitatori","Belvedere collinari sul vecchio quartiere del porto","Ingresso GRATUITO; un quartiere autenticamente abitato — parlate a bassa voce"],"timeUsed":["Discesa dal minibus + passeggiata tra i vicoli dei murales (~10 min)","Salita in monorotaia della scalinata dei desideri + belvedere (~10 min)","Discesa + tempo per le foto (~5 min)","Ritrovo al minibus (~5 min)"],"whyOnRoute":"**La chiusura silenziosa che i pullman saltano.** Dopo la folla di Gamcheon, Dakbatgol mostra la stessa Busan collinare a volume di vita quotidiana — murales, la scalinata dei desideri e una monorotaia che fa la salita. Chiude il capitolo dei villaggi a dieci minuti dalla zona di rientro di Nampo, così la giornata termina immersa nella trama locale anziché nel traffico.","_poi_meta":{"match":"authored","poi_key":"dakbatgol_mural_village","sources":["Visit Busan","Busan Seo-gu Office"],"verified":false,"verified_date":"2026-08-04"},"smartNotes":{"tip":"È un villaggio abitato, non un parco a tema — parlate a bassa voce nei vicoli e non fotografate verso le porte aperte delle case","photo":"Fotografate la scalinata dei desideri dal basso con il binario della monorotaia che le corre accanto; il belvedere in cima inquadra il quartiere del porto","facilities":"Piccoli caffè vicino all''ingresso; più scelta a Nampo-dong dopo il rientro"},"convenience":{"parking":"Fermata del minibus all''ingresso del villaggio","restroom":"Servizi pubblici nei pressi dell''ingresso del villaggio"},"visitBasics":{"hours":"Villaggio ad accesso libero; la monorotaia funziona in orario diurno (≈ 09:00–18:00, in base al meteo)","closed":"La monorotaia può fermarsi per manutenzione o maltempo — la scalinata resta aperta","walking":"Vicoli ripidi e scalinate; la monorotaia copre il tratto più ripido","admission":"GRATUITO (villaggio e monorotaia)"},"images":[],"imageCredits":[],"galleryItems":[]},{"number":9,"time":"≈ 17:10","duration":"≈ 70 min in totale","name":"Rientro (4 punti nel centro di Busan)","category":"Rientro — Stazioni centrali in sequenza","description":"**Le discese procedono in sequenza da ovest verso est**: **Nampo-dong / zona Jagalchi (~17:10)** — scendete qui per le migliori vie del cibo serale di Busan e la scena notturna di BIFF Square; **stazione di Busan (~17:30)** per le coincidenze KTX; **Seomyeon (~17:50)** per gli hotel del centro; e infine **Haeundae (~18:20)**. Concordate il vostro punto di discesa con la guida nel pomeriggio: proseguire fino a Haeundae è il tragitto più lungo, ma vi lascia in riva alla spiaggia per la serata.","image":null,"highlights":[],"timeUsed":["Nampo-dong / zona Jagalchi (~17:10)","Stazione di Busan (~17:30)","Seomyeon (~17:50)","Haeundae (~18:20)"],"whyOnRoute":"Dakbatgol dista dieci minuti da Nampo-dong, così la sequenza delle discese comincia quasi subito dopo l''ultima tappa, senza trasferimenti a vuoto. L''ordine ovest-est copre chi viaggia in KTX (stazione di Busan), gli hotel del centro (Seomyeon) e quelli sulla spiaggia (Haeundae) senza tornare indietro.","_poi_meta":null,"images":[],"imageCredits":[],"galleryItems":[]}]'::jsonb, true), '{"routeFlowStops"}', '[{"name":"Prelievo (il vostro hotel nel centro di Busan)","type":"origin","theme":"Departure"},{"name":"Tempio Haedong Yonggungsa","type":"primary","theme":"Seaside temple"},{"name":"Osservatorio Daritdol di Cheongsapo (passerella di vetro)","type":"secondary","theme":"Glass Skywalk"},{"name":"Sky Capsule dello Haeundae Blueline Park (Cheongsapo → Mipo)","type":"primary","theme":"Sky Capsule"},{"name":"Pranzo (ristorante locale di Busan)","type":"meal","theme":"Meal"},{"name":"Spiaggia di Haeundae","type":"secondary","theme":"Beach"},{"name":"Villaggio culturale di Gamcheon","type":"primary","theme":"Art village"},{"name":"Villaggio dei murales Dakbatgol e monorotaia della scalinata dei desideri","type":"secondary","theme":"Mural Village"},{"name":"Rientro (4 punti nel centro di Busan)","type":"return","theme":"Return"}]'::jsonb, true), '{"routePhases"}', '[{"phase":"Mattina sulla costa","duration":"≈ 3,5 ore","description":"Prelievo porta a porta negli hotel del centro di Busan (09:00–10:00), poi il tempio Haedong Yonggungsa prima dell''ondata dei bus turistici e quindi la passerella di vetro Daritdol a Cheongsapo."},{"phase":"Sky Capsule, pranzo e spiaggia","duration":"≈ 2 ore","description":"Lo Sky Capsule pastello da Cheongsapo a Mipo (biglietto opzionale — chi non sale prende il pullman o percorre la passerella Green Railway), pranzo vicino a Haeundae e poi venti minuti sulla spiaggia di Haeundae stessa."},{"phase":"Due villaggi in collina","duration":"≈ 2 ore","description":"Il giro fotografico del villaggio culturale di Gamcheon (60 min), poi il tranquillo villaggio dei murales di Dakbatgol con la monorotaia gratuita della \"scala dei desideri\" (30 min)."},{"phase":"Chiusura in centro","duration":"≈ 1 ora","description":"Discese in sequenza: Nampo-dong, stazione di Busan, Seomyeon, poi Haeundae."}]'::jsonb, true), '{"routeShapeIntro"}', '{"title":"Come si muove questa giornata a Busan","subtitle":"Prima la costa orientale: il tempio sul mare nella sua quieta finestra mattutina, poi il nucleo di Cheongsapo — passerella di vetro, fari gemelli — dove la corsa in Sky Capsule diventa essa stessa il trasferimento lungo la costa fino a Mipo. Dopo pranzo e una breve sosta sulla spiaggia di Haeundae la giornata attraversa la città verso le colline occidentali per due villaggi dagli umori opposti: i colori celebri in tutto il mondo di Gamcheon, poi i murales silenziosi di Dakbatgol, dove una monorotaia gratuita risale la ''scalinata dei desideri''. I rientri nelle stazioni centrali chiudono l''anello, dalle 09:00 alle 18:20 circa."}'::jsonb, true), '{"whyTourWorks"}', '{"bestFor":["Chi visita Busan per la prima volta","Coppie e viaggiatori appassionati di fotografia","Famiglie con adulti e gruppi di amici","Chi vuole la costa E i villaggi in un solo giorno"],"lessIdealFor":["Chi preferisce camminare poco o evitare le salite","Gruppi con passeggini (vicoli e scalinate dei villaggi)","Chi cerca panorami notturni — è un itinerario diurno"],"routeLogicSections":[{"title":"Pacing & geography","icon":"route","iconBg":"bg-sky-50/80","iconColor":"text-sky-600","items":[{"label":"Il tempio nella sua ora più quieta","detail":"Haedong Yonggungsa è il tempio più fotografato di Busan e l''ondata dei bus turistici comincia verso le 11:00. Arrivare intorno alle 10:20 mantiene percorribili la discesa dei 108 gradini e il punto panoramico di Haesu Gwaneum, senza code."},{"label":"La corsa in capsula È il trasferimento","detail":"Da Cheongsapo la Sky Capsule pastello scivola per 2,3 km lungo la costa fino a Mipo — la corsa sostituisce quindi un tratto in minibus invece di aggiungere una deviazione. Chi rinuncia al biglietto raggiunge Mipo in minibus oppure percorre gratuitamente la passeggiata in legno della Green Railway lungo la stessa costa."},{"label":"Due villaggi collinari, due atmosfere","detail":"Gamcheon è l''anfiteatro pastello di Busan, celebre in tutto il mondo; Dakbatgol, a dieci minuti, è il suo quieto omologo locale — vicoli di murales quasi senza folla, dove una monorotaia inclinata gratuita, costruita per gli anziani del villaggio, vi porta su per la ''scalinata dei desideri''."},{"label":"Tappe principali gratuite, un solo biglietto opzionale","detail":"Yonggungsa, la passerella Daritdol, Gamcheon e Dakbatgol (monorotaia inclusa) sono tutti gratuiti. L''unica attrazione a pagamento della giornata è la Sky Capsule — e la scelta è vostra al momento della prenotazione: biglietto incluso, oppure escluso se preferite la passeggiata sulla passerella in legno."}]}]}'::jsonb, true), '{"practicalAccordionItems"}', '[{"id":"pickup","title":"Prelievo e rientro","preview":"Il prelievo è porta a porta presso il vostro hotel nel centro di Busan — Seomyeon, Nampo-dong / stazione di Busan, Haeundae / Marine City — tra le 09:00 e le 10:00. L''orario esatto viene confermato via WhatsApp la sera prima.","content":["Il prelievo è porta a porta presso il vostro hotel nel centro di Busan — Seomyeon, Nampo-dong / stazione di Busan, Haeundae / Marine City — tra le 09:00 e le 10:00. L''orario esatto viene confermato via WhatsApp la sera prima.","Discese in sequenza: Nampo-dong/Jagalchi ≈17:10, stazione di Busan ≈17:30, Seomyeon ≈17:50, Haeundae ≈18:20.","La durata effettiva del tour dipende dall''orario di prelievo e dal punto di discesa: circa 7 ore e 15 minuti nel caso più breve (prelievo alle 10:00, discesa a Nampo-dong) e circa 9 ore e 15 minuti nel più lungo (prelievo alle 09:00, discesa a Haeundae)."]},{"id":"what-to-bring","title":"Cosa indossare e portare","preview":"Scarpe comode con buona presa — i vicoli collinari di Gamcheon e i 108 gradini di Yonggungsa…","content":["Scarpe comode con buona presa — i vicoli collinari di Gamcheon e i 108 gradini di Yonggungsa richiedono entrambi aderenza.","Uno strato leggero per il veicolo climatizzato e la brezza marina a Yonggungsa.","Macchina fotografica o smartphone (Gamcheon e Cheongsapo sono i momenti fotografici clou).","Contanti o carta per il pranzo (₩10,000–₩20,000), i biglietti opzionali di Sky Capsule / Beach Train a Cheongsapo e l''osservatorio opzionale della Busan Tower."]},{"id":"weather-policy","title":"Politica meteo","preview":"Operativo tutto l''anno.","content":["Operativo tutto l''anno.","Pioggia leggera: il tour si svolge come da programma — Yonggungsa sotto la pioggia ha un fascino tutto suo, e i vicoli di Gamcheon restano percorribili.","Pioggia forte o temporali: la guida può modificare l''itinerario, perché la parte bassa del tempio di Yonggungsa può diventare scivolosa e le scalinate di Gamcheon insidiose.","Meteo di livello tifone: viene offerto il rimborso completo o la riprenotazione."]},{"id":"inclusions","title":"What''s included","preview":"Minibus per piccolo gruppo (max ≈12 ospiti), guida certificata di lingua inglese, carburante/pedaggi/parcheggi.","content":["Minibus per piccolo gruppo (max ≈12 ospiti), guida certificata di lingua inglese, carburante/pedaggi/parcheggi.","Tutte le attrazioni principali sono a ingresso GRATUITO: Haedong Yonggungsa, osservatorio Daritdol di Cheongsapo, villaggio culturale di Gamcheon, villaggio dei murales Dakbatgol (monorotaia della scalinata dei desideri gratuita).","Biglietto Sky Capsule: a scelta alla prenotazione — incluso (riserviamo in anticipo le capsule per il vostro gruppo; base di 2 persone per capsula) oppure escluso (passeggiata gratuita sulla passerella in legno della Green Railway o trasferimento in minibus fino a Mipo).","Non incluso: pranzo (≈ ₩10,000–15,000), bevande, spese personali, mance."]},{"id":"language","title":"Lingua","preview":"Lingua principale del tour: inglese.","content":["Lingua principale del tour: inglese.","Guida di lingua cinese disponibile su richiesta — prenotare con almeno 3 giorni di anticipo.","Il coreano è presente per tutta la giornata su menu, cartelli e nelle interazioni con le bancarelle; la guida si occupa della traduzione."]},{"id":"walking","title":"Walking & terrain","preview":"Difficoltà moderata con brevi tratti impegnativi.","content":["Difficoltà moderata con brevi tratti impegnativi.","Yonggungsa ha 108 gradini di pietra in discesa e risalita.","La passerella Daritdol è pianeggiante (pavimento di vetro, copriscarpe forniti).","Le stazioni della Sky Capsule sono in piano con qualche gradino sulle banchine.","Gamcheon è fatta di vicoli collinari e scalinate — indossate scarpe comode.","La scalinata dei desideri di Dakbatgol è ripida, ma la monorotaia gratuita fa la salita.","Camminata totale di circa 4–5 km."]},{"id":"capsule","title":"Sky Capsule (opzione biglietto)","preview":"Incluso o escluso — a vostra scelta alla prenotazione.","content":["La Sky Capsule percorre 2,3 km su una rotaia sopraelevata tra Cheongsapo e Mipo (~30 min), in cabine pastello da 4 posti sospese sopra la costa.","Opzione con biglietto incluso: riserviamo in anticipo le capsule per il vostro gruppo (prezzo per capsula ≈ ₩30,000 per 2 / ₩39,000 per 3 / ₩44,000 per 4 sola andata; l''opzione inclusa è calcolata sulla base di 2 persone per capsula).","Opzione con biglietto escluso: passeggiata gratuita sulla passerella in legno della Green Railway (2,3 km, ~30 min, stessa costa) oppure trasferimento in minibus fino a Mipo.","Il servizio dipende dal meteo (il forte vento sospende la linea); se la capsula non può circolare, la passeggiata sulla passerella e il trasferimento in minibus mantengono l''itinerario in orario."]},{"id":"cancellation","title":"Cancellazione","preview":"Cancellazione gratuita fino a 24 ore prima del pickup.","content":["Cancellazione gratuita fino a 24 ore prima del pickup.","Le cancellazioni il giorno stesso e i mancati arrivi non sono rimborsabili."]}]'::jsonb, true), '{"bookingSupportSteps"}', '[{"timing":"Immediatamente","title":"Conferma immediata","detail":"Conferma della prenotazione con riepilogo dell''itinerario","description":"Conferma immediata della prenotazione, con la vostra finestra di prelievo in hotel (09:00–10:00) e cosa aspettarsi."},{"timing":"Il giorno prima","title":"Dettagli del pickup","detail":"Luogo esatto del pickup e informazioni sul veicolo via WhatsApp","description":"Verifica del meteo ed eventuali note sull''itinerario (consiglio sul trenino Danubi per Taejongdae, orari delle maree a Yonggungsa) inviate il giorno prima."},{"timing":"La mattina stessa","title":"Conferma del pickup","detail":"L''autista si annuncia 10 minuti prima dell''arrivo","description":"Targa del van e contatto della guida confermati la sera precedente."},{"timing":"Durante il tour","title":"Assistenza durante il tour","detail":"Linea diretta con l''operativo","description":"Un messaggio la sera prima conferma l''orario esatto di prelievo in hotel; uno al mattino copre il traffico in tempo reale."},{"timing":"Fine giornata","title":"Rientro flessibile","detail":"Scegliete il rientro a Nampo-dong, alla stazione di Busan, a Seomyeon o a Haeundae","description":"La guida offre narrazione dal vivo a ogni tappa — la fondazione di Yonggungsa nel 1376, la storia delle 22 nazioni dell''UNMCK, l''origine di Gamcheon come insediamento di rifugiati del 1955."},{"timing":"Dopo il tour","title":"Recensione e follow-up","detail":"Recensione facoltativa e follow-up","description":"Invio di una richiesta di feedback post-tour; le domande sui ristoranti consigliati a Busan ricevono risposta in giornata."}]'::jsonb, true), '{"staticQuestions"}', '[{"question":"Il biglietto della Sky Capsule è incluso?","answer":"A vostra scelta al momento della prenotazione. Con l''opzione con biglietto incluso riserviamo in anticipo le capsule per il vostro gruppo (prezzo per capsula: circa ₩30,000 per 2 / ₩39,000 per 3 / ₩44,000 per 4, sola andata — l''opzione inclusa è calcolata sulla base di 2 persone per capsula). Con l''opzione base potete invece percorrere gratuitamente la passeggiata in legno della Green Railway o raggiungere Mipo in minibus mentre gli altri salgono in capsula."},{"question":"Devo prenotare la Sky Capsule in anticipo?","answer":"Le fasce del tramonto e del fine settimana si esauriscono con 1–2 settimane di anticipo. Se scegliete l''opzione con biglietto incluso, gestiamo noi la prenotazione per il vostro gruppo alla conferma della prenotazione. Nei giorni feriali tranquilli è possibile acquistare i biglietti in giornata al chiosco, ma senza garanzia."},{"question":"Il pranzo è incluso?","answer":"No — il pranzo è a parte (circa ₩10,000–15,000). La guida consiglia opzioni locali nei pressi di Haeundae/Mipo come il dwaeji-gukbap (la zuppa di riso al maiale simbolo di Busan), i milmyeon (noodle freddi di grano) o un ristorante di pesce."},{"question":"Quanto si cammina e quanto è ripido il percorso?","answer":"Difficoltà da moderata a impegnativa in brevi tratti: 108 gradini in discesa e risalita a Yonggungsa, passerella di vetro pianeggiante al Daritdol, percorsi per lo più piani alle stazioni della capsula, vicoli in pendenza a Gamcheon e scalinate a Dakbatgol — dove però la monorotaia gratuita fa la salita al posto vostro. La distanza totale a piedi è di circa 4–5 km."},{"question":"È adatto a bambini o anziani?","answer":"Sì, per la maggior parte dei viaggiatori attivi. I bambini adorano il pavimento di vetro e la capsula; la monorotaia di Dakbatgol evita la salita più ripida. I gradini di Yonggungsa e le pendenze di Gamcheon sono i due tratti impegnativi — affrontateli con calma e saltate i vicoli laterali se necessario."},{"question":"In cosa si differenzia dal tour giornaliero Busan Top Attractions?","answer":"Stesso operatore, focus diverso. Top Attractions copre il classico giro della città (cimitero commemorativo delle Nazioni Unite, mercato di Jagalchi). Questo itinerario in piccolo gruppo punta tutto sulla costa e sui villaggi: una sosta dedicata alla passerella Daritdol, la corsa in Sky Capsule con opzione di biglietto incluso e il tranquillo villaggio dei murales Dakbatgol che i grandi pullman saltano."},{"question":"Dove si effettuano pickup e rientro?","answer":"Il prelievo è porta a porta presso il vostro hotel nel centro di Busan, tra le 09:00 e le 10:00 — l''orario esatto viene confermato via WhatsApp la sera prima. Le discese seguono questo ordine: Nampo-dong ≈17:10, stazione di Busan ≈17:30, Seomyeon ≈17:50, Haeundae ≈18:20."},{"question":"Cosa succede se piove?","answer":"Il tour si svolge con qualsiasi tempo. La capsula e la monorotaia funzionano con pioggia normale (si fermano solo in caso di forte vento), la passerella fornisce copriscarpe e i vicoli dei villaggi restano percorribili con l''ombrello. In caso di maltempo intenso il tempo all''aperto sulle terrazze del tempio può essere ridotto."}]'::jsonb, true), '{"pickup_dropoff"}', '{"departure":[{"order":1,"time":"09:00–10:00","name":"Il vostro hotel nel centro di Busan (porta a porta)","type":"hotel","note":"Prelievo porta a porta negli hotel del centro di Busan — Seomyeon, Nampo-dong / stazione di Busan, Haeundae / Marine City. L''orario esatto viene confermato la sera prima.","lat":35.15782,"lng":129.06003}],"return":[{"order":1,"name":"Nampo-dong / Jagalchi area","type":"station","lat":35.09663,"lng":129.0308},{"order":2,"name":"Busan Station (Exit 4)","type":"station","lat":35.11449,"lng":129.03933},{"order":3,"name":"Seomyeon Station (Exit 4)","type":"station","lat":35.15782,"lng":129.06003},{"order":4,"name":"Haeundae Station (Exit 5)","type":"station","lat":35.16396,"lng":129.15853}],"notes":["Il prelievo è porta a porta presso il vostro hotel nel centro di Busan tra le 09:00 e le 10:00; l''orario esatto viene confermato la sera prima. Le discese avvengono in quattro punti centrali in sequenza (Nampo-dong → stazione di Busan → Seomyeon → Haeundae, ≈ 17:10–18:20): comunicate alla guida nel pomeriggio quale preferite."]}'::jsonb, true), '{"matching_profile"}', '{"profile_version":1,"is_active":true,"product_id":"busan-small-group-yonggungsa-skycapsule-gamcheon-tour","product_type":"small_group","route_type":"fixed_route","destination_region":"busan_city","region_type":"busan_city","vehicle_type":"coach","duration_hours":9,"region_tags":["busan_haeundae","busan_gijang","busan_namgu","busan_saha","busan_jung"],"theme_tags":["temple","coastal","war_memorial","mural_village","fish_market","korean_war_history"],"poi_tags":["haedong_yonggungsa","cheongsapo_daritdol_observatory","cheongsapo_blue_line_park","gamcheon_culture_village","dakbatgol_mural_village"],"pace_level":0.7,"walking_level":0.85,"scenic_level":0.9,"photo_level":1,"culture_level":0.95,"relax_level":0.5,"first_time_fit":1,"family_fit":0.85,"senior_fit":0.7,"couple_fit":0.95,"solo_traveler_fit":0.9,"active_traveler_fit":0.8,"adult_family_fit":1,"family_with_teens_fit":0.95,"young_kids_fit":0.55,"senior_active_fit":0.7,"senior_general_fit":0.55,"mobility_friendly_fit":0.4,"stroller_fit":0.4,"one_day_fit":1,"same_day_flight_fit":0.3,"rain_fit":0.5,"value_for_money_fit":0.95,"iconic_landmark_fit":1,"cafe_fit":0.7,"food_fit":0.8,"nature_fit":0.8,"beach_fit":0.6,"nightlife_fit":0.2,"shopping_fit":0.2,"no_shopping_fit":0.5,"local_culture_fit":1,"storytelling_fit":0.8,"unesco_fit":0,"intangible_heritage_fit":0.2,"indoor_ratio":0.2,"weather_sensitivity":0.5,"comfort_level":0.6,"budget_fit":0.85,"premium_fit":0.3,"small_group_fit":1,"private_fit":0.05,"bus_fit":1,"price_band":"mid","pickup_base":"busan_central","return_time_band":"17:00-18:30","duration_band":"9h","min_recommended_age":8,"hard_constraints":{"avoidIf":["mobility_limited"],"notIdealFor":["very_low_mobility","stroller_heavy_groups"]},"walking_notes":["Active walking day with several flights of stairs (Yonggungsa 108 steps, Gamcheon hillside).","Average fitness expected.","Sturdy closed-toe shoes recommended (Jagalchi 1F floor is wet)."],"keywords":["busan top attractions day tour","busan small group tour","haedong yonggungsa","gamcheon culture village","jagalchi market","un memorial cemetery busan"],"synonym_hints":["busan one day classic tour","busan must-see day trip","busan top 5 highlights"],"seasonality":"year_round","pickup_base_normalized":"busan","vehicle_type_legacy":"bus_coach","anchor_poi_keys":["haedong_yonggungsa","cheongsapo_daritdol_observatory","cheongsapo_blue_line_park","gamcheon_culture_village","dakbatgol_mural_village"],"private_tour_fit":0.05,"customizable_route_fit":0.1,"flexibility_fit":0.3,"fixed_itinerary_fit":1,"buddhist_temple_fit":1,"scenic_temple_fit":1,"coastal_temple_fit":1,"seaside_temple_fit":1,"war_memorial_fit":1,"korean_war_history_fit":1,"mural_village_fit":1,"fish_market_fit":1,"market_fit":1,"street_food_fit":0.9,"skywalk_fit":1,"sky_capsule_fit":0.7,"coastal_railway_fit":1,"history_culture_fit":1,"k_drama_filming_fit":0.5,"religious_history_fit":0.85,"premium_dining_fit":0.3,"seasonal_fit":0.85,"china_mainland_market_fit":0,"korea_domestic_market_fit":0,"taiwan_market_fit":1,"singapore_market_fit":1,"hong_kong_market_fit":1,"china_diaspora_overseas_market_fit":0.95,"se_asia_market_fit":0.95,"us_market_fit":0.85,"europe_market_fit":0.85,"australia_market_fit":0.85,"japan_market_fit":0.85,"busan_signature_route_fit":1,"skywalk_coastal_railway_fit":1,"first_time_busan_fit":1,"no_inter_city_travel_fit":1,"differentiates_from_busan_gyeongju_routes":true,"deep_history_traveler_fit_minimum":0.7,"english_speaking_guide_provided":true,"chinese_speaking_guide_available_on_advance_notice":true,"japanese_speaking_guide_available_on_advance_notice":true}'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'busan-small-group-yonggungsa-skycapsule-gamcheon-tour' AND locale = 'it';

