UPDATE public.tour_product_pages SET
  duration_label = '≈ 9 часов',
  stops_count = 9,
  detail_payload = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(detail_payload, '{"seo"}', '{"pageTitle":"Тур по Пусану в мини-группе: Ёнгунса, Sky Capsule, Камчхон | AtoC Korea","metaDescription":"9-часовой тур по Пусану в мини-группе: храм Хэдон Ёнгунса, стеклянный скайвок Таритдоль в Чхонсапхо, Sky Capsule парка «Блюлайн» (билет по выбору), культурная деревня Камчхон, деревня фресок Такпатколь и монорельс.","title":"Пусан: морской храм, Sky Capsule и культурные деревни — тур в мини-группе | AtoC","description":"Тур по Пусану в мини-группе: Хэдон Ёнгунса → смотровая площадка Таритдоль в Чхонсапхо → Sky Capsule парка «Блюлайн» (билет включён/не включён — на ваш выбор) → обед → культурная деревня Камчхон → деревня фресок Такпатколь и монорельс у «лестницы желаний».","primaryKeywords":["Пусан тур мини-группа","храм Хэдон Ёнгунса тур","Blueline Park Sky Capsule","культурная деревня Камчхон тур","смотровая площадка Таритдоль Чхонсапхо"],"ogImage":"https://www.atockorea.com/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp"}'::jsonb, true), '{"catalog_card"}', '{"slug":"busan-small-group-yonggungsa-skycapsule-gamcheon-tour","title":"Пусан в мини-группе: морской храм, Sky Capsule и культурные деревни","subtitle":"Однодневный тур по прибрежным символам и холмистым деревням Пусана в мини-группе — приморский храм Хэдон Ёнгунса, стеклянный скайвок на смотровой площадке Таритдоль в Чхонсапхо, поездка на Sky Capsule в парке «Блюлайн» в Хэундэ (билет — по выбору при бронировании), культурная деревня Камчхон и тихая деревня фресок Такпатколь с монорельсом вдоль «лестницы желаний».","region":"Пусан","duration":"≈ 9 часов","stopsCount":9,"rating":0,"reviewCount":0,"badges":["Мини-группа","Пусан","Sky Capsule","Побережье","Культурные деревни"],"tags":["Мини-группа","Пусан","Sky Capsule","Побережье","Культурные деревни","Подходит для первого визита"],"heroImage":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","thumbnail":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","priceLabel":"","shortCardDescription":"День в Пусане в мини-группе, построенный вокруг побережья и деревень на холмах: приморский храм Хэдон Ёнгунса в его тихое утреннее окно, бесплатная смотровая площадка Таритдоль со стеклянным полом в Чхонсапхо, поездка на Sky Capsule по парку «Блюлайн» от Чхонсапхо до Мипхо (билет включён или не включён — выбираете при бронировании), обед, культурная деревня Камчхон и малоизвестная деревня фресок Такпатколь, где бесплатный монорельс скользит вверх вдоль «лестницы желаний». Все ключевые точки, кроме опциональной капсулы, — с бесплатным входом."}'::jsonb, true), '{"hero"}', '{"imageUrl":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","imagePosition":"center 40%","images":["/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp"],"tagline":"Приморский храм Пусана в его тихий час, стеклянный скайвок над морем, поездка в пастельной капсуле вдоль побережья и две деревни на холмах — одна знаменитая, другая всё ещё по-настоящему местная","pills":["Мини-группа","Пусан","Подходит для первого визита"],"meta":{"duration":"≈ 9 часов (посадка у отеля в 09:00, последняя высадка в центре ≈ 17:50)","region":"Пусан","stops":"9 остановок","rating":0,"ratingStars":0}}'::jsonb, true), '{"itineraryStops"}', '[{"number":1,"time":"≈ 09:00–10:00","duration":"60 мин","name":"Посадка (ваш отель в центре Пусана)","category":"Трансфер / Посадка у отеля","description":"Посадка от двери до двери у вашего отеля в центре Пусана, между **09:00 и 10:00**. Точное время подтверждается в WhatsApp накануне вечером, когда у водителя есть список отелей на день и он может выстроить маршрут эффективно: гостей со стороны Хэундэ обычно забирают последними, потому что дальше автобус уходит из города на северо-восток, в Кичжан-гун, к первой остановке.\n\nЗона обслуживания охватывает основные гостиничные кластеры центра: **Сомён**, **Нампхо-дон / вокзал Пусана** и **Хэундэ / Marine City**. Если ваш отель за её пределами, гид назовёт ближайшее место встречи при подтверждении бронирования.\n\nПожалуйста, ждите в лобби за 5 минут до подтверждённого времени. Дорога от последней посадки до Хэдон Ёнгунса занимает около 30–40 минут в зависимости от трафика.","image":null,"highlights":["Посадка от двери до двери у отелей в центре Пусана, 09:00–10:00","Точное время подтверждается в WhatsApp накануне вечером","Автобус малой группы (макс. ~14 чел.)","Печатная программа на корейском и английском при посадке"],"timeUsed":["Посадка у отелей в центре Пусана (~40 мин)","Дорога на северо-восток в Кичжан-гун (~20 мин)"],"whyOnRoute":"Посадка у отеля полностью снимает утренний трансфер — не нужно раннее метро и не нужно искать нужный выход. Маршрут идёт с запада на восток, поэтому автобус заканчивает посадку рядом с Хэундэ и покидает город уже развёрнутым в сторону Кичжана и первой остановки дня.","_poi_meta":{"match":"transit_only","poi_key":"OPS_busan_hotel_pickup_central","sources":["AtoC Korea operations"],"verified":true,"verified_date":"2026-08-05"},"images":[],"imageCredits":[],"galleryItems":[],"_role":"pickup"},{"name":"Храм Хэдон Ёнгунса","time":"≈ 10:20","number":2,"category":"Буддийский храм / Побережье","duration":"60 мин","timeUsed":["Высадка из микроавтобуса + проход по торговой аллее к входной площади (~10 мин)","Двенадцать генералов зодиака + «пагода от аварий» (~10 мин)","Спуск по 108 ступеням + главный зал Тэунчжон + приморские террасы (~25 мин)","Смотровая у статуи Хэсу Кваным + время на фото (~10 мин)","Подъём обратно + сбор у микроавтобуса (~5 мин)"],"_poi_meta":{"match":"exact","poi_key":"haedong_yonggungsa","sources":["Visit Busan","VisitKorea","Wikipedia","Culture Trip","Korean Temple Guide","Korea Tourism Organization Official"],"verified":true,"kb_version":"1.24","verified_date":"2026-04-29"},"highlights":["**Основан в 1376 году** буддийским мастером Наон Хегыном (изначально «Помунса»)","Один из очень немногих крупных корейских храмов на берегу моря (большинство — в горах)","Переименован в **Хэдон Ёнгунса в 1974 году** после видения монаха Чонама — богиня на драконе","**108 каменных ступеней** = 108 заблуждений ума в буддизме","**12 Сибичжи-син (генералов зодиака)** у входа; **«пагода от аварий»** с монетами","**Хэсу Кваным Тэбуль** (морская богиня милосердия) — самый фотографируемый вид с утёса","Главный зал Тэунчжон восстановлен в 1970 году с вниманием к оригинальным цветам","Ежедневно 04:30-19:20, вход БЕСПЛАТНЫЙ; на день рождения Будды (май) — фестиваль фонарей","**Ряд каменных 12 Сибичжи-син — генералов зодиака — у ворот храма** — уникален среди прибрежных храмов Кореи"],"smartNotes":{"tip":"В залы входят через боковые двери (передняя предназначена для монахов); на день рождения Будды (апрель–май) храм украшают фонарями; приезжайте до 10:30, чтобы избежать самого плотного потока туристических автобусов","photo":"Скала восхода на морском краю; лестница у зала Тэунчжон даёт классический кадр «океан и храм»; статуя Хэсу Кваным с верхнего утёса — широкий план храма и Восточного моря","facilities":"Сувенирные и снековые лавки и небольшое кафе на верхней площади; прибрежная тропа ведёт дальше вдоль скал"},"whyOnRoute":"**Знаковое начало маршрута — самый фотографируемый храм Пусана в его тихое окно.** Прибытие к 10:20 опережает основной наплыв туристических автобусов (обычно с 11:00), поэтому спуск по 108 ступеням и смотровая точка со статуей Хэсу Кваным ещё проходимы без очередей. К тому же расположение храма на скалах уезда Кичжан (Gijang-gun) начинает день в самой северо-восточной точке маршрута — всё дальнейшее течёт в одну сторону вдоль побережья: следом Чхонсапхо, затем капсула в сторону города — без возвратов.","convenience":{"parking":"Парковка Хэдон Ёнгунса (платная, по данным Visit Busan)","restroom":"Есть у главного входа и на территории комплекса"},"description":"**Хэдон Ёнгунса (해동 용궁사) — самый знаменитый приморский буддийский храм Кореи** — стоит на скалистых утёсах уезда Кичжан (Gijang-gun) на северо-восточном побережье Пусана, один из очень немногих крупных корейских храмов, НЕ расположенных в горах. Основан в **1376 году, в эпоху династии Корё, великим буддийским наставником Наон Хегыном (나옹 혜근, 1320-1376)** — королевским советником и мастером, который во многом сформировал корейский буддизм на пороге эпохи Чосон. \n\nПо легенде, Наон предавался аскезе в храме Пунхванса в Кёнджу во время общенациональной засухи; бог Восточного моря явился ему во сне и сказал, что храм на горе Поннэ (изначальное название этого приморского утёса) вернёт королевству процветание. \n\nНаон основал храм и назвал его **Помунса**, посвятив его Квансеым-посаль (관세음보살, бодхисаттве сострадания). Храм был разрушен во время **японского вторжения Имчжин 1592 года** и лежал в руинах более 300 лет, пока **монах Унган из храма Тхондоса не начал восстановление в начале 1930-х годов**. \n\nНынешнее название, **Хэдон Ёнгунса («храм Драконьего дворца»)**, появилось только в **1974 году** — когда настоятелю Чонаму во время 100-дневной молитвы (чонгон кидо) явилось видение богини милосердия, спускающейся на спине дракона в сиянии многоцветного света. \n\nХрам переименовали в честь этого видения. Визит следует фирменному процессионному пути храма: через ряд **12 Сибичжи-син (двенадцати генералов зодиака)** на входной площади, мимо **7-ярусной «пагоды от аварий»** (где водители оставляют монеты под каменным святилищем-колесом), вниз по знаменитым **108 каменным ступеням** (символизирующим 108 заблуждений буддийского ума) через небольшую бамбуковую рощу — и на приморские террасы к главному залу Тэунчжон. \n\n**Хэсу Кваным Тэбуль** (статуя морской богини милосердия) на верхнем утёсе — самый фотографируемый вид, в одном кадре крыши храма и Восточное море. \n\nЧасы работы: **04:30-19:20 ежедневно, последний вход 18:50, вход БЕСПЛАТНЫЙ**. На **день рождения Будды (май)** храм украшают фонари фестиваля Ёндынхве.","visitBasics":{"hours":"Ежедневно 04:30–19:20 (последний вход 18:50)","closed":"Открыт круглый год","walking":"Умеренная нагрузка — 108 ступеней через сосновую рощу, несколько приморских террас и лестниц","admission":"Бесплатно; парковка для личных автомобилей платная"},"image":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","images":["/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp"],"imageCredits":[{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","source":"atoc-korea"},{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 1","alt":"Haedong Yonggungsa Temple — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-haesu-gwaneum.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 2","alt":"Haedong Yonggungsa Temple — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-dragon-hall.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 3","alt":"Haedong Yonggungsa Temple — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-main-courtyard.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 4","alt":"Haedong Yonggungsa Temple — gallery image 4"},{"id":5,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-zodiac-statues.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 5","alt":"Haedong Yonggungsa Temple — gallery image 5"},{"id":6,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunrise-cliff.webp","location":"Haedong Yonggungsa Temple","caption":"Haedong Yonggungsa Temple — photo 6","alt":"Haedong Yonggungsa Temple — gallery image 6"}]},{"number":3,"time":"≈ 11:40","duration":"40 мин","name":"Смотровая площадка Таритдоль в Чхонсапхо (стеклянный скайвок)","category":"Прибрежная смотровая / бесплатно","description":"**Смотровая площадка Таритдоль в Чхонсапхо (청사포 다릿돌전망대)** — это **скайвок длиной 72,5 метра, изгибающийся над морем на высоте около 20 метров**, открытый в августе 2017 года на прибрежном утёсе между Чхонсапхо и Сончжоном. Название происходит от **таритдоль — пяти рифовых «камней-ступеней»**, что усеивают море под настилом и будто шагают к горизонту, как мост. Дальняя секция настила — со **стеклянным** полом; выдаются бахилы, чтобы беречь панели (и довериться им!), пока внизу под ногами перекатывается зыбь. Вход **бесплатный**. Вернувшись в деревню, в нескольких минутах прогулки вы найдёте **парные маяки Чхонсапхо** (один красный, один белый) и маленький переезд у станции, прославившийся кадром в стиле аниме «Слэм-данк».","image":null,"highlights":["**Скайвок 72,5 м, ~20 м над морем** — открыт в августе 2017 года, БЕСПЛАТНО","Назван в честь пяти рифов **таритдоль — «камней-ступеней»**, видимых под настилом","**Секция со стеклянным полом** на морском конце (бахилы выдаются)","**Парные маяки Чхонсапхо** (красный + белый) в нескольких минутах прогулки","Чхонсапхо — один из **восьми живописных видов** Пусана, действующая рыбацкая деревня","Знаменитый по аниме переезд у станции — фотоспот"],"timeUsed":["Высадка из микроавтобуса + пешком до входа на скайвок (~5 мин)","Выход на скайвок + секция со стеклянным полом (~20 мин)","Прогулка к парным маякам / переезду для фото (~10 мин)","Сбор у станции капсулы (~5 мин)"],"whyOnRoute":"**Бесплатный аттракцион между храмом и капсулой.** Таритдоль дарит дню его момент «над морем» — стеклянный пол, под которым перекатывается зыбь, — без билета, и стоит он прямо на утёсе Чхонсапхо, так что посадка на Sky Capsule всего в паре минут. Увидев берег сначала с неподвижного скайвока, вы через десять минут воспримете вид из движущейся капсулы совсем иначе.","_poi_meta":{"match":"authored","poi_key":"cheongsapo_daritdol_observatory","sources":["Visit Busan","Busan Metropolitan City Tourism","Blue Line Park official"],"verified":false,"verified_date":"2026-08-04"},"smartNotes":{"tip":"В ветреные дни настил иногда закрывают — гид проверяет условия и при необходимости меняет порядок остановок кластера Чхонсапхо","photo":"Снимайте вниз сквозь стекло на рифы таритдоль; изгиб настила с береговой тропы даёт лучший общий кадр","facilities":"Кафе и лавки с морепродуктами в деревне Чхонсапхо внизу"},"convenience":{"parking":"Остановка микроавтобуса в деревне Чхонсапхо; короткая прогулка до настила","restroom":"Общественные туалеты у станции Чхонсапхо"},"visitBasics":{"hours":"Открытый доступ; смотровая обслуживается примерно 09:00–18:00 (зависит от сезона/погоды)","closed":"Может временно закрываться при сильном ветре или шторме","walking":"Ровный выход по настилу; короткий подъём от деревни","admission":"БЕСПЛАТНО (бахилы выдаются для стеклянной секции)"},"images":[],"imageCredits":[],"galleryItems":[]},{"number":4,"time":"≈ 12:30","duration":"50 мин","name":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо)","category":"Прибрежный аттракцион / билет по выбору","description":"**Sky Capsule («Скай-капсула»)** — фирменный аттракцион **Haeundae Blueline Park (парка «Блюлайн» в Хэундэ)**, эко-редевелопмента 2020 года заброшенной прибрежной железной дороги Тонхэ-Намбу: **пастельные 4-местные кабинки скользят 2,3 км по эстакадному рельсу на высоте 7–10 метров над береговой линией** между Чхонсапхо и Мипхо, и всю дорогу море с одной стороны (~30 минут). Мы садимся в **Чхонсапхо и едем в сторону Мипхо**, где микроавтобус уже ждёт — так поездка одновременно служит трансфером дня вдоль побережья. **Билет на капсулу опционален и выбирается при бронировании**: при варианте с включённым билетом мы заранее резервируем капсулы для вашей группы (цена за капсулу: около ₩30,000 за 2 чел. / ₩39,000 за 3 / ₩44,000 за 4, в одну сторону); при базовом варианте вы можете пройтись по **бесплатной деревянной набережной Green Railway** — отмеченной наградами 2,3-километровой прибрежной дощатой тропе под тем же рельсом — или просто доехать до Мипхо на микроавтобусе.","image":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","highlights":["**Пастельные 4-местные капсулы на эстакадном прибрежном рельсе** — фирменный аттракцион парка «Блюлайн» (открыт в 2020 году)","**Чхонсапхо → Мипхо, 2,3 км / ~30 мин**, виды на море всю дорогу","**Билет включён или не включён — ваш выбор при бронировании** (цена за капсулу ≈ ₩30,000 за 2 чел. / ₩39,000 за 3 / ₩44,000 за 4, в одну сторону)","Кто не едет: **бесплатная деревянная набережная Green Railway** вдоль того же берега или микроавтобус до Мипхо","Поездка заканчивается там, где начинается обед — от Мипхо рукой подать до гастрономических улиц Хэундэ","Работает при обычном дожде; останавливается только при сильном ветре"],"timeUsed":["Посадка на станции Чхонсапхо (~15 мин)","Поездка на Sky Capsule Чхонсапхо → Мипхо (~35 мин)"],"whyOnRoute":"**Аттракцион, который одновременно трансфер.** Посадка в Чхонсапхо сразу после скайвока означает, что капсула везёт вас вдоль того самого берега, на который вы только что смотрели, — и высаживает в Мипхо, где уже ждут микроавтобус и обеденные улицы. День ради неё никуда не сворачивает: откажитесь от билета — и тот же отрезок покроют микроавтобус или бесплатная набережная.","_poi_meta":{"match":"partial","poi_key":"cheongsapo_blue_line_park","sources":["Blue Line Park official","Visit Busan","Busan Metropolitan City Tourism"],"verified":true,"kb_version":"1.24","verified_date":"2026-08-04"},"smartNotes":{"tip":"Слоты на закат и выходные распродаются за 1–2 недели — выберите вариант с включённым билетом при бронировании, и мы зарезервируем их для вас","photo":"Садитесь со стороны моря (правая сторона по ходу к Мипхо); поворот за тоннелем Тальмачжи — фирменный кадр","facilities":"Кафе и мини-маркет на площади Мипхо; билетные киоски на обеих станциях"},"convenience":{"parking":"Микроавтобус встречает группу на площади у станции Мипхо","restroom":"На обеих станциях — Чхонсапхо и Мипхо"},"visitBasics":{"hours":"≈ 09:30–18:30 (в высокий сезон — до вечера)","closed":"Зависит от погоды; при сильном ветре движение останавливают","walking":"Ровные платформы станций; альтернатива-набережная — 2,3 км (~30 мин) по деревянному настилу","admission":"За капсулу, в одну сторону: ≈ ₩30,000 (2 чел.) / ₩39,000 (3) / ₩44,000 (4) — вариант с включённым билетом доступен при бронировании"},"images":["/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","/images/tours/cheongsapo-blue-line/blueline-tram-cherry-sea.webp","/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-12-53-19.webp"],"imageCredits":[{"url":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","source":"atoc-korea"},{"url":"/images/tours/cheongsapo-blue-line/blueline-tram-cherry-sea.webp","source":"atoc-korea"},{"url":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","source":"atoc-korea"},{"url":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-12-53-19.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","location":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо)","caption":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — photo 1","alt":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/cheongsapo-blue-line/blueline-tram-cherry-sea.webp","location":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо)","caption":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — photo 2","alt":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","location":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо)","caption":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — photo 3","alt":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-12-53-19.webp","location":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо)","caption":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — photo 4","alt":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо) — gallery image 4"}]},{"name":"Обед (местный ресторан у Хэундэ/Мипхо)","time":"≈ 13:25","number":5,"category":"Местная кухня","duration":"45 мин","timeUsed":["Пешком от станции Мипхо до ресторана (~5 мин)","Обед (~35 мин)","Сбор у микроавтобуса (~5 мин)"],"_poi_meta":{"match":"lunch_placeholder","poi_key":"OPS_busan_lunch","sources":["Visit Busan","Busan Metropolitan Government cuisine guide"],"verified":true,"kb_version":"1.15","verified_date":"2026-04-29"},"highlights":[],"whyOnRoute":"**Естественная пауза между побережьем и деревнями.** Поездка в капсуле заканчивается в Мипхо как раз к обеду, а гастрономические улицы Хэундэ — в нескольких минутах ходьбы от станции: не нужно никуда ехать, чтобы хорошо поесть. Подкрепившись здесь, вы будете готовы к двум деревням на холмах, где ходьба самая «вертикальная» за день.","description":"Примерно 45 минут на обед у Мипхо/Хэундэ сразу после прибытия Sky Capsule. Типичные рекомендации гида: **твэджи-кукпаб (돼지국밥)** — фирменный пусанский суп на свином бульоне с рисом, родившийся в эпоху беженцев Корейской войны (~₩10,000), холодная пшеничная лапша **мильмён** или столик с морепродуктами у гавани. Обед не включён (≈ ₩10,000–15,000), так что вы сами выбираете то, что подходит вашему аппетиту и бюджету."},{"number":6,"time":"≈ 14:10","duration":"20 мин","name":"Пляж Хэундэ","category":"Пляж / Бесплатно","description":"**Пляж Хэундэ (해운대해수욕장)** — самая известная песчаная полоса Кореи: около **1,5 км** береговой линии, изгибающейся между островом Тонбэксом на западе и Мипхо на востоке, со скайлайном Marine City за спиной. Sky Capsule высаживает вас в Мипхо, а это и есть восточный край пляжа, поэтому остановка не стоит дню ни одной лишней минуты дороги.\n\nДвадцать минут — это остановка для фотографий и того, чтобы намочить ноги, а не для купания: выйти на песок, снять скайлайн и вернуться к автобусу. В июле и августе пляж наиболее многолюден и ряды зонтов расставлены; в остальное время года он широкий, тихий и удобный для прогулки. Бесплатно, открыт круглосуточно.","image":null,"highlights":["**Самый знаменитый пляж Кореи** — ~1,5 км песка, БЕСПЛАТНО и круглосуточно","Скайлайн Marine City прямо от кромки воды","Остров Тонбэксом и Nurimaru APEC House на западном краю","Прямо в Мипхо, где заканчивается Sky Capsule — без дополнительного трансфера"],"timeUsed":["Выход на песок из Мипхо (~5 мин)","Фото пляжа и скайлайна (~10 мин)","Сбор у автобуса (~5 мин)"],"whyOnRoute":"Капсула прибывает в Мипхо — восточный край пляжа, так что самый известный вид Пусана в пяти минутах пешком и ничего не стоит дню. Остановка намеренно короткая: ровно чтобы постоять на песке и снять скайлайн, прежде чем день повернёт к деревням на склонах.","_poi_meta":{"match":"authored","poi_key":"haeundae_beach","sources":["Visit Busan","Busan Metropolitan City Tourism"],"verified":false,"verified_date":"2026-08-05"},"visitBasics":{"hours":"Открыт круглосуточно","closed":"Никогда","walking":"Ровный песок и мощёная набережная","admission":"БЕСПЛАТНО"},"images":[],"imageCredits":[],"galleryItems":[]},{"name":"Культурная деревня Камчхон","time":"≈ 15:10","number":7,"category":"Культурная деревня / Фрески","duration":"60 мин","timeUsed":["Высадка на общественной парковке №2 + пешком до входа (~5 мин)","Туристический информационный центр + покупка карты-штампа (~10 мин)","Смотровая «Небесный сад» + скамейка Маленького принца (~20 мин)","Прогулка по переулкам мимо фресок + пауза в маленьком кафе (~20 мин)","Сбор у микроавтобуса (~5 мин)"],"_poi_meta":{"match":"exact","poi_key":"gamcheon_culture_village","sources":["Wikipedia","CNN","Visit Busan","Hapskorea","Columban Society","Lifeguin","Busan Cultural Foundation"],"verified":true,"kb_version":"1.24","verified_date":"2026-04-29"},"highlights":["**«Корейский Мачу-Пикчу» / «корейский Санторини»** — премия UN-HABITAT Asian Townscape Award 2012","Истоки: переселение администрацией Пусана в **1920-1930-е** + **беженцы Тхэгыкто 1955 года** (~800 семей)","**Философия Тхэгыкто «дай процветать другим»** = ни один дом не закрывает вид дому позади","**2009 «Мечтая о Мачу-Пикчу» + 2010 «Миро миро»** — паблик-арт-проекты министерства культуры","**Скамейка «Маленький принц и Лис»** в «Небесном саду» — самое фотографируемое место деревни","**~1,4 миллиона гостей в год** после паблик-арт-возрождения","**Живой жилой квартал** — тихие голоса, без дронов, без вспышки в сторону домов","Вход в деревню бесплатный; карта-штамп по желанию ~₩2,000","**Премия UN-HABITAT Asian Townscape Award 2012** — признание арт-проекта 2009 года «Мечтая о Мачу-Пикчу», превратившего поселение беженцев Тхэгыкто 1955 года в фирменную деревню фресок Пусана"],"smartNotes":{"tip":"Здесь живут люди — говорите тихо, без дронов, уносите мусор с собой; наденьте обувь с цепким протектором для крутых переулков; послеобеденный «золотой час» ~16:00-17:00 — лучший свет в деревне","photo":"Скамейка «Маленький принц и Лис» (длинная очередь) и смотровая «Ханыль Мару» / «Небесный сад» — ради панорамы радужных крыш и залива","facilities":"Прокат ханбока, ремесленные мастерские, лавки корейских сладостей, кафе; небольшой музей деревни у входа; карта-штамп — самый простой способ ориентироваться"},"whyOnRoute":"**Главная деревня второй половины дня — пастельный амфитеатр Пусана.** После прибрежного утра день переходит на западные холмы, где террасы Камчхона, построенные беженцами Корейской войны и возрождённые как арт-деревня в 2009 году, поднимаются леденцовыми красками над морем. 90-минутный маршрут охватывает смотровые точки, уступ с Маленьким принцем и время на прогулку по переулкам — и он намеренно поставлен в пару с тихим Такпатколем сразу после, чтобы вы увидели и знаменитую деревню, и местную, которую автобусы пропускают.","convenience":{"parking":"Общественная парковка Камчхон №2 (платная)","restroom":"Общественные туалеты у туристического информационного центра и у главных смотровых точек"},"description":"**Культурная деревня Камчхон (감천문화마을)** — прозванная и **«корейским Мачу-Пикчу»**, и **«корейским Санторини»** — это квартал на склоне холма в округе Саха-гу на западе Пусана, где дома в пастельных тонах спускаются по склону ступенчатыми рядами. \n\nПоселение возникло в **1920-1930-е годы**, когда администрация Пусана переселяла рабочих подальше от порта. Характер деревни сложился в **1955 году**, когда **~800 семей (около 4 000 человек) религиозной общины Тхэгыкто** — уникальной корейской синкретической религии, соединившей буддийские, конфуцианские и инь-янские элементы и основанной **Чо Чхольчже** в период японской колонизации, — поселились здесь как беженцы Корейской войны с Севера. \n\nФилософия Тхэгыкто «**дай процветать другим**» напрямую сформировала самую характерную черту деревни: дома намеренно поставлены ярусами так, что **ни одна крыша не закрывает вид дому позади**, и вся община открыта небу и морю. Камчхон оставался одним из беднейших кварталов Пусана до **2009 года**, когда министерство культуры Кореи запустило проект паблик-арт-возрождения **«Мечтая о Мачу-Пикчу в Пусане»**, а следом — проект **«Миро миро» («лабиринт») в 2010 году**, добавивший более 22 заказных фресок, скульптур и арт-инсталляций, включая знаменитую **скамейку «Маленький принц и Лис»** на смотровой точке «Небесный сад». \n\nКамчхон получил **премию UN-HABITAT Asian Townscape Award 2012** и теперь принимает **~1,4 миллиона гостей в год**. Визит следует фирменному маршруту с карта-штампами: от входа у **туристического информационного центра** — вверх к смотровой точке **«Небесный сад»** ради панорамного кадра радужных крыш, затем вниз сквозь лабиринт переулков мимо фресок, прокатов ханбока, ремесленных мастерских и маленьких кафе. \n\n**Деревня — живой жилой квартал**: говорите тихо, никаких дронов, не снимайте со вспышкой в сторону домов и уносите мусор с собой. \n\nЧасы работы: **09:00-18:00 март–октябрь / 09:00-17:00 ноябрь–февраль (инфоцентр)**; **сама деревня открыта круглосуточно, вход БЕСПЛАТНЫЙ**.","visitBasics":{"hours":"Ежедневно 09:00–18:00 (март–октябрь) / 09:00–17:00 (ноябрь–февраль); у части магазинов и кафе свои часы","closed":"Открыта круглый год (живой жилой квартал)","walking":"Высокая нагрузка — очень крутые переулки и лестницы; на многих участках не подходит для колясок и инвалидных кресел","admission":"Вход в деревню бесплатный; карта-штамп по желанию ≈ 2,000 KRW"},"image":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","images":["/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp"],"imageCredits":[{"url":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 1","alt":"Gamcheon Culture Village — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/gamcheon-culture-village/chatgpt-image-2026-5-11-01-00-53.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 2","alt":"Gamcheon Culture Village — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-night.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 3","alt":"Gamcheon Culture Village — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/gamcheon-culture-village/gamcheon-little-prince-day-sign.webp","location":"Gamcheon Culture Village","caption":"Gamcheon Culture Village — photo 8","alt":"Gamcheon Culture Village — gallery image 8"}]},{"number":8,"time":"≈ 16:30","duration":"30 мин","name":"Деревня фресок Такпатколь и монорельс у «лестницы желаний»","category":"Деревня фресок / бесплатный монорельс","description":"**Такпатколь (닥밭골)** — деревня на склоне холма в округе Со-гу в Пусане, чьё название хранит память о **полях бумажной шелковицы (так)**, когда-то снабжавших корейских мастеров традиционной бумаги ханчжи. Как и Камчхон, она карабкается по крутому склону тесными переулками — но так и не стала остановкой туристических автобусов, поэтому её **переулки с фресками, работы с мотивами ханчжи и смотровые точки остаются тихими и местными** — с бельевыми верёвками и всем прочим. Достопримечательность деревни — **«лестница желаний» (소망계단)** — длинная крутая лестничная улица, расписанная фресками, — и **бесплатный наклонный монорельс**, скользящий рядом с ней: его установили, чтобы пожилые жители деревни могли добираться до своих домов; на нём катаются и гости, превращая самый крутой подъём второй половины дня в смотровую площадку в замедленном движении. Это намеренно человечный по масштабу контрапункт славе Камчхона — в десяти минутах от зоны высадок.","image":null,"highlights":["**Тихая деревня фресок** — местный двойник Камчхона почти без туристов","Названа в честь **полей бумажной шелковицы (так)** — наследия пусанской бумаги ханчжи","**«Лестница желаний» (소망계단)** — крутая лестничная улица с фресками","**Бесплатный наклонный монорельс** вдоль лестницы — построен для пожилых жителей, открыт для гостей","Смотровые точки на склоне с видом на старый портовый квартал","Вход БЕСПЛАТНЫЙ; по-настоящему жилой квартал — говорите тихо"],"timeUsed":["Высадка из микроавтобуса + прогулка по переулкам с фресками (~10 мин)","Подъём на монорельсе у «лестницы желаний» + смотровая (~10 мин)","Спуск + время на фото (~5 мин)","Сбор у микроавтобуса (~5 мин)"],"whyOnRoute":"**Тихий финал, который автобусы пропускают.** После толп Камчхона Такпатколь показывает тот же холмистый Пусан на «живой громкости» — фрески, лестница желаний и монорельс, который поднимается за вас. Он закрывает главу деревень в десяти минутах от зоны высадки Нампхо, так что день заканчивается в глубине местной жизни, а не в пробке.","_poi_meta":{"match":"authored","poi_key":"dakbatgol_mural_village","sources":["Visit Busan","Busan Seo-gu Office"],"verified":false,"verified_date":"2026-08-04"},"smartNotes":{"tip":"Это жилая деревня, а не тематический парк — говорите тихо в переулках и не фотографируйте в открытые двери домов","photo":"Снимайте «лестницу желаний» снизу, с рельсом монорельса сбоку; верхняя смотровая обрамляет портовый квартал","facilities":"Небольшие кафе у входа; больше вариантов в Нампхо-доне после высадки"},"convenience":{"parking":"Остановка микроавтобуса у входа в деревню","restroom":"Общественный туалет у входа в деревню"},"visitBasics":{"hours":"Открытая деревня; монорельс работает в дневные часы (≈ 09:00–18:00, зависит от погоды)","closed":"Монорельс может останавливаться на обслуживание или в шторм — лестница остаётся открытой","walking":"Крутые переулки и лестницы; самый крутой участок покрывает монорельс","admission":"БЕСПЛАТНО (деревня и монорельс)"},"images":[],"imageCredits":[],"galleryItems":[]},{"number":9,"time":"≈ 17:10","duration":"≈ 70 мин всего","name":"Высадка (4 точки в центре Пусана)","category":"Высадка — последовательно по центральным станциям","description":"**Высадка идёт по порядку с запада обратно на восток**: **Нампхо-дон / Чагальчхи (~17:10)** — здесь выходят ради лучших вечерних улиц еды Пусана и ночной площади BIFF; **вокзал Пусана (~17:30)** для пересадки на KTX; **Сомён (~17:50)** для центрального гостиничного кластера; и **Хэундэ (~18:20)** последним. Согласуйте точку высадки с гидом во второй половине дня — до Хэундэ дорога самая долгая, зато вечер вы начнёте у моря.","image":null,"highlights":[],"timeUsed":["Нампхо-дон / Чагальчхи (~17:10)","Вокзал Пусана (~17:30)","Сомён (~17:50)","Хэундэ (~18:20)"],"whyOnRoute":"Такпатколь в десяти минутах от Нампхо-дона, поэтому высадка начинается почти сразу после последней остановки — без порожнего перегона. Порядок с запада на восток охватывает пассажиров KTX (вокзал Пусана), отели центра (Сомён) и пляжные отели (Хэундэ) без возвратов.","_poi_meta":null,"images":[],"imageCredits":[],"galleryItems":[]}]'::jsonb, true), '{"routeFlowStops"}', '[{"name":"Посадка (ваш отель в центре Пусана)","type":"origin","theme":"Departure"},{"name":"Храм Хэдон Ёнгунса","type":"primary","theme":"Seaside temple"},{"name":"Смотровая площадка Таритдоль в Чхонсапхо (стеклянный скайвок)","type":"secondary","theme":"Glass Skywalk"},{"name":"Sky Capsule парка «Блюлайн» в Хэундэ (Чхонсапхо → Мипхо)","type":"primary","theme":"Sky Capsule"},{"name":"Обед (местный ресторан Пусана)","type":"meal","theme":"Meal"},{"name":"Пляж Хэундэ","type":"secondary","theme":"Beach"},{"name":"Культурная деревня Камчхон","type":"primary","theme":"Art village"},{"name":"Деревня фресок Такпатколь и монорельс у «лестницы желаний»","type":"secondary","theme":"Mural Village"},{"name":"Высадка (4 точки в центре Пусана)","type":"return","theme":"Return"}]'::jsonb, true), '{"routePhases"}', '[{"phase":"Утро на побережье","duration":"≈ 3,5 часа","description":"Посадка от двери до двери у отелей в центре Пусана (09:00–10:00), затем храм Хэдон Ёнгунса до наплыва автобусов и далее стеклянная смотровая Тариттоль в Чхонсапхо."},{"phase":"Sky Capsule, обед и пляж","duration":"≈ 2 часа","description":"Пастельная капсула Sky Capsule из Чхонсапхо в Мипхо (билет по выбору — без него можно ехать на автобусе или пройти по деревянной Green Railway), обед рядом с Хэундэ и затем двадцать минут на самом пляже Хэундэ."},{"phase":"Две деревни на склоне","duration":"≈ 2 часа","description":"Фотомаршрут по культурной деревне Камчхон (60 мин), затем тихая деревня фресок Такпатколь и бесплатный монорельс у «лестницы желаний» (30 мин)."},{"phase":"Завершение в центре","duration":"≈ 1 час","description":"Высадка по порядку: Нампхо-дон, вокзал Пусана, Сомён, затем Хэундэ."}]'::jsonb, true), '{"routeShapeIntro"}', '{"title":"Как устроен этот день в Пусане","subtitle":"Сначала восточное побережье: приморский храм в его тихое утреннее окно, затем кластер Чхонсапхо — стеклянный скайвок, парные маяки, — где сама поездка на Sky Capsule становится трансфером вдоль берега до Мипхо. После обеда и короткой остановки на пляже Хэундэ день переходит на западные холмы Пусана — две деревни в двух настроениях: всемирно известные краски Камчхона, а затем тихие фрески Такпатколя, где бесплатный монорельс скользит вверх вдоль «лестницы желаний». Высадки в центре замыкают маршрут: с 09:00 примерно до 18:20."}'::jsonb, true), '{"whyTourWorks"}', '{"bestFor":["Тем, кто в Пусане впервые","Парам и любителям фотографии","Взрослым семьям и компаниям друзей","Тем, кто хочет увидеть и побережье, И деревни за один день"],"lessIdealFor":["Тем, кто хочет минимум ходьбы и без подъёмов","Группам с колясками (узкие переулки и лестницы в деревнях)","Любителям ночных панорам — это дневной маршрут"],"routeLogicSections":[{"title":"Pacing & geography","icon":"route","iconBg":"bg-sky-50/80","iconColor":"text-sky-600","items":[{"label":"Храм в его тихое окно","detail":"Хэдон Ёнгунса — самый фотографируемый храм Пусана, а наплыв туристических автобусов начинается примерно с 11:00. Приезд около 10:20 оставляет спуск по 108 ступеням и смотровую площадку Хэсу Гванным проходимыми без очередей."},{"label":"Поездка в капсуле И ЕСТЬ трансфер","detail":"От Чхонсапхо пастельная Sky Capsule скользит 2,3 км вдоль побережья до Мипхо — так поездка заменяет переезд на микроавтобусе, а не добавляет крюк. Гости без билета едут до Мипхо на микроавтобусе или идут пешком по бесплатной деревянной набережной-променаду Green Railway вдоль того же берега."},{"label":"Две деревни на холмах, два настроения","detail":"Камчхон — всемирно известный пастельный амфитеатр Пусана; Такпатколь в десяти минутах — его тихий местный двойник: переулки с фресками почти без туристов, где бесплатный наклонный монорельс, построенный для пожилых жителей деревни, поднимает вас вдоль «лестницы желаний»."},{"label":"Бесплатные ключевые точки, один опциональный билет","detail":"Ёнгунса, скайвок Таритдоль, Камчхон и Такпатколь (включая монорельс) — всё бесплатно. Единственная платная достопримечательность дня — Sky Capsule, и это ваш выбор при бронировании: билет включён — или не включён, если вы предпочитаете прогулку по набережной."}]}]}'::jsonb, true), '{"practicalAccordionItems"}', '[{"id":"pickup","title":"Посадка и высадка","preview":"Посадка — от двери до двери у вашего отеля в центре Пусана: Сомён, Нампхо-дон / вокзал Пусана, Хэундэ / Marine City — между 09:00 и 10:00. Точное время подтверждается в WhatsApp накануне вечером.","content":["Посадка — от двери до двери у вашего отеля в центре Пусана: Сомён, Нампхо-дон / вокзал Пусана, Хэундэ / Marine City — между 09:00 и 10:00. Точное время подтверждается в WhatsApp накануне вечером.","Высадка по порядку: Нампхо-дон/Чагальчхи ≈17:10, вокзал Пусана ≈17:30, Сомён ≈17:50, Хэундэ ≈18:20.","Фактическая длительность тура зависит от времени посадки и точки высадки — примерно 7 ч 15 мин в самом коротком варианте (посадка в 10:00, высадка в Нампхо-доне) и примерно 9 ч 15 мин в самом длинном (посадка в 09:00, высадка в Хэундэ)."]},{"id":"what-to-bring","title":"Что надеть и взять с собой","preview":"Удобная обувь с цепкой подошвой — переулки Камчхона на склоне и 108 ступеней Ёнгунса…","content":["Удобная обувь с цепкой подошвой — и переулки Камчхона на склоне, и 108 ступеней Ёнгунса требуют сцепления.","Лёгкий слой одежды — для кондиционера в транспорте и морского бриза у Ёнгунса.","Фотоаппарат или смартфон (Камчхон и Чхонсапхо — главные фототочки).","Наличные или карта — на обед (₩10,000–₩20,000), опциональные билеты на Sky Capsule / пляжный поезд в Чхонсапхо и опциональную смотровую башни Пусана."]},{"id":"weather-policy","title":"Погодная политика","preview":"Работаем круглый год.","content":["Работаем круглый год.","Лёгкий дождь: тур идёт по расписанию — у Ёнгунса под дождём своя атмосфера, а переулки Камчхона остаются проходимыми.","Сильный дождь или шторм: гид может скорректировать маршрут, потому что нижняя часть храма Ёнгунса становится скользкой, а лестницы Камчхона — небезопасными.","Погода уровня тайфуна: предлагается полный возврат или перенос бронирования."]},{"id":"inclusions","title":"What''s included","preview":"Микроавтобус для мини-группы (максимум ≈12 гостей), лицензированный англоговорящий гид, топливо/платные дороги/парковка.","content":["Микроавтобус для мини-группы (максимум ≈12 гостей), лицензированный англоговорящий гид, топливо/платные дороги/парковка.","Все ключевые достопримечательности — с БЕСПЛАТНЫМ входом: Хэдон Ёнгунса, смотровая площадка Таритдоль в Чхонсапхо, культурная деревня Камчхон, деревня фресок Такпатколь (монорельс у «лестницы желаний» бесплатный).","Билет на Sky Capsule: выбор при бронировании — включён (мы заранее резервируем капсулы для вашей группы; из расчёта 2 человека на капсулу) или не включён (прогулка по бесплатной деревянной набережной Green Railway или переезд до Мипхо на микроавтобусе).","Не включено: обед (≈ ₩10,000–15,000), напитки, личные расходы, чаевые."]},{"id":"language","title":"Язык","preview":"Основной язык тура: английский.","content":["Основной язык тура: английский.","Гид с китайским языком — по запросу; бронируйте за 3+ дня.","Корейский звучит весь день — в меню, на вывесках и у лавок; гид берёт перевод на себя."]},{"id":"walking","title":"Walking & terrain","preview":"Умеренная сложность с короткими требовательными отрезками.","content":["Умеренная сложность с короткими требовательными отрезками.","В Ёнгунса — 108 каменных ступеней вниз и обратно вверх.","Скайвок Таритдоль — ровный (стеклянный пол, бахилы выдаются).","Станции Sky Capsule — ровные, лишь несколько ступеней на платформах.","Камчхон — переулки и лестницы на склоне; наденьте удобную обувь.","«Лестница желаний» в Такпатколе крутая, но подъём берёт на себя бесплатный монорельс.","Всего пешком — около 4–5 км."]},{"id":"capsule","title":"Sky Capsule (билет по выбору)","preview":"Включён или не включён — ваш выбор при бронировании.","content":["Sky Capsule проходит 2,3 км по эстакадному рельсу между Чхонсапхо и Мипхо (~30 мин) — пастельные 4-местные кабинки над береговой линией.","Вариант с включённым билетом: мы заранее резервируем капсулы для вашей группы (цена за капсулу ≈ ₩30,000 за 2 чел. / ₩39,000 за 3 / ₩44,000 за 4, в одну сторону; вариант с включённым билетом рассчитан из расчёта 2 человека на капсулу).","Вариант без билета: прогулка по бесплатной деревянной набережной Green Railway (2,3 км, ~30 мин, вдоль того же берега) или переезд до Мипхо на микроавтобусе.","Работа зависит от погоды (при сильном ветре линию останавливают); если капсула не работает, прогулка по набережной и трансфер на микроавтобусе сохраняют график маршрута."]},{"id":"cancellation","title":"Отмена","preview":"Бесплатная отмена до 24 часов до посадки.","content":["Бесплатная отмена до 24 часов до посадки.","Отмена в день тура и неявка не возмещаются."]}]'::jsonb, true), '{"bookingSupportSteps"}', '[{"timing":"Сразу","title":"Мгновенное подтверждение","detail":"Подтверждение бронирования с кратким маршрутом","description":"Мгновенное подтверждение бронирования с указанием окна посадки у отеля (09:00–10:00) и того, чего ожидать."},{"timing":"За день до тура","title":"Детали посадки","detail":"Точное место посадки и данные транспорта через WhatsApp","description":"Накануне приходит проверка погоды и заметки по маршруту (совет о поезде «Дануби» для Тхэчжондэ, время приливов у Ёнгунса)."},{"timing":"Утром в день тура","title":"Подтверждение посадки","detail":"Водитель выходит на связь за 10 минут до прибытия","description":"Номер минивэна и контакт гида подтверждаются накануне вечером."},{"timing":"Во время тура","title":"Поддержка в туре","detail":"Прямая связь с операционной службой","description":"Сообщение накануне вечером подтверждает точное время посадки у отеля; утреннее сообщение — актуальную дорожную обстановку."},{"timing":"В конце дня","title":"Гибкая высадка","detail":"Выберите высадку: Нампхо-дон, вокзал Пусана, Сомён или Хэундэ","description":"Гид рассказывает на месте на каждой остановке — основание Ёнгунса в 1376 году, история 22 наций Мемориального кладбища ООН, происхождение Камчхона как поселения беженцев 1955 года."},{"timing":"После тура","title":"Отзыв и обратная связь","detail":"Отзыв и продолжение общения по желанию","description":"После тура приходит запрос обратной связи; на вопросы о ресторанах Пусана отвечаем в тот же день."}]'::jsonb, true), '{"staticQuestions"}', '[{"question":"Включён ли билет на Sky Capsule?","answer":"На ваш выбор при бронировании. Выберите вариант с включённым билетом — и мы заранее резервируем капсулы для вашей группы (цена за капсулу: около ₩30,000 за 2 чел. / ₩39,000 за 3 / ₩44,000 за 4, в одну сторону — вариант с включённым билетом рассчитан из расчёта 2 человека на капсулу). Выберите базовый вариант — и, пока другие едут в капсуле, вы можете пройтись по бесплатной деревянной набережной Green Railway или доехать до Мипхо на микроавтобусе."},{"question":"Нужно ли бронировать Sky Capsule заранее?","answer":"Слоты на закат и на выходные распродаются за 1–2 недели. Если вы выбрали вариант с включённым билетом, мы оформляем резерв для вашей группы сразу после подтверждения бронирования. Купить билет в кассе в тот же день возможно в спокойные будни, но это не гарантировано."},{"question":"Включён ли обед?","answer":"Нет — обед оплачивается отдельно (около ₩10,000–15,000). Гид порекомендует местные варианты у Хэундэ/Мипхо: твэджи-кукпаб (돼지국밥) — фирменный пусанский суп со свининой и рисом, холодную лапшу мильмён или ресторан морепродуктов."},{"question":"Сколько нужно ходить и насколько крутые подъёмы?","answer":"Умеренно-сложно короткими отрезками: 108 ступеней вниз и обратно вверх в Ёнгунса, ровный стеклянный скайвок на Таритдоль, почти ровные участки у станций капсулы, переулки на склоне в Камчхоне и лестницы в Такпатколе — где бесплатный монорельс поднимается за вас. Общая дистанция пешком — около 4–5 км."},{"question":"Подходит ли тур детям и пожилым?","answer":"Да — для большинства активных путешественников. Детям очень нравятся стеклянный пол и капсула, а монорельс в Такпатколе избавляет от самого крутого подъёма. Лестница в Ёнгунса и склоны Камчхона — два самых требовательных участка: проходите их не спеша и при необходимости пропускайте боковые переулки."},{"question":"Чем этот тур отличается от однодневного тура «Главные достопримечательности Пусана»?","answer":"Тот же оператор, другой фокус. «Главные достопримечательности» охватывают классический городской набор (Мемориальное кладбище ООН, рынок Чагальчхи). Этот маршрут в мини-группе делает ставку на побережье и деревни: отдельная остановка на скайвоке Таритдоль, поездка на Sky Capsule с вариантом включённого билета и тихая деревня фресок Такпатколь, мимо которой большие автобусы проезжают."},{"question":"Где посадка и высадка?","answer":"Посадка — от двери до двери у вашего отеля в центре Пусана, между 09:00 и 10:00; точное время подтверждается в WhatsApp накануне вечером. Высадка по порядку: Нампхо-дон ≈17:10, вокзал Пусана ≈17:30, Сомён ≈17:50, Хэундэ ≈18:20."},{"question":"Что будет, если пойдёт дождь?","answer":"Тур проходит в любую погоду. Капсула и монорельс работают при обычном дожде (останавливаются только при сильном ветре), на скайвоке выдают бахилы, а по переулкам деревень можно гулять с зонтом. При сильной непогоде время на открытых террасах храма может быть сокращено."}]'::jsonb, true), '{"pickup_dropoff"}', '{"departure":[{"order":1,"time":"09:00–10:00","name":"Ваш отель в центре Пусана (от двери до двери)","type":"hotel","note":"Посадка от двери до двери у отелей в центре Пусана — Сомён, Нампхо-дон / вокзал Пусана, Хэундэ / Marine City. Точное время подтверждается накануне вечером.","lat":35.15782,"lng":129.06003}],"return":[{"order":1,"name":"Nampo-dong / Jagalchi area","type":"station","lat":35.09663,"lng":129.0308},{"order":2,"name":"Busan Station (Exit 4)","type":"station","lat":35.11449,"lng":129.03933},{"order":3,"name":"Seomyeon Station (Exit 4)","type":"station","lat":35.15782,"lng":129.06003},{"order":4,"name":"Haeundae Station (Exit 5)","type":"station","lat":35.16396,"lng":129.15853}],"notes":["Посадка — от двери до двери у вашего отеля в центре Пусана между 09:00 и 10:00; точное время подтверждается накануне вечером. Высадка происходит в четырёх центральных точках по порядку (Нампхо-дон → вокзал Пусана → Сомён → Хэундэ, ≈ 17:10–18:20) — скажите гиду днём, какая вам нужна."]}'::jsonb, true), '{"matching_profile"}', '{"profile_version":1,"is_active":true,"product_id":"busan-small-group-yonggungsa-skycapsule-gamcheon-tour","product_type":"small_group","route_type":"fixed_route","destination_region":"busan_city","region_type":"busan_city","vehicle_type":"coach","duration_hours":9,"region_tags":["busan_haeundae","busan_gijang","busan_namgu","busan_saha","busan_jung"],"theme_tags":["temple","coastal","war_memorial","mural_village","fish_market","korean_war_history"],"poi_tags":["haedong_yonggungsa","cheongsapo_daritdol_observatory","cheongsapo_blue_line_park","gamcheon_culture_village","dakbatgol_mural_village"],"pace_level":0.7,"walking_level":0.85,"scenic_level":0.9,"photo_level":1,"culture_level":0.95,"relax_level":0.5,"first_time_fit":1,"family_fit":0.85,"senior_fit":0.7,"couple_fit":0.95,"solo_traveler_fit":0.9,"active_traveler_fit":0.8,"adult_family_fit":1,"family_with_teens_fit":0.95,"young_kids_fit":0.55,"senior_active_fit":0.7,"senior_general_fit":0.55,"mobility_friendly_fit":0.4,"stroller_fit":0.4,"one_day_fit":1,"same_day_flight_fit":0.3,"rain_fit":0.5,"value_for_money_fit":0.95,"iconic_landmark_fit":1,"cafe_fit":0.7,"food_fit":0.8,"nature_fit":0.8,"beach_fit":0.6,"nightlife_fit":0.2,"shopping_fit":0.2,"no_shopping_fit":0.5,"local_culture_fit":1,"storytelling_fit":0.8,"unesco_fit":0,"intangible_heritage_fit":0.2,"indoor_ratio":0.2,"weather_sensitivity":0.5,"comfort_level":0.6,"budget_fit":0.85,"premium_fit":0.3,"small_group_fit":1,"private_fit":0.05,"bus_fit":1,"price_band":"m